local config = {
  ui_story_5086_50860100_1_dialog_content = "... PlayerName, Elvis... aku...",
  ui_story_5086_50860100_2_dialog_content = "Huh... Jeno?",
  ui_story_5086_50860100_3_dialog_content = "Apa yang kamu katakan? Aku tidak bisa mendengarmu...",
  ui_story_5086_50860100_4_dialog_content = "Aku merasakan momen di mana air pasang ajaib naik.",
  ui_story_5086_50860100_5_dialog_content = "Saatnya bagi saya untuk mengejar titik krusial yang ditentukan oleh takdir.",
  ui_story_5086_50860100_6_dialog_content = "Jadi, tolong...",
  ui_story_5086_50860100_7_dialog_content = "Tunggu, Jeno!",
  ui_story_5086_50860100_8_dialog_content = "... Apa barusan aku bermimpi?",
  ui_story_5086_50860100_9_dialog_content = "Mimpi yang aneh dan tidak jelas.",
  ui_story_5086_50860100_10_dialog_content = "Aku bertanya-tanya apakah ini karena surat yang aku terima kemarin?",
  ui_story_5086_50860100_11_dialog_content = "<color=#e8d9bb>\"Maafkan aku telah mengirim surat mendesak seperti ini. Aku meninggalkan pesan untukmu di Harbour City. Tolong datang sendiri untuk menerimanya. —Jeno\"</color>",
  ui_story_5086_50860100_12_dialog_content = "Suratnya juga aneh dan tidak jelas... tapi sepertinya dia bersungguh-sungguh.",
  ui_story_5086_50860100_13_dialog_content = "Dia secara khusus meminta saya untuk datang sendirian... Apakah ini berarti dia tidak ingin saya membawa Vice atau Carleen? Saya bertanya-tanya apa itu...",
  ui_story_5086_50860100_14_dialog_content = "<color=#e8d9bb>Angin laut berhembus lembut saat jalan-jalan di kota yang biasanya damai dipenuhi keramaian turis.</color>",
  ui_story_5086_50860100_15_dialog_content = "Tidak terasa banyak waktu telah berlalu, tetapi tampaknya Harbour City akhirnya telah pulih dari krisis tersebut.",
  ui_story_5086_50860100_16_dialog_content = "Jika saja Elvis ada di sini untuk melihatnya, aku yakin dia akan sangat bangga... Huh?",
  ui_story_5086_50860100_17_dialog_content = "Itu aneh... Emerald berlabuh tepat di sini, bukan?",
  ui_story_5086_50860100_18_dialog_content = "Bagaimana mungkin kapal sebesar itu bisa hilang?",
  ui_story_5086_50860100_19_dialog_content = "Kamu di sini untuk melihat pertunjukan, teman?",
  ui_story_5086_50860100_20_dialog_content = "Membenci untuk memberitahumu, tapi kamu telah melewatkan kesempatanmu. Sirkus telah mengangkat jangkar dan berangkat beberapa hari yang lalu.",
  ui_story_5086_50860100_21_dialog_content = "Lepas landas? Tapi kenapa?",
  ui_story_5086_50860100_22_dialog_content = "Tidak tahu, tapi saya dengar itu ada hubungannya dengan seseorang yang terluka dalam kekacauan sebelumnya.",
  ui_story_5086_50860100_23_dialog_content = "Tidak, tidak, kamu salah paham semua!",
  ui_story_5086_50860100_24_dialog_content = "Setiap orang tahu bahwa pemimpin sirkus telah terlibat pertengkaran besar dengan kekasihnya, jadi dia berlayar untuk mencari mereka!",
  ui_story_5086_50860100_25_dialog_content = "Apa? Saya pikir itu karena binatang ajaib telah melarikan diri dari kapal!",
  ui_story_5086_50860100_26_dialog_content = "Kalian semua melihatnya, bukan? Paus besar itu yang memimpin jalan!",
  ui_story_5086_50860100_27_dialog_content = "Yah, mereka memang pergi dengan tergesa-gesa... Itu pasti.",
  ui_story_5086_50860100_28_dialog_content = "Aku hanya berharap tidak ada hal buruk yang terjadi.",
  ui_story_5086_50860100_29_dialog_content = "Jadi, di mana saya seharusnya menemukan Jeno sekarang?",
  ui_story_5086_50860100_30_dialog_content = "Surat itu tidak mengatakan... Tunggu, ada alamat yang tertulis di belakang! Sepertinya saya tidak menyadarinya sebelumnya.",
  ui_story_5086_50860100_31_dialog_content = "130 Coral Street—",
  ui_story_5086_50860100_32_dialog_content = "Selamat datang di keajaiban bawah laut Kota Pelabuhan, tempat di mana mimpi dan laut bertemu!",
  ui_story_5086_50860100_33_dialog_content = "Apakah kamu ingin berenang bersama hiu?",
  ui_story_5086_50860100_34_dialog_content = "Atau mungkin santai dan bersantai bersama kura-kura laut?",
  ui_story_5086_50860100_35_dialog_content = "Kamu bahkan bisa bergabung dengan ubur-ubur tersebut dan meniup gelembung yang indah!",
  ui_story_5086_50860100_36_dialog_content = "Segalanya mungkin di tempat fantastis ini!",
  ui_story_5086_50860100_37_dialog_content = "... Sebuah akuarium?",
  ui_story_5086_50860100_38_dialog_content = "Benar, sebuah akuarium!",
  ui_story_5086_50860100_39_dialog_content = "Kami memiliki berbagai jenis makhluk laut yang imut yang pasti akan menarik hati Anda! Apakah ini kunjungan pertama Anda di sini?",
  ui_story_5086_50860100_40_dialog_content = "Jika begitu, bolehkah saya menyarankan untuk mulai dari sisi kiri lantai pertama...",
  ui_story_5086_50860100_41_dialog_content = "Er... Apa yang dipajang di sana tadi? Maaf, ingatan jangka pendekku sangat buruk. Biarkan aku cek catatanku...",
  ui_story_5086_50860100_42_dialog_content = "Uh, saya di sini bukan untuk—",
  ui_story_5086_50860100_43_dialog_content = "Aha, itu dia! Itu pameran terumbu karang!",
  ui_story_5086_50860100_44_dialog_content = "Kami juga mengadakan acara interaktif hari ini! Tamu-tamu dapat menyentuh beberapa bintang laut di sana, sementara anak-anak sepuluh tahun ke bawah gratis!",
  ui_story_5086_50860100_45_dialog_content = "Saya pasti terlihat lebih tua dari sepuluh tahun, menurutmu tidak?",
  ui_story_5086_50860100_46_dialog_content = "Hmm... Kurasa begitu.",
  ui_story_5086_50860100_47_dialog_content = "Mari kita coba ini sebagai gantinya!",
  ui_story_5086_50860100_48_dialog_content = "<color=#e8d9bb>Gadis muda itu tiba-tiba menutupi mata kanannya dengan tangannya.</color>",
  ui_story_5086_50860100_49_dialog_content = "Karena saya hanya bisa melihat setengah dari kamu, itu berarti saya harus menganggap kamu setengah dari usia normalmu!",
  ui_story_5086_50860100_50_dialog_content = "Bagus, sekarang kamu bisa masuk secara gratis!",
  ui_story_5086_50860100_51_dialog_content = "Maaf, Nona... Maya, bukan? Saya menghargai niatnya, tapi saya datang ke sini untuk urusan yang cukup serius. Kalau Anda memaafkan saya—",
  ui_story_5086_50860100_52_dialog_content = "<color=#e8d9bb>Brak!</color>",
  ui_story_5086_50860100_53_dialog_content = "Ah! Aku sangat menyesal!",
  ui_story_5086_50860100_54_dialog_content = "Suara itu...",
  ui_story_5086_50860100_55_dialog_content = "Maafkan saya, Nona, tapi teman saya tidak sengaja menjatuhkan tanda display Anda di pintu masuk.",
  ui_story_5086_50860100_56_dialog_content = "Mohon izinkan kami untuk sepenuhnya mengganti kerugian Anda.",
  ui_story_5086_50860100_57_dialog_content = "Tidak apa-apa, aku hanya menggambar tanda itu sendiri. Aku hanya senang tidak ada satu pun dari kalian yang terluka.",
  ui_story_5086_50860100_58_dialog_content = "Saya benar-benar, sungguh minta maaf tentang ini...",
  ui_story_5086_50860100_59_dialog_content = "Minos! Sanae! Itu benar-benar kamu berdua!",
  ui_story_5086_50860100_60_dialog_content = "Tuan PlayerName! Aku tak menyangka akan bertemu denganmu di sini... Ah! Maaf, itu bukan cara menyapa seorang teman!",
  ui_story_5086_50860100_61_dialog_content = "Um, b-bagaimana kabarmu...",
  ui_story_5086_50860100_62_dialog_content = "Saya baik-baik saja, Sanae. Senang melihat Anda dan Minos lagi.",
  ui_story_5086_50860100_63_dialog_content = "Selamat siang, Bapak PlayerName. Senang melihat Anda baik-baik saja setelah sekian lama.",
  ui_story_5086_50860100_64_dialog_content = "Bukankah Nina bersama kalian?",
  ui_story_5086_50860100_65_dialog_content = "Saya takut bukan... Nona Nina saat ini sedang sibuk dengan desain baru... jadi dia meminta saya untuk... melakukan investigasi industri di tempatnya.",
  ui_story_5086_50860100_66_dialog_content = "Memang. Saya, di sisi lain, di sini untuk membantu dalam hal ini.",
  ui_story_5086_50860100_67_dialog_content = "... Yakin kamu tidak salah peran?",
  ui_story_5086_50860100_68_dialog_content = "Jangan khawatir, Tuan. Meski Sanae masih harus banyak belajar sebagai pembantu—",
  ui_story_5086_50860100_69_dialog_content = "Sebagai seseorang yang seumuran dengan wanita muda kita, dia kebetulan juga memiliki sejumlah kepekaan bangsawan yang sama dengannya.",
  ui_story_5086_50860100_70_dialog_content = "Yang paling penting, bagaimanapun, adalah fakta bahwa Nona Nina bersedia menaruh kepercayaannya pada dirinya.",
  ui_story_5086_50860100_71_dialog_content = "Selama dia terus memenuhi harapan lady kami, saya tidak memiliki alasan untuk mengganggu tugas-tugasnya.",
  ui_story_5086_50860100_72_dialog_content = "Nyonya saya ingin terlibat dalam industri ini, tetapi sebagai kepala pelayan keluarga Andersen, jika saya menemukan bahwa ada terlalu banyak faktor yang tidak stabil...",
  ui_story_5086_50860100_73_dialog_content = "Tatapan di matamu tiba-tiba menjadi lebih menakutkan, Minos.",
  ui_story_5086_50860100_74_dialog_content = "Begitu ya? Lalu mohon maafkan kekasaran saya. Saya hanya bermaksud bahwa saya akan mengambil tindakan korektif jika itu memang kasusnya.",
  ui_story_5086_50860100_75_dialog_content = "<color=#e8d9bb>Tiba-tiba, terdengar keributan keras tepat di luar pintu—</color>",
  ui_story_5086_50860100_76_dialog_content = "Apa yang terjadi di luar sana?",
  ui_story_5086_50860100_77_dialog_content = "Maya, cepat datang! Beberapa orang yang mencurigakan mencoba masuk ke akuarium!",
  ui_story_5086_50860100_78_dialog_content = "<color=#e8d9bb>Sejumlah anak-anak muncul di pintu, dengan panik menghalangi dua orang yang berpakaian tebal untuk masuk.</color>",
  ui_story_5086_50860100_79_dialog_content = "Skado! Sebastian! Formasi pertahanan! Jangan biarkan kedua orang itu menerobos lobi!",
  ui_story_5086_50860100_80_dialog_content = "Lebih mudah diucapkan daripada dilakukan, Froude! Si pendek seharusnya bukan masalah, tapi bagaimana kita bisa menghentikan orang tinggi itu masuk?",
  ui_story_5086_50860100_81_dialog_content = "Tikus... Apakah ini benar-benar akhirnya?",
  ui_story_5086_50860100_82_dialog_content = "Heheheh, kalian anak-anak sangat enerjik, tapi saya bisa menjamin, kami bukan orang jahat.",
  ui_story_5086_50860100_83_dialog_content = "Itulah yang akan dikatakan oleh seorang penjahat!",
  ui_story_5086_50860100_84_dialog_content = "Lagipula, siapa yang memakai pakaian sebanyak ini ke akuarium saat cuaca di luar sangat panas?",
  ui_story_5086_50860100_85_dialog_content = "Jika kamu tidak bisa menghargai kekerenan pakaian kami, maka kamu masih memiliki jalan panjang sebelum bisa menyebut dirimu seorang bajingan seperti kami.",
  ui_story_5086_50860100_86_dialog_content = "Swash-apa sekarang?",
  ui_story_5086_50860100_87_dialog_content = "Apa—Maksudmu kamu tidak tahu tentang profesi paling keren di dunia? Maka izinkan saya untuk—",
  ui_story_5086_50860100_88_dialog_content = "Baiklah kalian berdua, itu sudah cukup sekarang.",
  ui_story_5086_50860100_89_dialog_content = "!",
  ui_story_5086_50860100_90_dialog_content = "<color=#e8d9bb>Di suatu titik selama mereka berbickering, Maya entah bagaimana berhasil muncul di belakang mereka.</color>",
  ui_story_5086_50860100_91_dialog_content = "<color=#e8d9bb>Dengan satu gerakan lincah, dia merampas kacamata hitam dan topeng mereka dari wajah mereka.</color>",
  ui_story_5086_50860100_92_dialog_content = "Goldie? Sadie?",
  ui_story_5086_50860100_93_dialog_content = "Oh, tidak...",
  ui_story_5086_50860100_94_dialog_content = "Dia menyelinap mendekati kami tanpa menarik perhatian kami sama sekali! Siapa sebenarnya kamu?",
  ui_story_5086_50860100_95_dialog_content = "Namaku Maya. Saya adalah karyawan di akuarium ini.",
  ui_story_5086_50860100_96_dialog_content = "Maaf, tapi saya harus meminta Anda untuk menghindari memakai pakaian yang tampak menakutkan di sini. Ada banyak anak-anak yang berlarian di sekitar akuarium, tahu.",
  ui_story_5086_50860100_97_dialog_content = "Lagipula, bukankah kamu lebih suka melihat semua makhluk laut yang cantik tanpa harus memakai semua ini?",
  ui_story_5086_50860100_98_dialog_content = "Huuh, saya tidak datang ke sini untuk bersenang-senang.",
  ui_story_5086_50860100_99_dialog_content = "Saya mendengar tentang sesuatu yang mengerikan terjadi di Harbour City. Sebagai seorang bajak laut yang mulia, saya datang ke sini untuk menjalankan keadilan!",
  ui_story_5086_50860100_100_dialog_content = "Sesuatu yang mengerikan? Di Harbour City?",
  ui_story_5086_50860100_101_dialog_content = "Tolong jangan menyinggung tamu-tamu kami, Maya.",
  ui_story_5086_50860100_102_dialog_content = "Tetapi Nona Stellandine—",
  ui_story_5086_50860100_103_dialog_content = "Mohon maaf, semua orang. Nama saya Stellandine, dan saya adalah pemilik dari akuarium ini.",
  ui_story_5086_50860100_104_dialog_content = "Karyawan saya bisa bertindak sedikit terburu-buru kadang-kadang. Saya minta maaf jika ini berdampak negatif pada kunjungan Anda ke tempat kami hari ini.",
  ui_story_5086_50860100_105_dialog_content = "Tidak, kami juga salah di sini.",
  ui_story_5086_50860100_106_dialog_content = "Kemudian sebagai pemilik akuarium, izinkan saya untuk menjamu kalian semua makan sebagai tanda permintaan maaf kami.",
  ui_story_5086_50860100_107_dialog_content = "Sebelum itu, jangan ragu untuk mengamati setiap pameran yang kami tawarkan.",
  ui_story_5086_50860100_108_dialog_content = "Tapi seperti yang Maya katakan, banyak tamu kami adalah anak-anak kecil, jadi tolong hindari perilaku apa pun yang mungkin membuat mereka terganggu.",
  ui_story_5086_50860100_109_dialog_content = "Jika Anda memiliki pertanyaan lebih lanjut, Anda dapat bertanya kepada saya kapan saja.",
  ui_story_5086_50860100_110_dialog_content = "Kami tidak akan mengganggu tontonanmu lagi. Ayo, Maya.",
  ui_story_5086_50860100_111_dialog_content = "Tapi tanda display di pintu masuk...",
  ui_story_5086_50860100_112_dialog_content = "Aku masih perlu menyortir beberapa berkas. Bisakah kamu tolong bantu aku dengan ini?",
  ui_story_5086_50860100_113_dialog_content = "Tentu saja! Serahkan saja padaku!",
  ui_story_5086_50860100_114_dialog_content = "Betapa baik hatinya Bos.",
  ui_story_5086_50860100_115_dialog_content = "Pokoknya, begitu banyak wajah yang familiar di sini hari ini.",
  ui_story_5086_50860100_116_dialog_content = "Terakhir kali sesuatu seperti ini terjadi adalah di Rumah Hantu Andersen, dan kemudian...",
  ui_story_5086_50860100_117_dialog_content = "Meskipun saya tidak berpikir hal seperti itu akan terjadi lagi, saya harus bertanya tentang itu hanya untuk berjaga-jaga.",
  ui_story_5086_50860100_118_dialog_content = "Hei Sadie, apa hal mengerikan ini yang kamu dengar?",
  ui_story_5086_50860100_119_dialog_content = "Ah ya, hal yang mengerikan itu! Setiap swashbuckler sejati akan datang berlari bahkan pada petunjuk masalah yang paling samar sekalipun!",
  ui_story_5086_50860100_120_dialog_content = "Jadi... Apakah itu berarti kamu datang ke sini hanya karena mendengar sebuah rumor?",
  ui_story_5086_50860100_121_dialog_content = "Mungkin itu hanya rumor, tapi melihat adalah percaya setelah semua.",
  ui_story_5086_50860100_122_dialog_content = "Jika ada tanda bahaya, saya memiliki kewajiban untuk menghadapinya. Meskipun ternyata hanya rumor, saya tidak akan merasa tenang sampai saya melihat kebenaran dengan mata kepala sendiri.",
  ui_story_5086_50860100_123_dialog_content = "Mencegah bahkan krisis yang paling tidak mungkin terjadi adalah semua bagian dari menjadi seorang swashbuckler!",
  ui_story_5086_50860100_124_dialog_content = "Kenyataannya, kami memang menemukan sejumlah rumor yang mengganggu.",
  ui_story_5086_50860100_125_dialog_content = "Tetapi setiap cerita sedikit berbeda dari yang sebelumnya. Beberapa orang mengklaim bahwa seekor paus raksasa bersembunyi di perairan Harbour City, menunggu untuk menelan siapa saja yang cukup bodoh untuk berenang di laut.",
  ui_story_5086_50860100_126_dialog_content = "Orang lain mengklaim bahwa orang-orang terus menghilang setelah mengambil kartu aneh yang tersebar di sekitar kota.",
  ui_story_5086_50860100_127_dialog_content = "Sangat sulit untuk mencari tahu kebenaran langsung dari Umbraton, jadi Sadie bersikeras untuk datang ke sini dan memeriksa segalanya sendiri.",
  ui_story_5086_50860100_128_dialog_content = "Selalu ada kemungkinan ini akan membawa kita ke pertempuran yang mulia dan menentukan, satu yang akan membuat namaku terkenal di seluruh negeri.",
  ui_story_5086_50860100_129_dialog_content = "Saya sedikit khawatir tentang Sadie yang datang ke sini sendirian, jadi saya memutuskan untuk ikut serta.",
  ui_story_5086_50860100_130_dialog_content = "Tapi sungguh, kami tidak menyangka akan bertemu denganmu di sini, PlayerName. Betapa kebetulan yang menyenangkan!",
  ui_story_5086_50860100_131_dialog_content = "Saya lihat Pak Minos juga di sini, kita sebaiknya pergi menyapa. Mau ikut, PlayerName?",
  ui_story_5086_50860100_132_dialog_content = "Sebenarnya, ada hal penting yang harus saya tangani sekarang.",
  ui_story_5086_50860100_133_dialog_content = "Baiklah, semoga kita bisa bertemu lagi nanti!",
  ui_story_5086_50860100_134_dialog_content = "Siap.",
  ui_story_5086_50860100_135_dialog_content = "(Jika saja aku bisa menemukan pesan dari Jeno seperti ini juga.)",
  ui_story_5086_50860201_1_dialog_content = "Ini melelahkan.",
  ui_story_5086_50860201_2_dialog_content = "Saya telah berputar-putar sepanjang hari, tetapi saya masih belum menemukan apa-apa.",
  ui_story_5086_50860201_3_dialog_content = "Mungkin aku akan pergi beristirahat di area istirahat untuk sekarang.",
  ui_story_5086_50860201_4_dialog_content = "Jeno mengatakan bahwa dia meninggalkan pesan untukku di sini, yang berarti dia kemungkinan besar mempercayakannya kepada seseorang.",
  ui_story_5086_50860201_5_dialog_content = "Karena dia juga mencantumkan alamat akuarium ini, itu pasti berarti bahwa orang ini ada di sekitar sini.",
  ui_story_5086_50860201_6_dialog_content = "Itulah dua petunjuk yang sekarang aku punya.",
  ui_story_5086_50860201_7_dialog_content = "Saya cukup yakin ini hanya kebetulan bahwa begitu banyak teman saya juga di sini, tapi mungkin salah satu dari mereka adalah kurir? Jika iya, apakah saya harus bertanya kepada mereka tentang itu?",
  ui_story_5086_50860201_8_dialog_content = "Tidak, itu akan mengalahkan tujuan menjaga segalanya menjadi rahasia. Itu tidak berbeda dengan memberi tahu semua orang di Astra tentang hal itu.",
  ui_story_5086_50860201_9_dialog_content = "Itu menandai akhir acara interaktif hari ini, setiap orang! Saatnya bintang laut cantik kita pulang untuk istirahat yang pantas.",
  ui_story_5086_50860201_10_dialog_content = "Ini juga waktu bagi kalian, anak-anak, untuk pulang. Ingat untuk tidak bermain di jalan saat kembali.",
  ui_story_5086_50860201_11_dialog_content = "Aww! Tapi ini masih sangat pagi! Aku belum ingin pulang! Dan kamu masih belum menceritakan kisah kepada kami!",
  ui_story_5086_50860201_12_dialog_content = "Ceritamu selalu sangat menyenangkan, Maya!",
  ui_story_5086_50860201_13_dialog_content = "Aku juga mau dengar satu.",
  ui_story_5086_50860201_14_dialog_content = "Kamu berjanji akan menceritakan sebuah cerita minggu lalu, tapi sepertinya kamu sudah lupa tentang itu, Maya.",
  ui_story_5086_50860201_15_dialog_content = "Oh, apakah begitu? Aku pasti benar-benar lupa... Maaf.",
  ui_story_5086_50860201_16_dialog_content = "Kemarilah duduk bersama kami, Maya.",
  ui_story_5086_50860201_17_dialog_content = "Baiklah, aku akan menceritakan sebuah kisah yang kubaca beberapa hari lalu, tetapi setelah itu, kamu harus langsung pulang. Deal?",
  ui_story_5086_50860201_18_dialog_content = "Oke!",
  ui_story_5086_50860201_19_dialog_content = "Dahulu kala, ada seorang anak laki-laki yang tersesat selama perjalanannya...",
  ui_story_5086_50860201_20_dialog_content = "(Yah, Jeno mungkin tidak tahu kapan saya akan mencari pesannya.)",
  ui_story_5086_50860201_21_dialog_content = "(Lebih baik mempercayakannya kepada seorang pelancong, dia kemungkinan besar memilih seseorang yang hampir selalu berada di akuarium.)",
  ui_story_5086_50860201_22_dialog_content = "(Selain Maya, satu-satunya orang lain yang cocok adalah pemilik penginapan...)",
  ui_story_5086_50860201_23_dialog_content = "(Setelah dia selesai menceritakan ceritanya, aku akan mencoba membicarakannya secara halus.)",
  ui_story_5086_50860201_24_dialog_content = "Dia melakukan perjalanan melalui hutan yang lebat dan gurun yang kosong dan bahkan mencapai tepi laut di ujung dunia. Namun sepanjang waktu, dia tidak pernah bisa mengetahui arah mana yang dia tuju.",
  ui_story_5086_50860201_25_dialog_content = "Bagiku, dia terdengar agak konyol.",
  ui_story_5086_50860201_26_dialog_content = "Jika aku dia, aku akan membawa banyak peta bersamaku agar tidak pernah tersesat.",
  ui_story_5086_50860201_27_dialog_content = "Aku mengerti! Kamu suka mempersiapkan segalanya, bukan Skado?",
  ui_story_5086_50860201_28_dialog_content = "Tapi anak laki-laki dalam cerita ini tidak begitu beruntung.",
  ui_story_5086_50860201_29_dialog_content = "Meskipun biasanya dia dikelilingi oleh teman-temannya, ada beberapa perjalanan yang harus dia hadapi sendiri.",
  ui_story_5086_50860201_30_dialog_content = "Tapi untungnya, seekor kucing kecil muncul untuk menyelamatkannya dari kesepiannya.",
  ui_story_5086_50860201_31_dialog_content = "Ini adalah kucing yang sangat ramah. Dengan tidak ada yang lain untuk dilakukan, anak laki-laki itu memutuskan untuk bermain dengannya.",
  ui_story_5086_50860201_32_dialog_content = "Jadi kedua orang itu berjalan-jalan di sepanjang pantai dan menonton ombak berbusa yang pecah di atas terumbu karang.",
  ui_story_5086_50860201_33_dialog_content = "Mereka menonton saat ikan terbang melompat keluar dari air dengan suara mendesing.",
  ui_story_5086_50860201_34_dialog_content = "Mereka berguling di pasir dan tertawa saat mereka melihat kepiting yang canggung berjalan bolak-balik.",
  ui_story_5086_50860201_35_dialog_content = "Di akhir hari, mereka meringkuk di bawah pohon palem dan membiarkan angin laut yang lembut membawa mereka terlelap.",
  ui_story_5086_50860201_36_dialog_content = "Itu terdengar begitu bagus!",
  ui_story_5086_50860201_37_dialog_content = "Ketika anak laki-laki itu bangun, dia terkejut melihat sebuah kota kecil di depan matanya.",
  ui_story_5086_50860201_38_dialog_content = "Saya bilang itu adalah kota kecil, tapi sepadat kota besar. Ada toko senjata, toko barang, dan berbagai jenis penginapan.",
  ui_story_5086_50860201_39_dialog_content = "Jalan-jalan dipenuhi dengan petualang berani yang dilengkapi dengan segala jenis senjata dan baju besi, serta pelancong dengan pakaian yang indah.",
  ui_story_5086_50860201_40_dialog_content = "Faktanya, ada monster laut yang bersembunyi di suatu tempat di kota itu.",
  ui_story_5086_50860201_41_dialog_content = "Selama siang hari, segalanya sangat damai. Tapi di malam hari, suara tangisan bisa terdengar datang dari laut.",
  ui_story_5086_50860201_42_dialog_content = "Suara itu sangat menakutkan, jadi setiap orang mengira itu adalah tangisan monster laut.",
  ui_story_5086_50860201_43_dialog_content = "Pasti itulah sebabnya banyak petualang di kota itu! Saya yakin mereka berpikir bahwa siapa pun yang mengalahkan monster itu bisa mengklaim harta karunnya!",
  ui_story_5086_50860201_44_dialog_content = "Itu masuk akal, karena ada banyak orang yang berpikir seperti kamu, Froude. Tapi mengapa ada begitu banyak pelancong juga?",
  ui_story_5086_50860201_45_dialog_content = "Jika ada monster di kota itu, saya tidak akan pernah ingin pergi ke sana untuk apapun.",
  ui_story_5086_50860201_46_dialog_content = "Mungkin karena monster itu tidak pernah menunjukkan wajah aslinya, meskipun tangisannya sangat menakutkan. Tidak peduli berapa banyak orang yang datang, ia tidak pernah muncul di depan siapa pun.",
  ui_story_5086_50860201_47_dialog_content = "Meskipun ada banyak orang yang mengaku telah melihat monster itu, sisanya dari kota mengetahui bahwa mereka semua berbohong.",
  ui_story_5086_50860201_48_dialog_content = "Jadi, rumor tentang monster menakutkan itu hanya semakin buruk.",
  ui_story_5086_50860201_49_dialog_content = "(Hey, aku juga pernah baca cerita itu sebelumnya.)",
  ui_story_5086_50860201_50_dialog_content = "(Jika saya tidak salah ingat, ceritanya berakhir dengan anak laki-laki dan kucing menemukan sebuah gua tersembunyi.)",
  ui_story_5086_50860201_51_dialog_content = "(Alih-alih menemukan monster laut di sana, yang mereka temukan hanyalah seorang gadis kecil menangis sendirian.)",
  ui_story_5086_50860201_52_dialog_content = "(Dia tidak memiliki keluarga atau teman, jadi dia menghabiskan setiap malam menangis sendirian di gua itu.)",
  ui_story_5086_50860201_53_dialog_content = "(Isak tangisnya yang pelan bergema melalui gua hingga seluruh kota bisa mendengarnya, inilah yang memulai rumor tentang monster laut.)",
  ui_story_5086_50860201_54_dialog_content = "(Anak lelaki itu menghiburnya dan berjanji akan menjadi temannya.)",
  ui_story_5086_50860201_55_dialog_content = "(Setelah itu, desa tidak pernah mendengar \"monster laut\" di malam hari, tapi...)",
  ui_story_5086_50860201_56_dialog_content = "Namun...",
  ui_story_5086_50860201_57_dialog_content = "(Hah? Dia sudah sampai di bagian ini dari ceritanya?)",
  ui_story_5086_50860201_58_dialog_content = "Sayangnya, aku tidak ingat sisanya dari cerita itu!",
  ui_story_5086_50860201_59_dialog_content = "Pffft! Uhuk, uhuk...",
  ui_story_5086_50860201_60_dialog_content = "Sudah kuduga...",
  ui_story_5086_50860201_61_dialog_content = "Ini sama sekali tidak mengejutkan...",
  ui_story_5086_50860201_62_dialog_content = "Tidak apa-apa, kami sudah terbiasa.",
  ui_story_5086_50860201_63_dialog_content = "Kita semua tahu betapa buruknya ingatan Maya, setelah semua. Kadang dia bahkan lupa hal-hal yang terjadi lima menit yang lalu.",
  ui_story_5086_50860201_64_dialog_content = "Ini benar-benar membuat kami khawatir.",
  ui_story_5086_50860201_65_dialog_content = "Hahaha, aku tidak benar-benar yakin bagaimana harus melanjutkan...",
  ui_story_5086_50860201_66_dialog_content = "Apa yang akan kalian lakukan, anak-anak, jika berada di posisi anak laki-laki itu?",
  ui_story_5086_50860201_67_dialog_content = "Oh, aku tahu! Aku akan langsung pergi ke toko senjata untuk membeli pedang dan perisai baru!",
  ui_story_5086_50860201_68_dialog_content = "Aku tidak suka bertarung, tapi aku akan membeli beberapa obat penyembuh hanya untuk berjaga-jaga.",
  ui_story_5086_50860201_69_dialog_content = "Kalian berdua membuat poin yang bagus. Saya yakin anak laki-laki itu juga berpikir begitu.",
  ui_story_5086_50860201_70_dialog_content = "(Tidak sama sekali! Dan kapan ini berubah menjadi cerita fantasi tingkat tinggi?)",
  ui_story_5086_50860201_71_dialog_content = "Setelah membeli perlengkapan lengkap, anak laki-laki itu berangkat ke sarang monster laut dan menantangnya untuk pertempuran terakhir.",
  ui_story_5086_50860201_72_dialog_content = "Dia menjalani bertahun-tahun pelatihan dan mengatasi berbagai rintangan—",
  ui_story_5086_50860201_73_dialog_content = "(Cerita ini hanya berlangsung di sebuah kota kecil, meskipun begitu!)",
  ui_story_5086_50860201_74_dialog_content = "Monster laut raksasa itu akhirnya mengakui kekuatan dan keberanian anak laki-laki itu, dan dengan itu ia bangkit dari kedalaman untuk menerima tantangannya!",
  ui_story_5086_50860201_75_dialog_content = "Kamu ingin mengklaim harta karunku? Maka kamu harus mengalahkanku dalam pertempuran terlebih dahulu!",
  ui_story_5086_50860201_76_dialog_content = "Monster laut itu tertawa sombong pada anak laki-laki kecil itu.",
  ui_story_5086_50860201_77_dialog_content = "(Saya pasti pernah membaca kalimat-kalimat ini di tempat lain sebelumnya! Dia mulai menceritakan cerita yang benar-benar berbeda!)",
  ui_story_5086_50860201_78_dialog_content = "Wow!",
  ui_story_5086_50860201_79_dialog_content = "Dan begitu anak laki-laki itu menarik pedangnya dan melibatkan binatang raksasa itu dalam satu pertempuran terakhir!",
  ui_story_5086_50860302_1_dialog_content = "<color=#e8d9bb>Ketika anak-anak bersorak gembira mendengar cerita Maya, beberapa orang lagi memasuki area istirahat.</color>",
  ui_story_5086_50860302_2_dialog_content = "Sepertinya kita bisa istirahat sebentar di sini, Sadie.",
  ui_story_5086_50860302_3_dialog_content = "Tapi kami masih belum menemukan petunjuk apa pun mengenai hal buruk yang terjadi di sini!",
  ui_story_5086_50860302_4_dialog_content = "Mungkin tampak tenang dan damai di sekitar sini, tetapi mungkin ada orang yang sangat membutuhkan bantuan kita sekarang. Kita tidak bisa mengendur.",
  ui_story_5086_50860302_5_dialog_content = "Aku tahu bagaimana perasaanmu, tapi kau telah berlarian ke sana kemari sejak bangun pagi ini.",
  ui_story_5086_50860302_6_dialog_content = "Kami hampir mencari setengah kota untuk tanda-tanda bahaya. Dengan kecepatan ini, kami akan kehabisan tenaga sebelum kami berhasil membantu siapa pun.",
  ui_story_5086_50860302_7_dialog_content = "Menjaga keseimbangan antara kerja dan istirahat, tetap dalam kondisi fisik terbaik—",
  ui_story_5086_50860302_8_dialog_content = "Itulah bagaimana idola tetap di puncak permainan mereka... dan saya yakin hal yang sama berlaku untuk bajingan.",
  ui_story_5086_50860302_9_dialog_content = "Goldie...",
  ui_story_5086_50860302_10_dialog_content = "Benda apa?",
  ui_story_5086_50860302_11_dialog_content = "Kata-katamu barusan... Sebenarnya itu cukup keren.",
  ui_story_5086_50860302_12_dialog_content = "Aku mengerti. Aku akan beristirahat sebaik mungkin sekarang juga!",
  ui_story_5086_50860302_13_dialog_content = "Uh, baiklah. Mari kita habiskan beberapa jam ke depan untuk memulihkan kekuatan kita.",
  ui_story_5086_50860302_14_dialog_content = "Kami sudah memantau Harbour City di siang hari, jadi mungkin langkah selanjutnya adalah mengawasi kota di malam hari.",
  ui_story_5086_50860302_15_dialog_content = "Setelah semua, banyak hal hanya menunjukkan diri mereka di balik selimut kegelapan.",
  ui_story_5086_50860302_16_dialog_content = "Saya sendiri tidak bisa mengatakannya dengan lebih baik, Nona Goldie.",
  ui_story_5086_50860302_17_dialog_content = "Sanae, kamu akan baik-baik saja melakukan observasi malam hari juga.",
  ui_story_5086_50860302_18_dialog_content = "Ah... Mengerti! Begitu kita kembali... Tidak, aku akan langsung mulai merencanakan tugas penyelidikan baruku sekarang juga!",
  ui_story_5086_50860302_19_dialog_content = "Aku berniat untuk bertanya tentang itu sebelumnya.",
  ui_story_5086_50860302_20_dialog_content = "Apa yang sebenarnya kalian selidiki? Industri baru apa yang coba ditembus Nina?",
  ui_story_5086_50860302_21_dialog_content = "Saya minta kamu untuk tidak mencari jawaban dariku, Sanae. Ini adalah tugas kamu, setelah semua.",
  ui_story_5086_50860302_22_dialog_content = "Uh... O-oke, kalau begitu, biar kujelaskan...",
  ui_story_5086_50860302_23_dialog_content = "Yah, um, kamu lihat, Nona Nina mengatakan bahwa seorang pebisnis sejati tidak hanya berpegang pada satu industri, dan jadi...",
  ui_story_5086_50860302_24_dialog_content = "Dan jadi, dia ingin menciptakan rantai bisnis dengan mengembangkan lebih jauh dari rumah hantu.",
  ui_story_5086_50860302_25_dialog_content = "Banyak perubahan yang terjadi di sini di Harbour City, jadi Nona Nina meminta kami untuk datang dan mencari peluang bisnis potensial.",
  ui_story_5086_50860302_26_dialog_content = "Seperti membeli sebuah akuarium terkenal dan menggunakannya untuk melatih karyawan baru, kemudian membuka yang serupa di Umbraton... atau sesuatu seperti itu...",
  ui_story_5086_50860302_27_dialog_content = "Ide membuka akuarium di Umbraton mengisi kepalaku dengan beberapa gambar yang cukup menakutkan...",
  ui_story_5086_50860302_28_dialog_content = "Tidakkah kalian pikir sebaiknya dipertimbangkan lagi? Sejauh yang saya tahu, Umbraton belum pernah memiliki hal seperti itu sebelumnya.",
  ui_story_5086_50860302_29_dialog_content = "Itu... Itulah yang membuatnya menjadi kesempatan unik! Umbraton juga dekat dengan badan air, jadi itu masuk akal.",
  ui_story_5086_50860302_30_dialog_content = "Bukan kalian yang aku khawatirkan, tapi pengunjung masa depan kalian.",
  ui_story_5086_50860302_31_dialog_content = "Tapi Nona Nina sangat bertekad untuk mendirikan rantai bisnis ini... itulah sebabnya saya harus...",
  ui_story_5086_50860302_32_dialog_content = "A-Apalagi, saya masih harus bertanya apakah mereka ingin menjual akuarium—",
  ui_story_5086_50860302_33_dialog_content = "Kami tidak akan pernah melakukan itu!",
  ui_story_5086_50860302_34_dialog_content = "Maya? Bukankah kamu sedang menceritakan cerita kepada anak-anak itu? ... Oh, mereka sudah pulang.",
  ui_story_5086_50860302_35_dialog_content = "Aku tidak tahu apa yang kalian berdua cari, tapi—",
  ui_story_5086_50860302_36_dialog_content = "Akuarium ini ada untuk membawa senyum ke setiap tamu yang datang melalui pintunya.",
  ui_story_5086_50860302_37_dialog_content = "Ini adalah tempat yang penuh dengan kenangan indah dan bahagia, dan sangat penting bagi orang-orang di sini.",
  ui_story_5086_50860302_38_dialog_content = "Tak ada jumlah uang sebanyak apapun yang bisa membelinya.",
  ui_story_5086_50860302_39_dialog_content = "Ah... M-maaf...",
  ui_story_5086_50860302_40_dialog_content = "Apakah kamu lagi-lagi bersikap tidak sopan kepada tamu-tamu kita, Maya?",
  ui_story_5086_50860302_41_dialog_content = "Saya rasa saya tidak mengatakan sesuatu yang salah.",
  ui_story_5086_50860302_42_dialog_content = "Kamu juga berpikir begitu, kan, Miss Stellandine? Lagi pula, Anda lah yang telah berkorban paling banyak demi akuarium ini.",
  ui_story_5086_50860302_43_dialog_content = "Heheh, saya senang Anda begitu menghargai saya, Maya.",
  ui_story_5086_50860302_44_dialog_content = "Tapi kita masih harus menghasilkan uang.",
  ui_story_5086_50860302_45_dialog_content = "Bagaimana lagi aku bisa merawat kamu dan teman-teman kita yang lain di sini di akuarium?",
  ui_story_5086_50860302_46_dialog_content = "Mereka sudah dipaksa keluar dari rumah mereka di laut. Yang bisa saya lakukan hanyalah membuat hidup mereka di sini se nyaman mungkin.",
  ui_story_5086_50860302_47_dialog_content = "Saya telah berusaha keras untuk menghasilkan uang dan merawat semua orang juga! Um... Tunggu sebentar, tolong!",
  ui_story_5086_50860302_48_dialog_content = "Lihat ini, Miss Stellandine! Saya sudah menghasilkan dua ratus tiga puluh tiga Nightium untuk kita!",
  ui_story_5086_50860302_49_dialog_content = "Itu luar biasa, Maya! Saya yakin celengan di kamar Anda juga telah diberi makan dengan baik.",
  ui_story_5086_50860302_50_dialog_content = "Heehee!",
  ui_story_5086_50860302_51_dialog_content = "Jika suatu saat kamu mengalami masalah uang, kamu selalu bisa mengandalkan saya untuk membantu, Miss Stellandine!",
  ui_story_5086_50860302_52_dialog_content = "Saya tidak keberatan memberimu semua Nightium terakhir jika itu untuk akuarium.",
  ui_story_5086_50860302_53_dialog_content = "Terima kasih, Maya. Aku akan mengandalkanmu.",
  ui_story_5086_50860302_54_dialog_content = "Serahkan saja padaku!",
  ui_story_5086_50860302_55_dialog_content = "Astaga... Sungguh sangat mengejutkan.",
  ui_story_5086_50860302_56_dialog_content = "Apakah kamu mengatakan sesuatu? Minos?",
  ui_story_5086_50860302_57_dialog_content = "Tak ada apa-apa, teman baikku. Jangan hiraukan aku, aku hanya mencatat beberapa hal yang tak penting.",
  ui_story_5086_50860302_58_dialog_content = "Setelah semua, mengamati lingkungan budaya setempat juga merupakan bagian dari investigasi kita.",
  ui_story_5086_50860302_59_dialog_content = "Kamu rajin seperti biasa, Minos.",
  ui_story_5086_50860302_60_dialog_content = "Tentu saja.",
  ui_story_5086_50860401_1_dialog_content = "Karena semua orang sudah berkumpul di sini, mungkin ini saatnya untuk menepati janji saya.",
  ui_story_5086_50860401_2_dialog_content = "Maukah kamu bergabung dengan kami untuk makan siang?",
  ui_story_5086_50860401_3_dialog_content = "Tentu! Aku juga baru saja mulai merasa lapar.",
  ui_story_5086_50860401_4_dialog_content = "Saya tidak tahu bagaimana rasanya makanan di Harbour City, tetapi saya sangat menantikan untuk mencobanya.",
  ui_story_5086_50860401_5_dialog_content = "Maya, mari kita antar tamu-tamu kita ke restoran.",
  ui_story_5086_50860401_6_dialog_content = "Baik! Mari lewat sini, semuanya!",
  ui_story_5086_50860401_7_dialog_content = "Apakah kita juga pergi, Minos?",
  ui_story_5086_50860401_8_dialog_content = "Tolong jangan khawatirkan diri kalian demi kami.",
  ui_story_5086_50860401_9_dialog_content = "Sanae masih perlu menyusun laporannya tentang temuan pagi ini.",
  ui_story_5086_50860401_10_dialog_content = "Setelah dia menyelesaikan pekerjaannya, aku akan mengantar dia ke restoran.",
  ui_story_5086_50860401_11_dialog_content = "Silakan menikmati makanan Anda.",
  ui_story_5086_50860401_12_dialog_content = "Hah? M-maksud saya... ya, kita akan segera ke sana.",
  ui_story_5086_50860401_13_dialog_content = "Tetap pertahankan kerja bagusmu, Sanae.",
  ui_story_5086_50860401_14_dialog_content = "Aku... aku akan berusaha sebaik mungkin...",
  ui_story_5086_50860401_15_dialog_content = "Kami akan melihat kalian sebentar lagi... Tunggu, ke mana Maya dan Stellandine pergi?",
  ui_story_5086_50860401_16_dialog_content = "Di sebelah kiri pameran ikan hiu ada tangga. Ikuti ke lantai dua dan belok kiri, maka kamu akan menemukan restoran.",
  ui_story_5086_50860401_17_dialog_content = "Terima kasih, Minos.",
  ui_story_5086_50860401_18_dialog_content = "Belok kiri di lantai dua... Huh, saya bertanya-tanya mengapa Minos tahu cara sampai di sini...",
  ui_story_5086_50860401_19_dialog_content = "<color=#e8d9bb>Brak!</color>",
  ui_story_5086_50860401_20_dialog_content = "Aduh…",
  ui_story_5086_50860401_21_dialog_content = "Maya! Maaf, aku tidak melihatmu berlari ke arah ini.",
  ui_story_5086_50860401_22_dialog_content = "Kamu baik-baik saja?",
  ui_story_5086_50860401_23_dialog_content = "Heehee, aku baik-baik saja! Lagipula, seharusnya aku yang meminta maaf.",
  ui_story_5086_50860401_24_dialog_content = "Saya begitu sibuk memimpin jalan sampai-sampai saya lupa melihat apakah kamu masih mengikuti... Ah!",
  ui_story_5086_50860401_25_dialog_content = "<color=#e8d9bb>Dengan terkejut, Maya tiba-tiba mengeluarkan buku catatannya dan membolak-baliknya dengan panik.</color>",
  ui_story_5086_50860401_26_dialog_content = "Oh tidak. Di mana aku menuliskannya?",
  ui_story_5086_50860401_27_dialog_content = "Kalian sedang mencari apa?",
  ui_story_5086_50860401_28_dialog_content = "Saya sangat menyesal, Pak.",
  ui_story_5086_50860401_29_dialog_content = "Tapi, sepertinya aku lupa menuliskan namamu!",
  ui_story_5086_50860401_30_dialog_content = "Saya tidak berpikir kamu akan menemukannya di catatanmu. Lagi pula, saya belum memperkenalkan diri dengan benar.",
  ui_story_5086_50860401_31_dialog_content = "Nama saya adalah PlayerName, dan saya seorang Caelestite. Senang bertemu denganmu, Maya.",
  ui_story_5086_50860401_32_dialog_content = "Saya Maya, seorang trainee yang bekerja di akuarium!",
  ui_story_5086_50860401_X32_dialog_content = "Dan sekarang setelah kita saling berkenalan, itu membuat kita menjadi teman!",
  ui_story_5086_50860401_33_dialog_content = "Ke sini, PlayerName! Tidak mudah, tapi saya telah menyimpan tempat duduk terbaik di rumah ini hanya untukmu.",
  ui_story_5086_50860401_34_dialog_content = "Wow, aku bisa melihat seluruh tangki dari atas sini!",
  ui_story_5086_50860401_35_dialog_content = "Sungguh pemandangan yang luar biasa untuk menemani makan siang kita!",
  ui_story_5086_50860401_36_dialog_content = "Restoran ini sangat besar dan mewah juga. Apakah ini benar-benar bagian dari akuarium?",
  ui_story_5086_50860401_37_dialog_content = "Anda sangat tanggap, PlayerName.",
  ui_story_5086_50860401_38_dialog_content = "Secara ketat berbicara, restoran ini tidak sepenuhnya milik akuarium kami, tidak.",
  ui_story_5086_50860401_39_dialog_content = "Karena perkembangan cepat dari resor wisata di daerah ini, beberapa bisnis lokal yang lebih kecil telah mengalami kemunduran finansial yang serius.",
  ui_story_5086_50860401_40_dialog_content = "Untuk meredakan sebagian tekanan, sejumlah pemilik bisnis telah memutuskan untuk bersatu untuk bersaing di industri pariwisata yang sedang berkembang.",
  ui_story_5086_50860401_41_dialog_content = "Restoran ini hanyalah salah satu dari usaha-usaha tersebut.",
  ui_story_5086_50860401_42_dialog_content = "Setiap orang bekerja sangat keras untuk restoran ini, dan makanan di sini luar biasa!",
  ui_story_5086_50860401_43_dialog_content = "Pada hari pertama saya di sini, saya bertekad untuk mencoba setiap hidangan yang ada di menu.",
  ui_story_5086_50860401_44_dialog_content = "Tapi sampai hari ini, saya hanya bisa mencoba beberapa di antaranya.",
  ui_story_5086_50860401_45_dialog_content = "Masih banyak waktu, Maya. Tidak perlu terburu-buru.",
  ui_story_5086_50860401_46_dialog_content = "Nah, kita mau makan apa hari ini?",
  ui_story_5086_50860401_47_dialog_content = "Itu tergantung, kemarin kita makan apa ya? Hmm...",
  ui_story_5086_50860401_48_dialog_content = "Saya tidak menuliskannya di catatan saya. Apakah saya juga lupa melakukan itu?",
  ui_story_5086_50860401_49_dialog_content = "Oh baiklah, pesan apa saja yang kau suka—",
  ui_story_5086_50860401_50_dialog_content = "Aku akan pergi bertanya kepada salah satu pelayan tentang apa yang kamu makan kemarin.",
  ui_story_5086_50860401_51_dialog_content = "Oh, Anda tidak harus melakukan itu. Ini bukan masalah besar atau apa pun.",
  ui_story_5086_50860401_52_dialog_content = "Tapi kamu menetapkan tujuan untuk dirimu sendiri, bukan Maya?",
  ui_story_5086_50860401_53_dialog_content = "Tidak ada masalah sama sekali. Bahkan jika Anda lupa pesanan Anda, restoran ini memiliki menu khusus untuk Anda sebenarnya.",
  ui_story_5086_50860401_54_dialog_content = "Kamu selalu begitu bersedia membantu semua orang, jadi mereka juga ingin membantu kamu mewujudkan tujuanmu.",
  ui_story_5086_50860401_55_dialog_content = "Aku akan segera kembali.",
  ui_story_5086_50860401_56_dialog_content = "Miss Stellandine adalah orang yang baik.",
  ui_story_5086_50860401_57_dialog_content = "Benar kan? Dia adalah orang terbaik di seluruh dunia!",
  ui_story_5086_50860401_58_dialog_content = "Dia begitu baik dan lembut, dan dia secara pribadi merawat setiap hewan di akuarium.",
  ui_story_5086_50860401_59_dialog_content = "Bukan hanya itu, dia juga mengatakan akuarium bisa menjadi rumahku ketika aku tidak memiliki tempat untuk pergi.",
  ui_story_5086_50860401_60_dialog_content = "Hah? Jadi itu berarti kamu baru di sini?",
  ui_story_5086_50860401_61_dialog_content = "Serius, PlayerName? Aku tahu aku pelupa dan agak canggung, tapi aku tidak sepenuhnya putus asa, lo tahu!",
  ui_story_5086_50860401_62_dialog_content = "Jika aku sudah berada di sini cukup lama, apakah kamu benar-benar berpikir aku masih akan menjadi seorang trainee?",
  ui_story_5086_50860401_63_dialog_content = "Bisa saja saya bicara lebih banyak tentang ini... tapi kamu memang membuat poin yang cukup bagus, Maya.",
  ui_story_5086_50860401_64_dialog_content = "Kamu tampaknya sangat populer di sini.",
  ui_story_5086_50860401_65_dialog_content = "Meskipun ingatan burukmu membuatmu lupa akhir cerita yang kamu ceritakan, anak-anak tetap menyukainya.",
  ui_story_5086_50860401_66_dialog_content = "Hah? Cerita apa?",
  ui_story_5086_50860401_67_dialog_content = "Yang kamu ceritakan kepada anak-anak di area istirahat tadi.",
  ui_story_5086_50860401_68_dialog_content = "Oh, benarkah aku telah menceritakan sebuah kisah kepada mereka?",
  ui_story_5086_50860401_69_dialog_content = "<size=50>Maksudmu kamu sudah lupa?</size>",
  ui_story_5086_50860401_70_dialog_content = "Yah, sepertinya saya tidak menuliskannya di catatan saya—",
  ui_story_5086_50860401_71_dialog_content = "Jika kamu harus menulis setiap detail kecil seperti itu, saya tidak berpikir satu buku catatan saja cukup untuk satu hari.",
  ui_story_5086_50860401_72_dialog_content = "Tapi kamu masih ingat ceritanya, jadi kamu bisa menceritakannya padaku! Tolong, PlayerName, aku benar-benar ingin mendengarnya!",
  ui_story_5086_50860401_73_dialog_content = "T-Terlalu dekat! Aku akan menceritakan ceritanya, tapi beri aku sedikit ruang—",
  ui_story_5086_50860401_74_dialog_content = "Mari kita lihat, itu tentang seorang anak laki-laki...",
  ui_story_5086_50860402_1_dialog_content = "Apa cerita yang menarik. Apakah kamu mengarangnya lagi, Maya?",
  ui_story_5086_50860402_2_dialog_content = "Miss Stellandine! Kamu bisa membaca pikiran?",
  ui_story_5086_50860402_3_dialog_content = "Tidak, Maya, hanya saja ceritamu sangat istimewa.",
  ui_story_5086_50860402_4_dialog_content = "Tak peduli apa yang terjadi di dalamnya, atau jika karakternya baik atau buruk—",
  ui_story_5086_50860402_5_dialog_content = "Ceritamu selalu berakhir dengan semua orang berkumpul dan hidup bahagia selamanya.",
  ui_story_5086_50860402_6_dialog_content = "Nah, begitulah seharusnya dongeng berjalan, bahkan yang aku ciptakan sendiri.",
  ui_story_5086_50860402_7_dialog_content = "...",
  ui_story_5086_50860402_8_dialog_content = "Kurasa kamu benar. Lagipula, meski kamu membaca cerita sedih, kamu akan melupakannya pada hari berikutnya.",
  ui_story_5086_50860402_9_dialog_content = "Namun, kelupaan Maya jauh lebih serius daripada apa pun yang pernah aku lihat. Bukankah kita harus lebih khawatir tentang itu?",
  ui_story_5086_50860402_10_dialog_content = "Mungkin... Tapi saya membawanya ke dokter, dan hasil kesehatannya benar-benar normal.",
  ui_story_5086_50860402_11_dialog_content = "Dokter juga tidak bisa mengidentifikasi sumber dari pelupaan dia.",
  ui_story_5086_50860402_12_dialog_content = "Tidak mungkin mudah, hidup seperti ini...",
  ui_story_5086_50860402_13_dialog_content = "Tidak bercanda. Bagaimana lagi kamu bisa mengikuti manga jika kamu bahkan tidak bisa mengingat apa yang terjadi di edisi terakhir?",
  ui_story_5086_50860402_14_dialog_content = "Dan bagaimana dengan semua hal keren yang telah kamu lihat dalam hidup? Tidak ada pengalaman di dunia ini yang berarti jika kamu bahkan tidak bisa mengingatnya.",
  ui_story_5086_50860402_15_dialog_content = "Sadie! Kamu seharusnya tidak bicara tentang Miss Maya seperti itu, atau siapa pun juga. Itu tidak sopan.",
  ui_story_5086_50860402_16_dialog_content = "Ah, kamu benar. Maaf soal itu, Maya.",
  ui_story_5086_50860402_17_dialog_content = "Aww... Kasihan Miss Maya.",
  ui_story_5086_50860402_18_dialog_content = "Hei, kita tidak seharusnya membicarakan orang seperti itu.",
  ui_story_5086_50860402_19_dialog_content = "Aku tahu, tapi... ketika aku memikirkan betapa sulitnya hidupnya, aku...",
  ui_story_5086_50860402_20_dialog_content = "Nona Maya, kenapa kau tidak menjadi pelayan seperti aku?",
  ui_story_5086_50860402_21_dialog_content = "Pekerjaan bisa sedikit berat kadang-kadang... tapi kamu akan selalu dikelilingi oleh orang-orang baik...",
  ui_story_5086_50860402_22_dialog_content = "?",
  ui_story_5086_50860402_23_dialog_content = "Terima kasih, semua orang! Meskipun saya tidak benar-benar tahu apa yang sedang terjadi, kalian semua tampak benar-benar peduli padaku.",
  ui_story_5086_50860402_24_dialog_content = "Tapi kamu harus tahu, sebenarnya aku sangat senang di sini.",
  ui_story_5086_50860402_25_dialog_content = "Lihat? Jika ada hal penting yang terjadi dalam hidup saya, saya selalu menuliskannya dalam catatan saya agar tidak lupa.",
  ui_story_5086_50860402_26_dialog_content = "Kemarin, Maya tersesat di jalan. Seorang nenek yang memakai apron membantu Maya menunjukkan jalan, bahkan memberikan Maya sebuah jeruk.",
  ui_story_5086_50860402_27_dialog_content = "Itu karena kamu telah menyelamatkan cucunya dari tenggelam di laut pada hari itu. Dia sedang berterima kasih padamu, Maya.",
  ui_story_5086_50860402_28_dialog_content = "Sehari sebelumnya, aku lupa kalau lemari es kita rusak, jadi aku tidak bisa membuat es untuk beberapa hewan kita. Tapi untungnya, seorang penjual camilan yang baik hati memberiku ember besar es.",
  ui_story_5086_50860402_29_dialog_content = "Saya ingat itu juga. Kamu membantunya menarik lebih banyak pelanggan, karena bisnisnya sangat sepi hari itu. Kamu juga mencetuskan beberapa ide yang sangat berlebihan.",
  ui_story_5086_50860402_30_dialog_content = "Minggu lalu, ketika saya kehilangan diagram alir untuk acara interaktif kami, anak-anak bekerja sama untuk membantu saya menjalankan acara tersebut. Itu luar biasa!",
  ui_story_5086_50860402_31_dialog_content = "Awalnya tidak ada yang mau berpartisipasi, tetapi berkat kemampuan Maya bekerja dengan baik bersama anak-anak, acara tersebut menjadi sukses besar.",
  ui_story_5086_50860402_32_dialog_content = "Dan minggu sebelumnya, dan bulan lalu, bahkan tahun lalu...",
  ui_story_5086_50860402_33_dialog_content = "<color=#e8d9bb>Setiap halaman buku catatan Maya penuh dengan kenangan cerah dan positif.</color>",
  ui_story_5086_50860402_34_dialog_content = "<color=#e8d9bb>Dia mendeskripsikan momen-momen berwarna dalam kehidupan sehari-harinya dengan sangat jelas.</color>",
  ui_story_5086_50860402_35_dialog_content = "<color=#e8d9bb>Tiba-tiba, sebuah kartu jatuh dari halaman buku catatan.</color>",
  ui_story_5086_50860402_36_dialog_content = "<color=#e8d9bb>Dicoret-coret di atasnya adalah beberapa baris tulisan. Meskipun tulisan tangannya tampak seperti anak-anak, tetapi membawa suatu keberatan tertentu.</color>",
  ui_story_5086_50860402_37_dialog_content = "Apa yang kamu rekam di kartu itu, Maya?",
  ui_story_5086_50860402_38_dialog_content = "Oh, ini? Ini aku!",
  ui_story_5086_50860402_39_dialog_content = "Anda?",
  ui_story_5086_50860402_40_dialog_content = "Benar! Setiap kali ada sesuatu yang sangat-sangat-sangat penting terjadi dalam hidup saya, saya menulisnya di kartu ini dan membacanya setiap hari.",
  ui_story_5086_50860402_41_dialog_content = "Meskipun saya tidak dapat mengingat apa pun yang tertulis di dalamnya, kenangan ini adalah bagian besar dari diri saya.",
  ui_story_5086_50860402_42_dialog_content = "<color=#e8d9bb>Maya dengan lembut mengambil kartu itu dan memejamkan matanya.</color>",
  ui_story_5086_50860402_43_dialog_content = "<color=#e8d9bb>Jelas, dia tidak perlu melihat kartu itu untuk tahu apa yang tertulis.</color>",
  ui_story_5086_50860402_44_dialog_content = "Elvis mengharapkan saya memiliki hidup yang panjang dan bahagia.",
  ui_story_5086_50860402_45_dialog_content = "Miss Stellandine memberikan tempat tinggal untukku di akuariumnya.",
  ui_story_5086_50860402_46_dialog_content = "Saya mencintai setiap orang di sini di Harbour City.",
  ui_story_5086_50860402_47_dialog_content = "Oh, Nona Maya...",
  ui_story_5086_50860402_48_dialog_content = "Jika kamu ingin mengunjungi Umbraton, aku akan pastikan untuk merawatmu dengan baik. Itu adalah hal terkecil yang bisa dilakukan oleh seorang swashbuckler.",
  ui_story_5086_50860402_49_dialog_content = "Saya pikir Anda juga memiliki potensi untuk menjadi idola, Miss Maya. Ingin mencobanya?",
  ui_story_5086_50860402_50_dialog_content = "Hah? Tunggu, aku baru saja bilang bahwa aku sangat menikmati hidupku di sini. Aku tidak mau pergi ke mana-mana lagi—",
  ui_story_5086_50860402_51_dialog_content = "Nona Stellandine, dia baru saja menyebut seseorang bernama Elvis...",
  ui_story_5086_50860402_52_dialog_content = "Tuan Kota, ya. Dia cukup baik untuk merawat Maya di masa lalu, karena dia tidak memiliki orang tua untuk dijadikan pembicaraan dan ingatannya masih tidak dapat diandalkan. Hal ini sudah diketahui oleh setiap orang di kota.",
  ui_story_5086_50860402_53_dialog_content = "Dia juga dikenal karena berlari keliling kota dan memberikan bantuan kepada siapa saja yang membutuhkan.",
  ui_story_5086_50860402_54_dialog_content = "Untuk alasan itu, beberapa penduduk kota kami mulai menyebutnya Tuan Putri Miskin dari Harbour City.",
  ui_story_5086_50860402_55_dialog_content = "Ketika Harbour City diserang selama krisis baru-baru ini, Maya tampaknya juga telah menghilang.",
  ui_story_5086_50860402_56_dialog_content = "Tak ada yang tahu jika sesuatu telah terjadi padanya, atau jika Tuan Kota memiliki kaitan dengan itu...",
  ui_story_5086_50860402_57_dialog_content = "Karena dia tidak bisa mengingat apa-apa tentang itu, mencari tahu kebenaran sekarang hampir mustahil.",
  ui_story_5086_50860402_58_dialog_content = "Yang saya tahu adalah beberapa hari setelah insiden itu, dia tiba-tiba muncul di pintu masuk akuarium, meminta pekerjaan.",
  ui_story_5086_50860402_59_dialog_content = "Melihat bahwa dia tidak lagi memiliki seorang guardian, saya menawarkan untuk membiarkannya tinggal dan bekerja di sini sebagai seorang peserta pelatihan.",
  ui_story_5086_50860402_60_dialog_content = "Aku tidak pernah melakukan sesuatu yang sangat istimewa, namun dia menulis tentangku seolah-olah aku adalah seorang orang suci.",
  ui_story_5086_50860402_61_dialog_content = "Sebenarnya...",
  ui_story_5086_50860402_62_dialog_content = "(Elvis dulu merawatnya... Bisakah jadi Jeno memilih Maya untuk menjadi kurirnya?)",
  ui_story_5086_50860402_63_dialog_content = "Nona Stellandine, saya mungkin memiliki cara untuk membantu Maya memulihkan beberapa ingatannya.",
  ui_story_5086_50860402_64_dialog_content = "Begitukah?",
  ui_story_5086_50860402_65_dialog_content = "Ya, dan saya rasa ada kemungkinan baik itu juga akan berhasil.",
  ui_story_5086_50860402_66_dialog_content = "Oh, begitu..",
  ui_story_5086_50860402_67_dialog_content = "Sebanyak apapun aku ingin menerima tawaranmu, sebagai wali sementara Maya, aku pikir dia yang harus memutuskan.",
  ui_story_5086_50860500_1_dialog_content = "Kamu bilang kamu bisa membantu saya memulihkan ingatanku?",
  ui_story_5086_50860500_2_dialog_content = "Aku tidak tahu kamu bisa melakukan sesuatu yang begitu luar biasa, PlayerName!",
  ui_story_5086_50860500_3_dialog_content = "Sebagai seorang Caelestite, saya dapat menggunakan kemampuan psikis saya untuk terhubung dengan pikiran orang lain. Saya belum sepenuhnya menguasai kekuatan saya, tetapi saya pasti dapat menggunakannya untuk hal seperti ini.",
  ui_story_5086_50860500_4_dialog_content = "Dengan menyelami ingatan Anda, saya mungkin bisa menemukan sesuatu yang tidak mungkin Anda lihat sendiri.",
  ui_story_5086_50860500_5_dialog_content = "Kekuatan untuk terhubung dengan pikiran orang... Apakah itu yang dimaksud?",
  ui_story_5086_50860500_6_dialog_content = "Yah, kira-kira begitulah.",
  ui_story_5086_50860500_7_dialog_content = "Hmm... Biar saya lihat catatan saya sekali lagi.",
  ui_story_5086_50860500_8_dialog_content = "?",
  ui_story_5086_50860500_9_dialog_content = "...",
  ui_story_5086_50860500_10_dialog_content = "Maaf, tapi saya tidak bisa melakukan itu.",
  ui_story_5086_50860500_11_dialog_content = "Hah? Apakah karena ada sesuatu yang tidak ingin kau biarkan aku lihat?",
  ui_story_5086_50860500_12_dialog_content = "Tidak, bukan itu!",
  ui_story_5086_50860500_13_dialog_content = "Hanya saja, aku tidak seharusnya mengganggu mimpi leluhurku.",
  ui_story_5086_50860500_14_dialog_content = "Leluhurmu?",
  ui_story_5086_50860500_15_dialog_content = "Benar. Ingatan yang telah aku lupakan mungkin sekarang ada bersama leluhurku, bersama dengan orang tuaku.",
  ui_story_5086_50860500_16_dialog_content = "Itulah sebabnya aku tidak terburu-buru untuk mendapatkan mereka kembali sekarang juga.",
  ui_story_5086_50860500_17_dialog_content = "Terkadang rasanya sedikit sepi, tapi aku bisa menahannya.",
  ui_story_5086_50860500_18_dialog_content = "Karena suatu hari nanti, ketika mimpi saya akhirnya berakhir, saya akan dapat mengembalikan segala yang telah saya hilang.",
  ui_story_5086_50860500_19_dialog_content = "Uh, Maya... Apa yang kamu bicarakan?",
  ui_story_5086_50860500_20_dialog_content = "Maksudmu kamu tidak tahu, PlayerName?",
  ui_story_5086_50860500_21_dialog_content = "Seluruh dunia ini hanya mimpi.",
  ui_story_5086_50860500_22_dialog_content = "Apa maksudmu? Kita jelas berada di dunia nyata sekarang. Cubit pipimu, jika kamu tidak percaya padaku!",
  ui_story_5086_50860500_23_dialog_content = "Dan bahkan jika kita berada dalam mimpi, mimpi siapa itu? Milikmu?",
  ui_story_5086_50860500_24_dialog_content = "Mimpi hanyalah mimpi. Mimpi kamu tidak berbeda dengan milikku, atau milik orang lain.",
  ui_story_5086_50860500_25_dialog_content = "Orang tuaku melihatku dalam mimpi mereka, yang merupakan satu-satunya alasan aku ada di sini pada awalnya.",
  ui_story_5086_50860500_26_dialog_content = "Leluhurku juga mengawasiku dari dalam mimpi.",
  ui_story_5086_50860500_27_dialog_content = "Jadi, kamu pikir kita semua hanya karakter di dalam mimpi, Maya?",
  ui_story_5086_50860500_28_dialog_content = "Tentu saja tidak! Semua orang hanya hidup dalam gelembung, itu saja. Adapun orang-orang penting yang telah kita kehilangan... mereka hidup dalam mimpi terindah sepanjang masa, merawat kita.",
  ui_story_5086_50860500_29_dialog_content = "Jadi, siapa sebenarnya leluhurmu?",
  ui_story_5086_50860500_30_dialog_content = "Progenitor dari seluruh garis keturunan saya, seorang guardian bawah laut yang pandangannya melihat melampaui aliran waktu.",
  ui_story_5086_50860500_31_dialog_content = "Atau setidaknya itu yang baru saja dikatakan oleh leluhur saya.",
  ui_story_5086_50860500_32_dialog_content = "Itulah sebabnya saya tidak seharusnya mengganggu dunia lain hanya untuk sesuatu yang sekecil mendapatkan kembali ingatan saya.",
  ui_story_5086_50860500_33_dialog_content = "Tentu saja, saya seharusnya tidak mengganggu leluhur saya tentang hal itu juga.",
  ui_story_5086_50860500_34_dialog_content = "Aku masih merasa cukup bingung sekarang...",
  ui_story_5086_50860500_35_dialog_content = "Maaf...",
  ui_story_5086_50860500_36_dialog_content = "Tapi yang saya mengerti adalah ada sesuatu yang lebih penting bagi Anda daripada mengambil kembali ingatan Anda.",
  ui_story_5086_50860500_37_dialog_content = "!",
  ui_story_5086_50860500_38_dialog_content = "Meski aku benar-benar penasaran untuk mengetahui lebih banyak tentang itu... Aku tidak akan memaksa kamu melakukan apa pun yang tidak kamu mau, Maya.",
  ui_story_5086_50860500_39_dialog_content = "PlayerName...",
  ui_story_5086_50860500_40_dialog_content = "Aku benar-benar menyukaimu!",
  ui_story_5086_50860500_41_dialog_content = "Hah? Tidak, tunggu... Uh... Aku masih...",
  ui_story_5086_50860500_42_dialog_content = "Kita sudah membahas ini sebelumnya, Maya. Kamu tidak bisa mengatakan hal-hal seperti itu kepada anak laki-laki dengan begitu santai.",
  ui_story_5086_50860500_43_dialog_content = "Saya juga benar-benar menyukai Anda, Miss Stellandine!",
  ui_story_5086_50860500_44_dialog_content = "Oh, anak kecil yang manis... Tidak apa-apa. Siang nanti masih ada pekerjaan yang harus dilakukan, jadi cobalah untuk istirahat sekarang.",
  ui_story_5086_50860500_45_dialog_content = "Tapi aku ingin mendengarkan dongeng.",
  ui_story_5086_50860500_46_dialog_content = "Karena aku sudah lupa cerita dari pagi ini, mendengarkan cerita baru adalah cara istirahatku!",
  ui_story_5086_50860500_47_dialog_content = "Kamu benar-benar tampak menikmati dongeng, Maya.",
  ui_story_5086_50860500_48_dialog_content = "Itu karena mereka adalah catatan dari mimpi-mimpi yang berbeda.",
  ui_story_5086_50860500_49_dialog_content = "Dan saya suka melihat berbagai jenis mimpi yang berbeda.",
  ui_story_5086_50860500_50_dialog_content = "Catatan mimpi, huh...",
  ui_story_5086_50860500_51_dialog_content = "Baiklah, kalau begitu. Kebetulan aku memiliki sebuah kisah yang layak untuk diceritakan sekarang.",
  ui_story_5086_50860500_52_dialog_content = "Ini tentang seorang gadis kecil dan mimpi yang tak berharap.",
  ui_story_5086_50860500_53_dialog_content = "Ya! Kamu yang terbaik, Nona Stellandine!",
  ui_story_5086_50860500_54_dialog_content = "Pada suatu masa, ada seorang gadis yang tinggal di bawah laut.",
  ui_story_5086_50860500_55_dialog_content = "Laut menyediakan segala macam hal untuknya—makanan lezat, harta karun melimpah, dan semua mainan serta hiburan yang dia inginkan.",
  ui_story_5086_50860500_56_dialog_content = "Tapi ada juga banyak hal yang hilang dari dunianya, seperti api dan kebisingan... dan cinta.",
  ui_story_5086_50860500_57_dialog_content = "Suatu hari, selama badai berbahaya, gadis muda itu menyelamatkan seorang pangeran muda yang jatuh dari kapalnya. Alami, dia jatuh cinta berkepanjangan padanya.",
  ui_story_5086_50860500_58_dialog_content = "Wow! Seorang pangeran dari daratan dan seorang putri dari laut!",
  ui_story_5086_50860500_59_dialog_content = "Tak lama kemudian, awak kapal pangeran menariknya kembali ke kapal, dan mereka kembali ke kerajaan mereka. Waktu berlalu lama, tetapi pangeran itu tak pernah kembali.",
  ui_story_5086_50860500_60_dialog_content = "Eh? Tapi, kenapa...",
  ui_story_5086_50860500_61_dialog_content = "Jadi gadis itu mengunjungi penyihir laut dan menawarkan harta paling berharganya sebagai tukar menukar kekuatan untuk berjalan di darat.",
  ui_story_5086_50860500_62_dialog_content = "Ketika akhirnya dia sampai di pantai, dia berjuang untuk menggunakan kaki barunya. Tapi dia bertekad untuk bertemu pangeran lagi, jadi dia merangkak sampai dia bisa berjalan, dan berjalan sampai dia bisa berlari...",
  ui_story_5086_50860500_63_dialog_content = "Ya! Jangan menyerah, Putri! Kamu pasti bisa!",
  ui_story_5086_50860500_64_dialog_content = "Tapi itu adalah ketika gadis itu menemukan sesuatu yang mengerikan telah terjadi. Sebagai ganti kaki barunya, penyihir telah mengambil apa yang paling dia hargai—kenangan tentang pangeran yang dia cintai.",
  ui_story_5086_50860500_65_dialog_content = "Dia berdiri di tengah kerumunan orang asing, wajah dan suara kekasihnya kini menjadi misteri baginya.",
  ui_story_5086_50860500_66_dialog_content = "Sebenarnya, gadis itu mulai meragukan apakah dia benar-benar pernah jatuh cinta sejak awal.",
  ui_story_5086_50860500_67_dialog_content = "Dia tidak memiliki cara untuk bertemu dengan orang yang dia cintai lagi.",
  ui_story_5086_50860500_68_dialog_content = "Terus bagaimana?",
  ui_story_5086_50860500_69_dialog_content = "Tidak ada, sayangku. Inilah bagaimana cerita berakhir.",
  ui_story_5086_50860500_70_dialog_content = "Hah? B-Tapi gadis itu belum menemukan pangerannya!",
  ui_story_5086_50860500_71_dialog_content = "Dia juga tidak mendapatkan kembali ingatannya! Dia bahkan tidak bisa mengingat bagaimana wajahnya lagi!",
  ui_story_5086_50860500_72_dialog_content = "Sungguh cerita yang sedih dan tanpa harapan...",
  ui_story_5086_50860500_73_dialog_content = "Kamu menceritakannya dengan baik, Nona Stellandine... tetapi aku tidak bisa tidak merasa sedih sekarang...",
  ui_story_5086_50860500_74_dialog_content = "Maya...",
  ui_story_5086_50860500_75_dialog_content = "Aku merasa sama! Kenapa... Kenapa hidup harus begitu tidak adil pada gadis malang itu?",
  ui_story_5086_50860500_76_dialog_content = "Sanae? Dan setiap orang lainnya... Berapa lama kalian di sini?",
  ui_story_5086_50860500_77_dialog_content = "Sejak cerita dimulai, tentu saja! Lihat? Sadie menarik topinya ke bawah karena dia tidak ingin siapa pun melihat air matanya.",
  ui_story_5086_50860500_78_dialog_content = "Saya tidak menangis. Ini hanya cara swashbuckler menunjukkan rasa hormat dan rasa terima kasih mereka.",
  ui_story_5086_50860500_79_dialog_content = "Uh-huh, terserah kata-katamu!",
  ui_story_5086_50860500_80_dialog_content = "Meski begitu, saya terkejut banyak orang yang belum pernah mendengar dongeng ini sebelumnya. Saya selalu berpikir itu adalah cerita yang cukup terkenal.",
  ui_story_5086_50860500_81_dialog_content = "Saya hanya tertarik pada kisah-kisah swashbuckler.",
  ui_story_5086_50860500_82_dialog_content = "Jika ada pemberani di dunianya, saya yakin mereka akan membantu dia mendapatkan kembali ingatannya dalam sekejap.",
  ui_story_5086_50860500_83_dialog_content = "Kamu benar, tapi bahkan tanpa pahlawan seperti itu, saya yakin ada orang yang bersedia membantu dia.",
  ui_story_5086_50860500_84_dialog_content = "Dongeng seharusnya tidak memiliki akhir yang sedih.",
  ui_story_5086_50860500_85_dialog_content = "Tapi... Mungkin saja sang pangeran sudah melupakan dia... Bahkan, dia mungkin sudah menikahi putri lain...",
  ui_story_5086_50860500_86_dialog_content = "Sementara itu, gadis malang itu ditinggalkan sendirian di pantai... Sungguh tragis... *menangis*",
  ui_story_5086_50860500_87_dialog_content = "Eh, Sanae? Ini hanya cerita, kamu tahu.",
  ui_story_5086_50860500_88_dialog_content = "Waaaaaaah—",
  ui_story_5086_50860500_89_dialog_content = "Astaga, Sanae tidak berhenti menangis... Lakukan sesuatu, Manae! Tolong!",
  ui_story_5086_50860500_90_dialog_content = "...",
  ui_story_5086_50860500_91_dialog_content = "Waaaaaah! Mengapa gadis itu harus membayar harga yang begitu mengerikan? Penyihir itu tidak lebih dari orang jahat besar! Dan mengapa pangeran tidak pernah mencarinya? Waaaaaaah!",
  ui_story_5086_50860500_92_dialog_content = "Mengapa kamu malah makin membingungkan, Manae?",
  ui_story_5086_50860500_93_dialog_content = "<color=#e8d9bb>Fwooo—</color>",
  ui_story_5086_50860500_94_dialog_content = "<color=#e8d9bb>Tiba-tiba, sebuah lagu lembut mulai diputar.</color>",
  ui_story_5086_50860500_95_dialog_content = "<color=#e8d9bb>Seiring ringan dan jauhnya angin laut yang lembut, melodi naik dan turun seperti ombak yang muncul dari dasar laut yang tenang.</color>",
  ui_story_5086_50860500_96_dialog_content = "<color=#e8d9bb>Setiap nada terdengar jelas dari kerang di tangan Maya.</color>",
  ui_story_5086_50860500_97_dialog_content = "<color=#e8d9bb>Untuk sesaat, pikiran setiap orang melayang mengikuti irama lagunya...</color>",
  ui_story_5086_50860500_98_dialog_content = "<color=#e8d9bb>Dengan hati mereka yang ditenangkan oleh melodi, mereka mulai melupakan semua masalah mereka.</color>",
  ui_story_5086_50860500_99_dialog_content = "Lagu yang sangat indah... Itu tadi apa, Miss Maya?",
  ui_story_5086_50860500_100_dialog_content = "Saya tidak tahu banyak tentang musik, tetapi lagu itu membuat saya memikirkan manga swashbuckler favorit saya baru saja.",
  ui_story_5086_50860500_101_dialog_content = "Saya sangat terhormat telah mendapat keistimewaan mendengar lagu yang begitu indah.",
  ui_story_5086_50860500_102_dialog_content = "Kamu juga di sini, Minos? ... Hah?",
  ui_story_5086_50860500_103_dialog_content = "Kapan Sanae tertidur?",
  ui_story_5086_50860500_104_dialog_content = "Musik Maya memiliki kekuatan untuk menenangkan hati orang-orang. Ini sangat berguna dalam situasi seperti ini.",
  ui_story_5086_50860500_105_dialog_content = "Saya yakin anak kecil ini sedang bermimpi indah saat kita bicara.",
  ui_story_5086_50860500_106_dialog_content = "Yep. Sekarang dia sudah melupakan semua kesedihannya, dia akhirnya bisa santai.",
  ui_story_5086_50860500_107_dialog_content = "Nona Muda Sanae telah berusaha keras untuk menyelesaikan tugas yang diberikan oleh Lady kita. Ini adalah kesempatan sempurna untuk dia beristirahat.",
  ui_story_5086_50860500_108_dialog_content = "Di belakang akuarium adalah kuartir tempat tinggal untuk karyawan kami. Ada banyak kamar yang tersedia.",
  ui_story_5086_50860500_109_dialog_content = "Jika Anda tidak keberatan, dia sangat diterima untuk tidur di sana.",
  ui_story_5086_50860500_110_dialog_content = "Kalian yang lain juga bebas menggunakan ruangan tersebut.",
  ui_story_5086_50860500_111_dialog_content = "Saya percaya saya akan melakukan hal itu. Keramahan Anda sangat kami hargai, Nona Stellandine.",
  ui_story_5086_50860500_112_dialog_content = "Pak PlayerName, bisakah Anda membantu saya mengantar Sanae ke kamarnya?",
  ui_story_5086_50860500_113_dialog_content = "Aku? Yah, ayo.",
  ui_story_5086_50860500_114_dialog_content = "Anda memiliki terima kasih saya.",
  ui_story_5086_50860601_1_dialog_content = "Minos, apakah ada alasan tertentu kamu memintaku untuk membantumu?",
  ui_story_5086_50860601_2_dialog_content = "Maaf?",
  ui_story_5086_50860601_3_dialog_content = "Aku bisa mengerti jika orang lain meminta bantuan dariku, tapi ini kamu yang kita bicarakan.",
  ui_story_5086_50860601_4_dialog_content = "Untuk Minos, kepala pelayan yang sangat berkuasa dari keluarga Andersen, meminta bantuan saya sama tidak mungkinnya dengan Cloud Gardens menjadi pusat yang tepat dari seluruh alam semesta.",
  ui_story_5086_50860601_5_dialog_content = "Saya percaya kamu menganggap saya dengan penghargaan yang terlalu tinggi, temanku. Namun, itu persis seperti yang kamu duga.",
  ui_story_5086_50860601_6_dialog_content = "Anda sadar tentang konflik yang baru-baru ini menimpa Harbour City, bukan?",
  ui_story_5086_50860601_7_dialog_content = "... Saya.",
  ui_story_5086_50860601_8_dialog_content = "Sepertinya kamu jauh lebih tahu banyak tentang situasi ini daripada yang ingin kamu akui.",
  ui_story_5086_50860601_9_dialog_content = "A-Apakah itu begitu jelas?",
  ui_story_5086_50860601_10_dialog_content = "Saya hanya membuat pengamatan kecil lainnya, tidak lebih.",
  ui_story_5086_50860601_11_dialog_content = "Tapi saya menyimpang. Dalam sepuluh tahun terakhir, Lord Kota Elvis mengorbankan darah dan keringat dalam ukuran yang sama besar demi Harbour City.",
  ui_story_5086_50860601_12_dialog_content = "Berkat upaya dia, kota ini menjadi tempat yang begitu damai dan makmur.",
  ui_story_5086_50860601_13_dialog_content = "Namun, setelah insiden baru-baru itu dan hilangnya dia, Harbour City jatuh di bawah administrasi Lumopolis.",
  ui_story_5086_50860601_14_dialog_content = "Ini adalah alasan tepat mengapa Miss Nina percaya bahwa Harbour City penuh dengan peluang bisnis.",
  ui_story_5086_50860601_15_dialog_content = "Tapi juga patut dicatat bahwa ketika sebuah organisasi terjebak dalam kerusuhan, cacing akan cenderung berkembang biak bahkan di sudut-sudut terkecil.",
  ui_story_5086_50860601_16_dialog_content = "Apa maksudmu?",
  ui_story_5086_50860601_17_dialog_content = "Saya yakin Anda sudah menyadarinya sekarang, Tuan PlayerName. Berbagai macam rumor aneh dan mengganggu telah beredar di dalam dan sekitar Harbour City.",
  ui_story_5086_50860601_18_dialog_content = "Saya khawatir bahwa konflik terbaru di kota ini adalah penyebab mereka, dan rumor buruk ini hanya berfungsi untuk menurunkan nilai Harbour City di mata dunia.",
  ui_story_5086_50860601_19_dialog_content = "Sekarang kamu sebutkan itu, Sadie dan Goldie hanya datang ke sini dari Umbraton karena mereka mendengar sesuatu yang mengganggu tentang Harbour City.",
  ui_story_5086_50860601_20_dialog_content = "Namun, sampai sekarang, mereka masih belum menemukan apa pun untuk membuktikan rumor tersebut.",
  ui_story_5086_50860601_21_dialog_content = "Semuanya sangat aneh. Saya tidak heran jika Sadie datang untuk hal semacam ini, tapi kenapa Goldie juga ikut?",
  ui_story_5086_50860601_22_dialog_content = "Apakah dia juga merasakan bahaya di sini?",
  ui_story_5086_50860601_23_dialog_content = "... Tunggu.",
  ui_story_5086_50860601_24_dialog_content = "Kecurigaanku benar terakhir kali, bukan? Ini mirip dengan apa yang terjadi saat aku pertama kali bertemu denganmu, Minos...",
  ui_story_5086_50860601_25_dialog_content = "Apakah kamu sedang memberitahuku bahwa sesuatu yang mengerikan seperti itu akan terjadi lagi?",
  ui_story_5086_50860601_26_dialog_content = "Tentu saja tidak. Aku hanyalah seorang pelayan biasa, bukan nabi.",
  ui_story_5086_50860601_27_dialog_content = "Fiuh, itu melegakan.",
  ui_story_5086_50860601_28_dialog_content = "Namun, saya membuat sejumlah penemuan yang mengganggu saat melakukan penyelidikan bisnis kami.",
  ui_story_5086_50860601_29_dialog_content = "Misalnya, telah ada beberapa kasus penghilangan pelancong di Harbour City.",
  ui_story_5086_50860601_30_dialog_content = "Lebih lanjut, masing-masing dari mereka mengungkapkan keinginan tertentu sebelum menghilang—",
  ui_story_5086_50860601_31_dialog_content = "Yaitu, mereka ingin pergi ke akuarium.",
  ui_story_5086_50860601_32_dialog_content = "Akuarium ini benar-benar sesuai dengan reputasinya!",
  ui_story_5086_50860601_33_dialog_content = "Semua ikan di sini begitu hidup. Seperti baru saja mereka tarik dari laut hari ini.",
  ui_story_5086_50860601_34_dialog_content = "Haha... Ha...",
  ui_story_5086_50860601_35_dialog_content = "Hei... Di mana semua orang?",
  ui_story_5086_50860601_36_dialog_content = "Halo? Ada orang di sana? Saya bisa menggunakan bantuan di sini!",
  ui_story_5086_50860601_37_dialog_content = "Ini sedikit terlalu gelap di sini. Bukankah seharusnya ada tanda keluar yang diterangi agar orang bisa melihat?",
  ui_story_5086_50860601_38_dialog_content = "Oh, saya melihat cahaya di sana! Saya cukup yakin itu mengarah ke lobi, jadi saya akan—",
  ui_story_5086_50860601_39_dialog_content = "... Bau apa itu?",
  ui_story_5086_50860601_40_dialog_content = "Apakah... seseorang di sana?",
  ui_story_5086_50860601_41_dialog_content = "Hah? Ap-Apa yang kau...",
  ui_story_5086_50860601_42_dialog_content = "Ahhhhhhh!",
  ui_story_5086_50860602_1_dialog_content = "Gah!",
  ui_story_5086_50860602_2_dialog_content = "J-Jangan menakutiku seperti itu, Minos!",
  ui_story_5086_50860602_3_dialog_content = "Permintaan maaf saya. Saya hanya bermaksud untuk membagikan informasi yang telah saya peroleh dengan Anda.",
  ui_story_5086_50860602_4_dialog_content = "Kebenaran yang murni seringkali yang paling menakutkan. Pernahkah kamu mendengar pepatah ini sebelumnya?",
  ui_story_5086_50860602_5_dialog_content = "Dibandingkan dengan ketenangan pikiran yang dangkal, saya merasa jauh lebih nyaman ketika saya mengetahui seluruh kebenaran di balik setiap detail.",
  ui_story_5086_50860602_6_dialog_content = "Anda pasti memiliki saraf baja, Minos.",
  ui_story_5086_50860602_7_dialog_content = "Selama Yang Mulia membutuhkannya, seluruh kota bisa dibangun di atas sarafku yang tidak bergerak.",
  ui_story_5086_50860602_8_dialog_content = "... Saya tidak bisa lagi membedakan apakah kamu sedang bercanda atau tidak.",
  ui_story_5086_50860602_9_dialog_content = "Itu hampir tidak penting sekarang.",
  ui_story_5086_50860602_10_dialog_content = "Yang benar-benar penting adalah, apakah kau sudah beristirahat selama jeda singkat ini?",
  ui_story_5086_50860602_11_dialog_content = "...Sudah.",
  ui_story_5086_50860602_12_dialog_content = "Luar biasa. Akan menjadi hal yang tak bisa dimaafkan jika aku membuat teman baik Nona Nina merasa terganggu dengan kata-kataku.",
  ui_story_5086_50860602_13_dialog_content = "Jika kamu memaafkan saya, saya harus merawat Sanae muda sekarang.",
  ui_story_5086_50860602_14_dialog_content = "Ha?",
  ui_story_5086_50860602_15_dialog_content = "Saya bertanya-tanya mengapa Minos merasa perlu untuk berbagi semua ini denganku...",
  ui_story_5086_50860602_16_dialog_content = "Tidak terasa seolah dia mencoba menakutiku atau apa pun.",
  ui_story_5086_50860602_17_dialog_content = "Namun, masih mungkin bahwa semua kejadian menghilang ini entah bagaimana berhubungan dengan akuarium...",
  ui_story_5086_50860602_18_dialog_content = "Berdasarkan pengalaman saya, setiap kali ada sesuatu yang aneh seperti ini terjadi, pelaku pertama yang harus saya curigai adalah—",
  ui_story_5086_50860602_19_option_content = "Pemindaian Psikis!",
  ui_story_5086_50860602_20_dialog_content = "!",
  ui_story_5086_50860602_21_dialog_content = "Tidak mungkin... Aku tidak menyangka ini, tapi aku merasakan kehadiran Eclipsite di akuarium!",
  ui_story_5086_50860602_22_dialog_content = "Terlalu samar untuk menentukan lokasi tepatnya... Di mana kira-kira itu bisa berada?",
  ui_story_5086_50860602_23_dialog_content = "<color=#e8d9bb>Fwooo—</color>",
  ui_story_5086_50860602_24_dialog_content = "Hilang? Tunggu... Aku pernah mendengar lagu ini sebelumnya...",
  ui_story_5086_50860602_25_dialog_content = "...",
  ui_story_5086_50860602_26_dialog_content = "Maya?",
  ui_story_5086_50860602_27_dialog_content = "Ssst.",
  ui_story_5086_50860602_28_dialog_content = "Dia sedang tidur.",
  ui_story_5086_50860602_29_dialog_content = "<color=#e8d9bb>Maya mundur untuk menunjukkan seorang anak laki-laki yang sedang tidur di bangku.</color>",
  ui_story_5086_50860602_30_dialog_content = "Itu anak dari sebelumnya... Froude, kan? Kenapa dia belum pulang ke rumah?",
  ui_story_5086_50860602_31_dialog_content = "Paus di sini adalah hewan favoritnya, jadi dia suka menyelinap keluar setelah pulang untuk mengunjungi mereka.",
  ui_story_5086_50860602_32_dialog_content = "Biasanya aku menemukannya berkeliling di pameran paus sekitar waktu ini. Setiap kali aku melakukannya, aku hanya menceritakan dongeng lain kepadanya, dan dia langsung kembali ke rumah.",
  ui_story_5086_50860602_33_dialog_content = "Heheh, aku tahu semua ini karena aku menuliskannya di catatan ku.",
  ui_story_5086_50860602_34_dialog_content = "Jadi cerita apa yang kamu ceritakan kepadanya, Maya?",
  ui_story_5086_50860602_35_dialog_content = "Nah, karena aku hanya bisa mengingat setengahnya, aku harus melengkapinya dengan memainkan kerangku.",
  ui_story_5086_50860602_36_dialog_content = "Sekarang kamu di sini, PlayerName... Kamu bisa menceritakan sebuah kisah kepada kami!",
  ui_story_5086_50860602_37_dialog_content = "Tapi Froude sudah tidur.",
  ui_story_5086_50860602_38_dialog_content = "Tidak tahukah kamu, PlayerName? Mereka bilang kamu masih bisa mengingat hal-hal bahkan ketika kamu mendengarnya dalam tidurmu.",
  ui_story_5086_50860602_39_dialog_content = "Kamu hanya ingin mendengar cerita lainnya, 'kan?",
  ui_story_5086_50860602_40_dialog_content = "Haha, benar sekali!",
  ui_story_5086_50860602_41_dialog_content = "... Kurasa aku mulai mengerti bagaimana perasaan Miss Stellandine.",
  ui_story_5086_50860602_42_dialog_content = "(Hampir mustahil untuk menolak Maya.)",
  ui_story_5086_50860602_43_dialog_content = "Masihkah kamu ingat cerita yang diceritakan Miss Stellandine kepada kita sebelumnya?",
  ui_story_5086_50860602_44_dialog_content = "Apa? Nyonya Stellandine menceritakan sebuah cerita kepada kita?",
  ui_story_5086_50860602_45_dialog_content = "Seharusnya aku tahu... Tidak apa-apa, aku akan ceritakan lagi padamu.",
  ui_story_5086_50860602_46_dialog_content = "Pada suatu masa, ada seorang gadis yang tinggal di laut. Dia menyelamatkan seorang pangeran muda ketika dia jatuh dari kapalnya...",
  ui_story_5086_50860602_47_dialog_content = "Ya!",
  ui_story_5086_50860602_48_dialog_content = "... Dan begitu gadis itu membuat kesepakatan dengan penyihir laut, yang memberinya kemampuan untuk berjalan di darat.",
  ui_story_5086_50860602_49_dialog_content = "Tapi ketika gadis itu sampai di pantai, dia menyadari bahwa harga yang dia bayar untuk kaki barunya adalah kenangan tentang pangeran yang sangat dia cintai.",
  ui_story_5086_50860602_50_dialog_content = "Bagaimana bisa seperti ini? Tanpa ingatannya, bukankah dia akan merasa kesepian?",
  ui_story_5086_50860602_51_dialog_content = "...",
  ui_story_5086_50860602_52_dialog_content = "Jangan khawatir! Ceritanya belum berakhir!",
  ui_story_5086_50860602_53_dialog_content = "Sekarang bagaimana kelanjutan ceritanya lagi ya?",
  ui_story_5086_50860602_54_dialog_content = "Oh, benar! Bahkan setelah pangeran kembali ke kerajaannya, dia tidak bisa berhenti memikirkan gadis cantik yang telah menyelamatkan hidupnya.",
  ui_story_5086_50860602_55_dialog_content = "Jadi dia kembali ke laut tempat mereka pertama kali bertemu, tetapi gadis itu tak di mana-mana.",
  ui_story_5086_50860602_56_dialog_content = "Meski begitu, sang pangeran menolak untuk menyerah. Dia memanggil makhluk-makhluk laut dan bertanya kepada masing-masing dari mereka apakah mereka tahu kemana dia pergi.",
  ui_story_5086_50860602_57_dialog_content = "Pertama, dia bertanya pada seekor paus...",
  ui_story_5086_50860602_58_dialog_content = "<color=#e8d9bb>Guyuran.</color>",
  ui_story_5086_50860602_59_dialog_content = "<color=#e8d9bb>Kerang Maya mulai membuat suara lagi.</color>",
  ui_story_5086_50860602_60_dialog_content = "<color=#e8d9bb>Seolah-olah tertarik, seekor paus muncul di sisi lain kaca dan berenang dengan anggun bolak-balik.</color>",
  ui_story_5086_50860602_61_dialog_content = "Kemudian, dia bertanya pada seorang flounder...",
  ui_story_5086_50860602_62_dialog_content = "<color=#e8d9bb>Di tangki lain, sekolah ikan flounder melintas cepat di depan mereka.</color>",
  ui_story_5086_50860602_63_dialog_content = "Setelah itu, dia bertanya pada kepiting...",
  ui_story_5086_50860602_64_dialog_content = "<color=#e8d9bb>Dari pameran pantai terdekat, beberapa kepiting mengintip keluar dari pasir.</color>",
  ui_story_5086_50860602_65_dialog_content = "<color=#e8d9bb>Tak terhitung jumlahnya, roh air berkumpul diam-diam di sekitar Maya dan menari mengikuti melodi conch-nya.</color>",
  ui_story_5086_50860602_66_dialog_content = "Dengan bantuan mereka, sang pangeran melakukan perjalanan ke ujung terjauh laut.",
  ui_story_5086_50860602_67_dialog_content = "Dan di sana, di pantai, dia akhirnya bertemu kembali dengan gadis yang telah menyelamatkannya.",
  ui_story_5086_50860602_68_dialog_content = "Siapa kamu? dia bertanya dengan wajah bingung.",
  ui_story_5086_50860602_69_dialog_content = "Akhirnya aku menjadi milikmu, jawabnya. \"Aku mencintaimu.\"",
  ui_story_5086_50860602_70_dialog_content = "Dan kedua orang itu hidup bahagia selama-lamanya.",
  ui_story_5086_50860602_71_dialog_content = "Saat tangan mereka bersentuhan, kenangan gadis itu tiba-tiba kembali mengalir ke dalam hatinya.",
  ui_story_5086_50860602_72_dialog_content = "Ketika berbicara tentang dongeng, cinta selalu lebih kuat daripada sihir yang paling kuat sekalipun. Itu adalah jawaban untuk setiap masalah!",
  ui_story_5086_50860701_1_dialog_content = "Apa cerita yang hebat! Bisakah kamu menceritakan yang lain? Tolong?!",
  ui_story_5086_50860701_2_dialog_content = "Baiklah, mari kita lihat...",
  ui_story_5086_50860701_3_dialog_content = "Perhatian, pengunjung dan staf. Karena keadaan darurat yang tidak terduga, akuarium akan ditutup lebih awal hari ini.",
  ui_story_5086_50860701_4_dialog_content = "Silakan ikuti anggota staf kami ke lobi secepat mungkin.",
  ui_story_5086_50860701_5_dialog_content = "Itu adalah suara Miss Stellandine. Aku bertanya-tanya apa yang terjadi...",
  ui_story_5086_50860701_6_dialog_content = "Seorang pengunjung telah melaporkan hilangnya seorang teman. Akuarium sedang bekerja sama dengan penjaga kota untuk menyelidiki masalah tersebut.",
  ui_story_5086_50860701_7_dialog_content = "Mari kita lihat.",
  ui_story_5086_50860701_8_dialog_content = "Tunggu—",
  ui_story_5086_50860701_9_dialog_content = "Eclipsite lebih baik berhati-hati! Aku tidak akan mentolerir pengkhianatan di bawah pengawasanku!",
  ui_story_5086_50860701_10_dialog_content = "Sadie, santai saja! Mereka mungkin saja terpisah; kita belum tahu apa-apa dengan pasti.",
  ui_story_5086_50860701_11_dialog_content = "Jika Super Swashbuckler Sadie tidak bisa tetap tenang dalam situasi ini, orang biasa akan semakin panik.",
  ui_story_5086_50860701_12_dialog_content = "Miss Stellandine! Apakah semua orang baik-baik saja?!",
  ui_story_5086_50860701_13_dialog_content = "Huff... Meskipun dia hanya seorang anak kecil, menggendongnya sejauh ini sungguh menyiksa lengan dan kakiku...",
  ui_story_5086_50860701_14_dialog_content = "Bagus, Maya dan PlayerName juga ada di sini... Hmm? Dari mana anak kecil ini datang?",
  ui_story_5086_50860701_15_dialog_content = "Maya mengatakan dia menyelinap masuk untuk melihat paus.",
  ui_story_5086_50860701_16_dialog_content = "Cukup letakkan dia di kursi itu untuk saat ini.",
  ui_story_5086_50860701_17_dialog_content = "Saya percaya semua orang di akuarium sekarang hadir dan telah diperhitungkan.",
  ui_story_5086_50860701_18_dialog_content = "Apakah Anda dapat mengkonfirmasi itu, Nona Stellandine?",
  ui_story_5086_50860701_19_dialog_content = "Saya ingat wajah setiap pengunjung. Tapi jika kamu masih ragu...",
  ui_story_5086_50860701_20_dialog_content = "Apakah ada orang lain yang kehilangan teman atau pendamping?",
  ui_story_5086_50860701_21_dialog_content = "<color=#e8d9bb>Setiap orang yang hadir melirik sekeliling, menggelengkan kepala mereka.</color>",
  ui_story_5086_50860701_22_dialog_content = "Bukan siapa-siapa...",
  ui_story_5086_50860701_23_dialog_content = "(Minos pasti tahu sesuatu. Aku harus pergi bertanya padanya.)",
  ui_story_5086_50860701_24_dialog_content = "Hei, Minos... Huh? Kemana dia pergi? Dia baru saja di sini beberapa detik yang lalu.",
  ui_story_5086_50860701_25_dialog_content = "Saya melihat dia mengantar seseorang melewati lorong itu.",
  ui_story_5086_50860701_26_dialog_content = "Terima kasih, Goldie.",
  ui_story_5086_50860701_27_dialog_content = "Heheh, kamu bisa meninggalkan tempat ini padaku, sekarang pergi lakukan halmu!",
  ui_story_5086_50860701_28_dialog_content = "Tidak mungkin dia akan meninggalkan saya tanpa mengatakan apa-apa!",
  ui_story_5086_50860701_29_dialog_content = "Akuarium ini tidak begitu besar. Seorang dewasa tidak mungkin bisa tersesat di sini selama ini!",
  ui_story_5086_50860701_30_dialog_content = "Tidak... Pasti ada sesuatu yang terjadi padanya!",
  ui_story_5086_50860701_31_dialog_content = "*menangis* Ini semua salahku... Aku seharusnya tidak memaksa untuk datang ke sini!",
  ui_story_5086_50860701_32_dialog_content = "Tolong tetap tenang. Kita belum tahu apa-apa dengan pasti.",
  ui_story_5086_50860701_33_dialog_content = "Kita harus fokus pada pencarian petunjuk dan menemukan temanmu.",
  ui_story_5086_50860701_34_dialog_content = "Untungnya, seorang Caelestite yang sangat membantu baru saja muncul di depan kami.",
  ui_story_5086_50860701_35_dialog_content = "Maaf?",
  ui_story_5086_50860701_36_dialog_content = "<color=#e8d9bb>Minos meminta pengunjung yang sedang bingung untuk kembali ke grup dan memberi isyarat kepada saya untuk bergabung dengannya lebih jauh di lorong.</color>",
  ui_story_5086_50860701_37_dialog_content = "Di sini sangat gelap.",
  ui_story_5086_50860701_38_dialog_content = "Menurut Miss Stellandine, sistem pencahayaan telah mengalami kerusakan akhir-akhir ini.",
  ui_story_5086_50860701_39_dialog_content = "Dia mengklaim telah menutup akuarium untuk pemeliharaan di masa lalu, jadi masalah listrik hari ini benar-benar tak terduga.",
  ui_story_5086_50860701_40_dialog_content = "Untungnya, hanya lampu utama di aula ini yang kehilangan daya.",
  ui_story_5086_50860701_41_dialog_content = "Cahaya ambient sangat redup, tetapi seharusnya cukup untuk menavigasi melalui koridor.",
  ui_story_5086_50860701_42_dialog_content = "Bagaimanapun, saya percaya lokasi terakhir yang diketahui dari pengunjung yang hilang adalah di tempat ini.",
  ui_story_5086_50860701_43_dialog_content = "Kok kau bisa bilang begitu?",
  ui_story_5086_50860701_44_dialog_content = "Tolong lihat pilar ini.",
  ui_story_5086_50860701_45_dialog_content = "Apa itu? Ada sesuatu yang teroles di atasnya... Tunggu, ini darah?!",
  ui_story_5086_50860701_46_dialog_content = "Apakah masih ada lagi di area ini?",
  ui_story_5086_50860701_47_dialog_content = "<color=#e8d9bb>Guyuran.</color>",
  ui_story_5086_50860701_48_dialog_content = "Wah, itu sudah dekat... Hampir saja aku terpeleset di genangan ini. Hati-hati langkahmu, Minos.",
  ui_story_5086_50860701_49_dialog_content = "Aku bisa mengatakan hal yang sama kepadamu, PlayerName. Sampai insiden ini terselesaikan, harap berhati-hati di tempat kejadian—",
  ui_story_5086_50860701_50_dialog_content = "Kita harus menghindari merusak petunjuk atau bukti apa pun.",
  ui_story_5086_50860701_51_dialog_content = "Jika kamu mengambil satu langkah lagi, kamu akan merusak jejak kaki itu di lantai.",
  ui_story_5086_50860701_52_dialog_content = "Oh, sekarang kamu memberitahuku!",
  ui_story_5086_50860701_53_dialog_content = "Tunggu, ada lebih dari satu jejak kaki di sini... Saya senang kamu bisa melihatnya meski dalam pencahayaan ini.",
  ui_story_5086_50860701_54_dialog_content = "Tapi mereka semua tercampur bersama...",
  ui_story_5086_50860701_55_dialog_content = "Berdasarkan tinggi yang diberikan oleh teman orang yang hilang, saya dapat memperkirakan ukuran sepatu mereka secara kasar.",
  ui_story_5086_50860701_56_dialog_content = "Dan berdasarkan cara mereka tumpang tindih satu sama lain, saya juga dapat kurang lebih mengetahui urutan pembuatannya.",
  ui_story_5086_50860701_57_dialog_content = "Terakhir, mengingat cara jejak kaki ini melewati pilar yang penuh dengan darah, sangat mungkin bahwa mereka milik orang yang hilang kita.",
  ui_story_5086_50860701_58_dialog_content = "Cepat sekali!",
  ui_story_5086_50860701_59_dialog_content = "Namun, ada sesuatu yang aneh tentang jejak kaki ini.",
  ui_story_5086_50860701_60_dialog_content = "Mereka tampak benar-benar normal dalam perjalanan mereka ke tengah lorong, tetapi kemudian mereka kembali dan berubah menjadi kekacauan total.",
  ui_story_5086_50860701_61_dialog_content = "Hampir seolah-olah... orang yang meninggalkan mereka bertemu dengan sesuatu yang menakutkan.",
  ui_story_5086_50860701_62_dialog_content = "Saya percaya Anda memiliki bakat menjadi detektif yang terampil, teman saya.",
  ui_story_5086_50860701_63_dialog_content = "Saya juga membuat observasi yang serupa.",
  ui_story_5086_50860701_64_dialog_content = "Seorang orang biasa akan secara alami berteriak minta bantuan ketika berhadapan dengan sesuatu yang menakutkan.",
  ui_story_5086_50860701_65_dialog_content = "Dari tampilan jejak kaki ini, saya akan berasumsi dia memiliki cukup waktu untuk berteriak.",
  ui_story_5086_50860701_66_dialog_content = "Sayangnya, pertanyaan saya kepada pengunjung akuarium lainnya mengungkapkan bahwa tidak satupun dari mereka yang berada di dekat koridor ini lebih awal sore ini.",
  ui_story_5086_50860701_67_dialog_content = "Orang-orang yang telah melewati sini juga tidak melaporkan sesuatu yang tidak biasa, yang berarti bahwa waktu hilangnya orang yang hilang tidak dapat ditentukan berdasarkan pengetahuan kita saat ini.",
  ui_story_5086_50860701_68_dialog_content = "Sebenarnya, Maya dan aku berada di dekat tempat kejadian ketika itu terjadi...",
  ui_story_5086_50860701_69_dialog_content = "Tapi Maya bermain kerangnya sepanjang waktu, yang May menjelaskan mengapa kami tidak mendengar apa-apa.",
  ui_story_5086_50860701_70_dialog_content = "Begitu rupanya. Sayang sekali.",
  ui_story_5086_50860701_71_dialog_content = "Tampaknya jejak petunjuk saat ini hanya bisa membawa kita sejauh ini.",
  ui_story_5086_50860701_72_dialog_content = "Jejak kaki berhenti tepat sebelum mereka mencapai ujung lorong... Jadi, kemana orang ini bisa pergi?",
  ui_story_5086_50860701_73_dialog_content = "... Tunggu, aku baru saja teringat sesuatu!",
  ui_story_5086_50860701_74_dialog_content = "Setelah kami selesai berbicara sebelumnya, aku merasakan kehadiran Eclipsite di suatu tempat di dalam akuarium! Itu samar, tapi tidak bisa salah!",
  ui_story_5086_50860701_75_dialog_content = "Apakah mungkin ada ruangan dan jalan rahasia di tempat ini, seperti rumah hantu?",
  ui_story_5086_50860701_76_dialog_content = "Jadi mereka bisa bersembunyi dalam gelap, dan muncul saat lampu padam.",
  ui_story_5086_50860701_77_dialog_content = "Pengunjung yang hilang bertemu dengan Eclipsite dan diserang saat mencoba melarikan diri...",
  ui_story_5086_50860702_1_dialog_content = "Sampai kita mencari setiap sudut akuarium ini, aku tidak bisa menyangkal kemungkinan adanya ruangan tersembunyi di tempat ini.",
  ui_story_5086_50860702_2_dialog_content = "Namun, kita harus menghadapi masalah mendesak lainnya...",
  ui_story_5086_50860702_3_dialog_content = "Apakah kita sudah selesai? Berapa lama lagi kita harus membuang waktu di sini?",
  ui_story_5086_50860702_4_dialog_content = "Biarkan saja penjaga kota yang menangani ini. Menangani kasus orang hilang adalah tugas mereka, bukan?",
  ui_story_5086_50860702_5_dialog_content = "Saya mengerti kekhawatiran Anda semua. Penjaga kota sudah diberitahu, tetapi akan lebih baik jika semua orang tetap di sini sampai mereka tiba.",
  ui_story_5086_50860702_6_dialog_content = "Sejujurnya, ada sesuatu yang sangat salah dengan tempat ini, dan aku tidak akan bertahan untuk mencari tahu apa itu! Aku akan memastikan untuk memberi tahu teman-temanku untuk menjauh dari tempat ini juga!",
  ui_story_5086_50860702_7_dialog_content = "Tolong jangan bilang begitu! Kita...",
  ui_story_5086_50860702_8_dialog_content = "Mengingat keadaan saat ini, kita sederhana tidak memiliki waktu untuk melakukan inspeksi yang begitu menyeluruh.",
  ui_story_5086_50860702_9_dialog_content = "Para tamu mulai merasa gelisah...",
  ui_story_5086_50860702_10_dialog_content = "Maafkan aku.",
  ui_story_5086_50860702_11_dialog_content = "Apa—Hai!",
  ui_story_5086_50860702_12_dialog_content = "Apa maksudmu, Minos? Kenapa kamu mendorongku seperti itu...",
  ui_story_5086_50860702_13_dialog_content = "Apakah ada yang salah, PlayerName?",
  ui_story_5086_50860702_14_dialog_content = "(Oh tidak, semua orang memalingkan perhatian mereka kepadaku karena aku tiba-tiba muncul!)",
  ui_story_5086_50860702_15_dialog_content = "Ahaha... M-Maaf mengganggu...",
  ui_story_5086_50860702_16_dialog_content = "Tapi saya pikir saya tahu cara untuk mengungkap kebenaran!",
  ui_story_5086_50860702_17_dialog_content = "?!",
  ui_story_5086_50860702_18_dialog_content = "(A-Apakah itu suaraku?!)",
  ui_story_5086_50860702_19_dialog_content = "Itu luar biasa, PlayerName!",
  ui_story_5086_50860702_20_dialog_content = "Sementara semua orang lain panik, kamu sudah bekerja keras mencoba memecahkan misteri, huh?",
  ui_story_5086_50860702_21_dialog_content = "Kemampuanmu untuk mengambil alih situasi sangat mengesankan!",
  ui_story_5086_50860702_22_dialog_content = "Wow, PlayerName! Aku tidak tahu kamu ingin menjadi detektif bukan bajak laut seperti aku!",
  ui_story_5086_50860702_23_dialog_content = "S-Sekarang tunggu sebentar! Itu bukan aku—",
  ui_story_5086_50860702_24_dialog_content = "Itu bukan aku yang hanya omong kosong!",
  ui_story_5086_50860702_25_dialog_content = "Hei! Jangan ganggu aku—",
  ui_story_5086_50860702_26_dialog_content = "Karena aku akan menunjuk pelaku sebenarnya!",
  ui_story_5086_50860702_27_dialog_content = "... Apa?!?",
  ui_story_5086_50860702_28_dialog_content = "Hah? Apakah kamu benar-benar begitu terkejut dengan sisi lain dari dirimu ini, PlayerName?",
  ui_story_5086_50860702_29_dialog_content = "Kamu pikir kamu siapa, berpura-pura menjadi detektif sekarang? Baca situasinya, kamu bajingan!",
  ui_story_5086_50860702_30_dialog_content = "Ah, biarkan dia. Dia hanya seorang bocah.",
  ui_story_5086_50860702_31_dialog_content = "(Mereka semua berpikir aku gila sekarang!)",
  ui_story_5086_50860702_32_dialog_content = "Tapi, aku benar-benar—",
  ui_story_5086_50860702_33_dialog_content = "Ehem.",
  ui_story_5086_50860702_34_dialog_content = "(Minos?!)",
  ui_story_5086_50860702_35_option_content = "Pemindaian Psikis!",
  ui_story_5086_50860702_36_dialog_content = "(Apa yang terjadi di sini, Minos?)",
  ui_story_5086_50860702_37_dialog_content = "(Aku akan meminta maaf dengan benar kepada kamu nanti, temanku. Tapi sebagai butler, aku tidak cocok berada di pusat perhatian.)",
  ui_story_5086_50860702_38_dialog_content = "(Karena alasan ini, saya harus meminta Anda untuk bekerja sama dengan saya, seperti yang dilakukan Manae dengan Sanae.)",
  ui_story_5086_50860702_39_dialog_content = "(Jadi, kamu membutuhkan saya untuk berperan sebagai bonekamu?)",
  ui_story_5086_50860702_40_dialog_content = "(Jika kamu mau, ya.)",
  ui_story_5086_50860702_41_dialog_content = "Tolong dengarkan, semua orang! Aku menemukan beberapa hal di lorong itu...",
  ui_story_5086_50860702_42_dialog_content = "... Jadi ketika kamu menggabungkan semuanya, terutama noda darah di tiang, kemungkinan besar orang yang hilang itu diserang.",
  ui_story_5086_50860702_43_dialog_content = "Mulai sore ini, belum ada yang meninggalkan akuarium. Itu juga berarti—",
  ui_story_5086_50860702_44_dialog_content = "Bahwa pelaku belum pergi. Dengan kata lain... Pembunuh itu ada di antara kita.",
  ui_story_5086_50860702_45_dialog_content = "Jadi nyata, anak! Apakah kamu serius menuduh kami?!",
  ui_story_5086_50860702_46_dialog_content = "Pencarian perhatianmu sudah benar-benar kelewatan! Lagipula, apa kamu benar-benar berpikir kamu bisa membangun kasus dengan bukti yang begitu tipis?!",
  ui_story_5086_50860702_47_dialog_content = "Aku tahu! Aku tahu ada yang salah dengan akuarium ini!",
  ui_story_5086_50860702_48_dialog_content = "Ketika Eclipsites menyerang Harbour City, mereka pasti telah mengubah beberapa karyawan di sini menjadi jenis mereka sendiri!",
  ui_story_5086_50860702_49_dialog_content = "Apa?! Saya sama sekali bukan Eclipsite! Dan jangan berani-berani menuding Miss Stellandine atau staf kami yang lain!",
  ui_story_5086_50860702_50_dialog_content = "Benar! Kamu tidak bisa seenaknya menuduh Maya atau Stellandine seperti itu, terutama ketika kamu tidak tahu apa-apa tentang mereka!",
  ui_story_5086_50860702_51_dialog_content = "PlayerName, meskipun saya berterima kasih atas bantuan Anda dalam penyelidikan ini, saya harus meminta Anda untuk menahan diri dari menuduh tamu-tamu kami melakukan kesalahan tanpa dasar...",
  ui_story_5086_50860702_52_dialog_content = "(Dia benar, Minos! Saya sudah bilang saya merasakan Eclipsite sebelumnya, jadi bukankah itu berarti pelaku bukan salah satu dari mereka?)",
  ui_story_5086_50860702_53_dialog_content = "(Setiap orang mulai saling curiga karena apa yang kamu katakan!)",
  ui_story_5086_50860702_54_dialog_content = "(Ini juga bagian dari alasan mengapa saya meminta kerja sama Anda.)",
  ui_story_5086_50860702_55_dialog_content = "(Kamu adalah pemuda yang cerdas, tetapi kurangnya sikap skeptis bisa menjadi perhatian di beberapa waktu.)",
  ui_story_5086_50860702_56_dialog_content = "(Hah?)",
  ui_story_5086_50860702_57_dialog_content = "Tentu saja saya bisa membuat tuduhan ini! Saya seorang Caelestite, setelah semua!",
  ui_story_5086_50860702_58_dialog_content = "Saya juga teman dekat Lady Carleen. Para ksatria Lumopolis akan lebih dari senang untuk memverifikasi semua ini ketika mereka tiba di sini.",
  ui_story_5086_50860702_59_dialog_content = "Sebagai seorang Caelestite dan sekutu tepercaya Lady Carleen, sangatlah wajar jika saya ingin menangkap pidana ini, bukan?",
  ui_story_5086_50860702_60_dialog_content = "Yang perlu saya lakukan hanyalah bergandengan tangan dengan setiap orang yang hadir, dan kemampuan psikis saya akan memungkinkan saya untuk menemukan pelaku yang sebenarnya.",
  ui_story_5086_50860702_61_dialog_content = "Dan bagaimana jika kamu tidak menemukan pelaku di antara kita?",
  ui_story_5086_50860702_62_dialog_content = "Lalu itu akan menjadi hasil terbaik yang mungkin, bukankah kamu setuju?",
  ui_story_5086_50860702_63_dialog_content = "Hah…?",
  ui_story_5086_50860702_64_dialog_content = "Tentu saja akan sangat baik jika kita bisa mencari tahu pelaku di sini dan sekarang.",
  ui_story_5086_50860702_65_dialog_content = "Tapi jika saya tidak menemukannya di antara kalian, itu hanya berarti tidak ada di antara kalian yang adalah pembunuh, bukan?",
  ui_story_5086_50860702_66_dialog_content = "Jadi, entah saya akan menemukan penjahat atau membuktikan ketidakbersalahan setiap orang. Ini adalah situasi menang-menang, bukan menurutmu?",
  ui_story_5086_50860702_67_dialog_content = "Itu sebenarnya sangat masuk akal! Di sini, biarkan aku yang pergi terlebih dahulu!",
  ui_story_5086_50860702_68_dialog_content = "Saya kira Anda benar... Baiklah, saya akan bekerja sama.",
  ui_story_5086_50860702_69_dialog_content = "(Wow... Semua orang yang tidak kooperatif ini tiba-tiba mengantri untuk membantu.)",
  ui_story_5086_50860702_70_dialog_content = "(Aku tahu seharusnya aku boneka di sini, tapi Minos memimpin seluruh ruangan dengan hidung mereka.)",
  ui_story_5086_50860702_71_dialog_content = "(Juga, sepertinya tidak ada satupun dari mereka yang mempertimbangkan kemungkinan bahwa saya sebenarnya tidak tahu apa-apa, atau bahwa saya tidak memiliki cara untuk membuktikan bahwa siapa pun tidak bersalah...)",
  ui_story_5086_50860702_72_dialog_content = "(Sebuah respon alami. Bagaimanapun, orang-orang menjadi mudah miopi dalam situasi stres seperti ini. Ketika itu terjadi, mereka hanya melihat segala sesuatu dalam hitam dan putih.)",
  ui_story_5086_50860702_73_dialog_content = "(Tapi untuk saat ini, tolong jangan beri tahu mereka tentang kemungkinan itu.)",
  ui_story_5086_50860702_74_dialog_content = "(Mengingat keadaan kita saat ini, saya percaya bahwa menyatukan semua orang di bawah satu tujuan yang sama sangat penting.)",
  ui_story_5086_50860702_75_dialog_content = "(Aku tahu... Tapi...)",
  ui_story_5086_50860702_76_dialog_content = "(Mereka semua ingin aku menjabat tangan mereka sekarang! Apakah aku benar-benar harus menggunakan kekuatanku pada setiap orang di antara mereka?)",
  ui_story_5086_50860702_77_dialog_content = "(Tidak sama sekali, temanku.)",
  ui_story_5086_50860702_78_dialog_content = "(Setelah semua, saya hanya ingin mengamati...)",
  ui_story_5086_50860702_79_dialog_content = "(Manakah di antara orang-orang ini yang akan bertindak tidak normal di titik kritis seperti ini.)",
  ui_story_5086_50860702_80_dialog_content = "<color=#e8d9bb>Tiba-tiba, barisan orang yang menunggu untuk berjabat tangan berhenti secara mendadak.</color>",
  ui_story_5086_50860702_81_dialog_content = "Ada apa, Maya? Sekarang giliranmu, kamu tahu.",
  ui_story_5086_50860702_82_dialog_content = "Aku...",
  ui_story_5086_50860702_83_dialog_content = "(Benar; Maya berpikir bahwa kekuatanku akan mengganggu Leluhur.)",
  ui_story_5086_50860702_84_dialog_content = "Jangan khawatir, Maya, saya...",
  ui_story_5086_50860702_85_dialog_content = "<color=#e8d9bb>Klik!</color>",
  ui_story_5086_50860702_86_dialog_content = "Apa yang terjadi?! Siapa yang mematikan lampunya?!",
  ui_story_5086_50860702_87_dialog_content = "Tetap taati peraturan dan tetap tenang, semuanya—",
  ui_story_5086_50860702_88_dialog_content = "Seseorang mengunci pintu masuk! Sekarang kita semua terjebak di sini!",
  ui_story_5086_50860702_89_dialog_content = "Minggir! Tidak ada pintu yang bisa bertahan—",
  ui_story_5086_50860702_90_dialog_content = "<color=#e8d9bb>Brak!</color>",
  ui_story_5086_50860702_91_dialog_content = "<color=#e8d9bb>Di tengah kebingungan, suara pecahan kaca menembus udara.</color>",
  ui_story_5086_50860702_92_dialog_content = "<color=#e8d9bb>Sebelum siapa pun bisa bereaksi, tangki yang mengelilingi lobi akuarium meledak.</color>",
  ui_story_5086_50860702_93_dialog_content = "<color=#e8d9bb>Lobi cepat-cepat dibanjiri air dingin dan ikan yang tak terhitung jumlahnya.</color>",
  ui_story_5086_50860801_1_dialog_content = "PlayerName—!",
  ui_story_5086_50860801_2_dialog_content = "Argh... Batuk, batuk, batuk—",
  ui_story_5086_50860801_3_dialog_content = "Kamu baik-baik saja?",
  ui_story_5086_50860801_4_dialog_content = "Ya, saya baru saja menelan sedikit air, itu saja... Terima kasih sudah menyelamatkan saya.",
  ui_story_5086_50860801_5_dialog_content = "Jangan berterima kasih kepada saya, berterima kasih kepada Goldie.",
  ui_story_5086_50860801_6_dialog_content = "Setiap orang tersapu ketika tangki meledak, tetapi dia berhasil memancing kami berdua keluar dari air.",
  ui_story_5086_50860801_7_dialog_content = "Itu hanya keberuntungan bodoh, itu saja.",
  ui_story_5086_50860801_8_dialog_content = "Saat tank-tank itu meledak, aku adalah yang paling jauh, jadi aku punya sedikit lebih banyak waktu untuk bereaksi.",
  ui_story_5086_50860801_9_dialog_content = "Namun, aku tidak bisa melihat apa-apa dalam gelap tadi, jadi aku berpegangan pada dua orang yang paling dekat denganku.",
  ui_story_5086_50860801_10_dialog_content = "Untungnya, saat arus membawa kita terbawa, saya juga berhasil membuka pintu area istirahat ini dan menarik kita keluar dari air.",
  ui_story_5086_50860801_11_dialog_content = "(Itu sama sekali tidak terdengar seperti keberuntungan bodoh, Goldie...)",
  ui_story_5086_50860801_12_dialog_content = "Pokoknya... Bagaimana ini semua bisa terjadi...?",
  ui_story_5086_50860801_13_dialog_content = "<color=#e8d9bb>Air terus mengalir melalui celah-celah pintu, secara bertahap meningkatkan level air di ruangan.</color>",
  ui_story_5086_50860801_14_dialog_content = "Saya tahu ini adalah akuarium, tapi kenapa rasanya seperti ada jumlah air yang tak terbatas di sini?",
  ui_story_5086_50860801_15_dialog_content = "Sepertinya ruangan ini juga tidak akan bertahan lama lagi.",
  ui_story_5086_50860801_16_dialog_content = "Jadi apa yang harus kita lakukan sekarang?",
  ui_story_5086_50860801_17_dialog_content = "Saya pikir kita perlu mencari cara untuk berkumpul kembali dengan setiap orang terlebih dahulu.",
  ui_story_5086_50860801_18_dialog_content = "Tolong—!",
  ui_story_5086_50860801_19_dialog_content = "Seseorang dalam masalah!",
  ui_story_5086_50860801_20_dialog_content = "Jangan khawatir, Super Sadie Swashbuckler 666 sedang dalam perjalanan!",
  ui_story_5086_50860801_21_dialog_content = "Tunggu—",
  ui_story_5086_50860801_22_dialog_content = "Kami akan pergi denganmu.",
  ui_story_5086_50860801_23_dialog_content = "Sebelah sana! Lihat!",
  ui_story_5086_50860801_24_dialog_content = "<color=#e8d9bb>Air di koridor sudah setinggi pinggang. Sebuah kelompok pengunjung berteriak minta tolong dari atas sepotong kayu yang mengapung.</color>",
  ui_story_5086_50860801_25_dialog_content = "<color=#e8d9bb>Yang berenang menuju mereka adalah ikan hiu raksasa—</color>",
  ui_story_5086_50860801_26_dialog_content = "Hilanglah, kau pecundang besar!",
  ui_story_5086_50860801_27_dialog_content = "<color=#e8d9bb>Yang mengejutkan, serangan Sadie memaksa hiu itu mundur beberapa kaki.</color>",
  ui_story_5086_50860801_28_dialog_content = "Jangan khawatir, seorang swashbuckler selalu melindungi siapa pun yang membutuhkan!",
  ui_story_5086_50860801_29_dialog_content = "Di sini, PlayerName! Pegang ini!",
  ui_story_5086_50860801_30_dialog_content = "Sebuah jaring pancing? Darimana kamu mendapatkan ini?",
  ui_story_5086_50860801_31_dialog_content = "Aku hampir terjerat olehnya saat dalam perjalanan ke sini. Aku pikir mungkin nanti bisa bermanfaat, jadi aku membawanya.",
  ui_story_5086_50860801_32_dialog_content = "Mari kita gunakan!",
  ui_story_5086_50860801_33_dialog_content = "Pikir kita bisa melakukan ini bersama, Sadie?",
  ui_story_5086_50860801_34_dialog_content = "Tentu saja! Seorang swashbuckler tidak pernah menyerah!",
  ui_story_5086_50860801_35_dialog_content = "Lalu, ikuti aba-abaku—",
  ui_story_5086_50860801_36_dialog_content = "Tiga.",
  ui_story_5086_50860801_37_dialog_content = "<color=#e8d9bb>Sadie mengangkat tongkat bisbolnya.</color>",
  ui_story_5086_50860801_38_dialog_content = "Dua.",
  ui_story_5086_50860801_39_dialog_content = "<color=#e8d9bb>Goldie dan aku merayap ke depan dengan diam-diam.</color>",
  ui_story_5086_50860801_40_dialog_content = "Satu!",
  ui_story_5086_50860801_41_dialog_content = "<size=50>Kamu diusir dari sini—!</size>",
  ui_story_5086_50860801_42_dialog_content = "<color=#e8d9bb>Ikan hiu mendarat dengan sempurna di dalam jaring yang menunggu.</color>",
  ui_story_5086_50860801_43_dialog_content = "Bagus sekali, semuanya.",
  ui_story_5086_50860801_44_dialog_content = "Kamu hampir tidak berkeringat barusan, Goldie... Apakah aku benar-benar tidak bugar?",
  ui_story_5086_50860801_45_dialog_content = "Heehee!",
  ui_story_5086_50860801_46_dialog_content = "Ayo Sadie, mari kita berangkat—!",
  ui_story_5086_50860801_47_dialog_content = "<color=#e8d9bb>Tiba-tiba, bayangan besar muncul di air di belakang Sadie.</color>",
  ui_story_5086_50860801_48_dialog_content = "Keluar dari sana, Sadie!",
  ui_story_5086_50860801_49_dialog_content = "*Meraung*",
  ui_story_5086_50860801_50_dialog_content = "!",
  ui_story_5086_50860801_51_dialog_content = "(A-Aku terlambat...)",
  ui_story_5086_50860801_52_dialog_content = "<size=50>Putusan Cepat.</size>",
  ui_story_5086_50860801_53_dialog_content = "<size=50>Manae Tak Tertandingi!</size>",
  ui_story_5086_50860801_54_dialog_content = "Permintaan maaf kami karena memakan waktu begitu lama, semuanya.",
  ui_story_5086_50860801_55_dialog_content = "Saya hanya pergi sebentar untuk mengambil Sanae, tetapi tampaknya sejumlah makhluk jahat telah muncul selama kita tidak ada.",
  ui_story_5086_50860801_56_dialog_content = "<color=#e8d9bb>Minos berdiri dengan sempurna di atas pita di udara dan memberikan hormat yang sopan.</color>",
  ui_story_5086_50860801_57_dialog_content = "<color=#e8d9bb>Di bawah lengan kirinya ada Sanae yang tampak sangat cemas.</color>",
  ui_story_5086_50860801_58_dialog_content = "Um... T-Tolong maafkan aku! Aku tidak bermaksud tidur sepanjang waktu!",
  ui_story_5086_50860801_59_dialog_content = "B-Tapi sekarang aku di sini, aku akan melakukan segala yang bisa aku lakukan untuk memperbaiki semuanya!",
  ui_story_5086_50860801_60_dialog_content = "Itu jauh lebih baik, Sanae. Sekarang mulailah, jika kamu berkenan.",
  ui_story_5086_50860801_61_dialog_content = "Ha?",
  ui_story_5086_50860801_62_dialog_content = "Hati-hati, setiap orang! Lebih banyak Eclipsites sedang dalam perjalanan!",
  ui_story_5086_50860802_1_dialog_content = "Graaah...",
  ui_story_5086_50860802_2_dialog_content = "Akhirnya selesai... Berapa banyak Eclipsites yang bersembunyi di bawah air?",
  ui_story_5086_50860802_3_dialog_content = "Ini mungkin tidak membuktikan teori Anda tentang ruangan tersembunyi di akuarium, tetapi ini masih merupakan bukti yang meyakinkan.",
  ui_story_5086_50860802_4_dialog_content = "Apakah ini benar-benar waktunya untuk itu, Minos?",
  ui_story_5086_50860802_5_dialog_content = "Tentu saja. Sampai kebenaran menjadi jelas, kita tidak boleh kehilangan fokus pada penyelidikan kita.",
  ui_story_5086_50860802_6_dialog_content = "Ah!",
  ui_story_5086_50860802_7_dialog_content = "Saya tidak tahu apa yang kalian bicarakan, tetapi hiu itu menuju langsung ke arah kita!",
  ui_story_5086_50860802_8_dialog_content = "<color=#e8d9bb>Suara jaring ikan yang putus mengisi lorong saat hiu berhasil melepaskan diri dari belenggunya!</color>",
  ui_story_5086_50860802_9_dialog_content = "<color=#e8d9bb>Lebih jauh, semakin banyak bayangan berbahaya muncul di bawah permukaan air.</color>",
  ui_story_5086_50860802_10_dialog_content = "Di belakang kita! Dan jumlah mereka bertambah banyak!",
  ui_story_5086_50860802_11_dialog_content = "Kami akan dimakan hidup-hidup!!!",
  ui_story_5086_50860802_12_dialog_content = "... Apakah setiap orang masih memiliki cukup kekuatan untuk bertarung?",
  ui_story_5086_50860802_13_dialog_content = "Aku cukup lelah, tapi bertarung sampai akhir yang pahit adalah satu-satunya cara untuk keluar.",
  ui_story_5086_50860802_14_dialog_content = "Selama ada satu penggemar, seorang idola tidak boleh menunjukkan sedikit pun tanda kelelahan!",
  ui_story_5086_50860802_15_dialog_content = "Pelayan dan kepala pelayan tidak berbeda. Namun...",
  ui_story_5086_50860802_16_dialog_content = "<color=#e8d9bb>Suara familiar dari sebuah kerang bergema.</color>",
  ui_story_5086_50860802_17_dialog_content = "<color=#e8d9bb>Ikan hiu yang mengamuk berbalik arah tiba-tiba dan berenang ke arah musik.</color>",
  ui_story_5086_50860802_18_dialog_content = "Tampaknya kita bisa menurunkan senjata kita sekarang.",
  ui_story_5086_50860802_19_dialog_content = "Mari kita ikuti itu.",
  ui_story_5086_50860802_20_dialog_content = "<color=#e8d9bb>Dipantulkan oleh berbagai pecahan kaca yang tak terhitung jumlahnya, cahaya kabur yang berkilauan mengisi seluruh akuarium.</color>",
  ui_story_5086_50860802_21_dialog_content = "<color=#e8d9bb>Sosok Maya yang kabur bisa terlihat berdiri di ujung lorong yang gelap.</color>",
  ui_story_5086_50860802_22_dialog_content = "<color=#e8d9bb>Tertarik oleh melodi indah dari kerang, makhluk akuatik berbagai bentuk dan ukuran berenang menuju padanya.</color>",
  ui_story_5086_50860802_23_dialog_content = "Maya—",
  ui_story_5086_50860802_24_dialog_content = "Jangan bergerak!",
  ui_story_5086_50860802_25_dialog_content = "Nona Stellandine? Dan Froude, dan seluruh pengunjung lainnya... Syukurlah kalian semua baik-baik saja!",
  ui_story_5086_50860802_26_dialog_content = "Kamu menyebut ini \"baik-baik saja\"?! Tidakkah kamu melihat gadis itu memerintahkan semua ikan itu untuk menyerang kita?!",
  ui_story_5086_50860802_27_dialog_content = "Kita pasti sudah jadi umpan ikan sekarang jika pemilik akuarium tidak ada di sini untuk melindungi kita!",
  ui_story_5086_50860802_28_dialog_content = "Orang yang hilang sebelumnya mungkin juga korban gadis itu! Jika kalian pikir kalian cukup kuat, hadapi dia sekarang juga!",
  ui_story_5086_50860802_29_dialog_content = "Ha?",
  ui_story_5086_50860802_30_dialog_content = "Tentu saja tidak...",
  ui_story_5086_50860802_31_dialog_content = "Dia berusaha kabur!",
  ui_story_5086_50860802_32_dialog_content = "...",
  ui_story_5086_50860802_33_dialog_content = "Tunggu, Maya!",
  ui_story_5086_50860802_34_dialog_content = "Argh, aku tidak bisa bergerak cukup cepat di air! Aku tidak bisa mengejar—",
  ui_story_5086_50860802_35_dialog_content = "Serahkan ini padaku, Tuan PlayerName. Tolong awasi yang lain di ujungku.",
  ui_story_5086_50860802_36_dialog_content = "<color=#e8d9bb>Minos melompat lincah melintasi puing-puing yang mengapung dan mengejar Maya.</color>",
  ui_story_5086_50860802_37_dialog_content = "... Kita tidak bisa terus tinggal di sini. Kita perlu menemukan tempat yang aman untuk setiap orang berteduh.",
  ui_story_5086_50860802_38_dialog_content = "Air masih belum mencapai lantai dua. Kita harus mencoba membuat jalan kita ke sana.",
  ui_story_5086_50860802_39_dialog_content = "Aku tidak akan pergi dengan kalian! Aku harus pergi mencari Miss Maya!",
  ui_story_5086_50860802_40_dialog_content = "Maaf, si kecil, tetapi kita sebaiknya membahas ini setelah semua orang aman.",
  ui_story_5086_50860802_41_dialog_content = "Tidak mungkin! Kamu wanita jahat, jadi jauhkan tanganmu dariku!",
  ui_story_5086_50860802_42_dialog_content = "Izinkan saya, Nona Stellandine.",
  ui_story_5086_50860802_43_dialog_content = "Aku tahu kamu sedih, nak, tapi kamu harus tetap positif di saat-saat seperti ini! Jika kamu tidak tersenyum saat menghadapi kesulitan, kamu tidak akan bahagia dalam waktu yang lama!",
  ui_story_5086_50860802_44_dialog_content = "B-Tapi mereka mengatakan semua hal buruk itu tentang Nona Maya!",
  ui_story_5086_50860802_45_dialog_content = "Aku tahu, dan itu bukan cara untuk berbicara tentang siapa pun. Tapi kamu sama sekali tidak setuju dengan mereka, bukan?",
  ui_story_5086_50860802_46_dialog_content = "H-Hah? Apakah kamu... Percaya padaku?",
  ui_story_5086_50860802_47_dialog_content = "Hmm... Aku tidak yakin, karena aku baru saja bertemu dengannya untuk pertama kalinya hari ini.",
  ui_story_5086_50860802_48_dialog_content = "Jadi, Froude, tolong beritahu aku dan semua orang lainnya mengapa Maya tidak akan pernah melakukan sesuatu yang buruk.",
  ui_story_5086_50860802_49_dialog_content = "Oke! Oke!",
  ui_story_5086_50860802_50_dialog_content = "Sepertinya semuanya baik-baik saja sekarang. Ayo pergi, Miss Stellandine.",
  ui_story_5086_50860802_51_dialog_content = "Aku akan mencoba menjaga jarak.",
  ui_story_5086_50860802_52_dialog_content = "Sepertinya anak itu tidak menyukai saya.",
  ui_story_5086_50860802_53_dialog_content = "Uh... Mungkin dia hanya cemas karena dia dekat dengan Maya.",
  ui_story_5086_50860802_54_dialog_content = "Sebenarnya, itu sama bagi saya.",
  ui_story_5086_50860802_55_dialog_content = "Saya benar-benar tidak bisa percaya bahwa Maya adalah orang yang jahat.",
  ui_story_5086_50860802_56_dialog_content = "Dia hanya... Sedikit canggung.",
  ui_story_5086_50860802_57_dialog_content = "Tapi dia gadis yang baik, tidak ada keraguan tentang itu.",
  ui_story_5086_50860802_58_dialog_content = "Mungkin ada beberapa kesalahpahaman, tetapi semoga Minos bisa meluruskan semuanya!",
  ui_story_5086_50860802_59_dialog_content = "Eh... Nona Stellandine...",
  ui_story_5086_50860802_60_dialog_content = "Apakah ini satu-satunya cara untuk mencapai lantai dua?",
  ui_story_5086_50860802_61_dialog_content = "Ya. Mengapa kamu bertanya?",
  ui_story_5086_50860802_62_dialog_content = "Tapi... Goldie dan yang lainnya telah menghilang.",
  ui_story_5086_50860802_63_dialog_content = "Dan lingkungan sekitar kita... Sepertinya semuanya telah terdistorsi dengan cara tertentu.",
  ui_story_5086_50860802_64_dialog_content = "Itu sangat mengkhawatirkan, ya...",
  ui_story_5086_50860802_65_dialog_content = "Apa kamu baik-baik saja? Kamu terlihat sangat pucat.",
  ui_story_5086_50860802_66_dialog_content = "Untuk mengatakan yang sebenarnya... Aku tidak merasa begitu baik...",
  ui_story_5086_50860802_67_dialog_content = "Tapi aku akan baik-baik saja. Silakan lanjutkan tanpa aku...",
  ui_story_5086_50860802_68_dialog_content = "Bagaimana aku bisa melakukan itu?! Ayo! Mungkin aku bukan yang terkuat, tapi aku pasti bisa membantu kamu berjalan.",
  ui_story_5086_50860802_69_dialog_content = "!",
  ui_story_5086_50860802_70_dialog_content = "... Apa itu?",
  ui_story_5086_50860802_71_dialog_content = "Sepertinya... aku merasakan Eclipsite...",
  ui_story_5086_50860901_1_dialog_content = "La-la-la♪",
  ui_story_5086_50860901_2_dialog_content = "Um... Nona Goldie?",
  ui_story_5086_50860901_3_dialog_content = "Apa kau menemukan sesuatu?",
  ui_story_5086_50860901_4_dialog_content = "Saya sudah! Lantai dua tidak banjir, dan tidak ada yang berkelahi juga.",
  ui_story_5086_50860901_5_dialog_content = "Kita hanya perlu menemukan jalan keluar untuk bisa keluar dari sini!",
  ui_story_5086_50860901_6_dialog_content = "Tidak, saya tidak berbicara tentang itu...",
  ui_story_5086_50860901_7_dialog_content = "Saya rasa dia mencoba mengatakan bahwa semua orang yang mengikuti kita telah menghilang.",
  ui_story_5086_50860901_8_dialog_content = "Ha?",
  ui_story_5086_50860901_9_dialog_content = "Mereka benar-benar pergi! Halo? PlayerName? Froude? Miss Stellandine?!",
  ui_story_5086_50860901_10_dialog_content = "Satu-satunya respons adalah gema.",
  ui_story_5086_50860901_11_dialog_content = "Tempat ini... Ada sesuatu yang terasa berbeda sekarang...",
  ui_story_5086_50860901_12_dialog_content = "Atmosfer... Sekarang sangat intens.",
  ui_story_5086_50860901_13_dialog_content = "Aku tahu, kan? Ini seperti perubahan tiba-tiba dalam gaya seni.",
  ui_story_5086_50860901_14_dialog_content = "Ada gambar-gambar super menyeramkan di kaca, dan rasanya seperti monster bisa melompat ke arah kita kapan saja.",
  ui_story_5086_50860901_15_dialog_content = "<size=50>Aaaak!</size>",
  ui_story_5086_50860901_16_dialog_content = "Berhentilah menakuti diri sendiri seperti itu! Tidak peduli seberapa menakutkannya, itu masih hanya sebuah akuarium.",
  ui_story_5086_50860901_17_dialog_content = "Tidakkah kamu ingat apa yang dikatakan Miss Maya? Ini adalah tempat kita mengalami mimpi, dan begitu kamu menyadari itu, tidak ada yang perlu ditakutkan.",
  ui_story_5086_50860901_18_dialog_content = "Tempat ini sekarang lebih mirip mimpi buruk.",
  ui_story_5086_50860901_19_dialog_content = "Mari bernyanyi, lalu.",
  ui_story_5086_50860901_20_dialog_content = "Nyanyian dari hati memiliki kekuatan untuk menembus kegelapan dan mimpi buruk!",
  ui_story_5086_50860901_21_dialog_content = "Saya benar-benar sangat gembira membaca itu di surat kabar setelah konser terakhir!",
  ui_story_5086_50860901_22_dialog_content = "Pokoknya, mari kita mulai mengumpulkan kawan-kawan kita yang tersesat.",
  ui_story_5086_50860901_23_dialog_content = "T-Tunggu sebentar...",
  ui_story_5086_50860901_24_dialog_content = "Sebelah sana... Eclipsite!",
  ui_story_5086_50860901_25_dialog_content = "Tahan sebentar lagi! Eclipsite itu pasti ada di sekitar sini!",
  ui_story_5086_50860901_26_dialog_content = "Oke... Terima kasih...",
  ui_story_5086_50860901_27_dialog_content = "Tempat ini berbeda dari sebelumnya. Rasanya seperti labirin sekarang... Ah!",
  ui_story_5086_50860901_28_dialog_content = "Lihat! Itu Sanae dan yang lainnya!",
  ui_story_5086_50860901_29_dialog_content = "Kita...",
  ui_story_5086_50860901_30_dialog_content = "<size=50>Manae Tak Tertandingi!</size>",
  ui_story_5086_50860901_31_dialog_content = "?!",
  ui_story_5086_50860901_32_dialog_content = "Ah—",
  ui_story_5086_50860901_33_dialog_content = "Nona Stellandine!",
  ui_story_5086_50860901_34_dialog_content = "Tunggu, Sanae! Itu kami!",
  ui_story_5086_50860901_35_dialog_content = "Hah? B-Bagaimana ini bisa...",
  ui_story_5086_50860901_36_dialog_content = "Sakit...",
  ui_story_5086_50860901_37_dialog_content = "B-B-Bagaimana aku bisa menyerangmu seperti itu?! Aku sangat menyesal! A-Aku pikir kamu...",
  ui_story_5086_50860901_38_dialog_content = "A-Apakah kamu baik-baik saja?",
  ui_story_5086_50860901_39_dialog_content = "... Tolong jangan sentuh aku.",
  ui_story_5086_50860901_40_dialog_content = "Hiks... Aku benar-benar, sungguh-sungguh minta maaf! Aku salah mengira kamu sebagai Eclipsite tadi...",
  ui_story_5086_50860901_41_dialog_content = "<color=#e8d9bb>Fwooo—</color>",
  ui_story_5086_50860901_42_dialog_content = "Itu suara conch Maya! Dia dekat!",
  ui_story_5086_50860901_43_dialog_content = "aku... eh...",
  ui_story_5086_50860901_44_dialog_content = "T-Tolong tetap diam sebentar. A-Aku...",
  ui_story_5086_50860901_45_dialog_content = "AH! Sadie dan Nona Goldie sudah pergi... Mereka pasti tertarik oleh suara itu.",
  ui_story_5086_50860901_46_dialog_content = "Aku akan tetap di sini dan melindungi Miss Stellandine. Tolong bantu mereka, PlayerName!",
  ui_story_5086_50860901_47_dialog_content = "Nng... Kamu juga pergi, dan jaga Maya.",
  ui_story_5086_50860901_48_dialog_content = "Aku akan pergi sekarang!",
  ui_story_5086_50860901_49_dialog_content = "(Suara keong terasa benar-benar berbeda.)",
  ui_story_5086_50860901_50_dialog_content = "<color=#e8d9bb>Fwooo—</color>",
  ui_story_5086_50860901_51_dialog_content = "(Urgh... Hanya mendengar suara itu saja membuat pikiranku menjadi kabur.)",
  ui_story_5086_50860901_52_dialog_content = "(Maya, apa yang kamu...)",
  ui_story_5086_50860901_53_dialog_content = "!",
  ui_story_5086_50860901_54_dialog_content = "Kamu benar-benar tidak berbeda dengan para pahlawan drama klasik, teman saya.",
  ui_story_5086_50860901_55_dialog_content = "Ketika kamu mengatakannya seperti itu, membuatku berpikir bahwa kamu benar-benar membutuhkan bantuan saya lagi.",
  ui_story_5086_50860901_56_dialog_content = "Ini seperti yang kamu curigai, ya.",
  ui_story_5086_50860901_57_dialog_content = "Membuatku malu untuk mengakuinya, tetapi aku hampir tidak bisa bertempur sambil menahan efek ilusi dari conch-nya.",
  ui_story_5086_50860901_58_dialog_content = "<color=#e8d9bb>Fwooo—</color>",
  ui_story_5086_50860901_59_dialog_content = "Maya!",
  ui_story_5086_50860901_60_dialog_content = "...",
  ui_story_5086_50860901_61_dialog_content = "Jangan khawatir, Minos! Aku akan melindungi pikiranmu selama kamu berjuang!",
  ui_story_5086_50860901_62_dialog_content = "Saya percaya pada kemampuan dan penilaian Anda, jadi fokus saja untuk mendekati Maya!",
  ui_story_5086_50860901_63_option_content = "Pemindaian Psikis!",
  ui_story_5086_50860901_64_dialog_content = "<color=#e8d9bb>Graw!</color>",
  ui_story_5086_50860901_65_dialog_content = "Saya hampir tidak mampu mengecewakan kawan saya sekarang setelah dia menaruh begitu banyak kepercayaan pada saya. Maafkan saya, Nona Maya, tapi saya harus meminta kerjasama Anda sekarang.",
  ui_story_5086_50860901_66_dialog_content = "!",
  ui_story_5086_50860901_67_dialog_content = "Jangan mendekat!",
  ui_story_5086_50860901_68_dialog_content = "Harap turunkan keong itu, dan saya jamin tidak ada bahaya yang akan menimpa Anda.",
  ui_story_5086_50860901_69_dialog_content = "A... Aku tidak mengerti apa yang sedang terjadi sekarang... Tapi aku tidak bisa!",
  ui_story_5086_50860901_70_dialog_content = "Aduh...",
  ui_story_5086_50860901_71_dialog_content = "Serangan psikis tiba-tiba menjadi lebih kuat— Argh, kepalaku!",
  ui_story_5086_50860901_72_dialog_content = "Tampaknya aku harus bertarung dengan serius sekarang.",
  ui_story_5086_50860901_73_dialog_content = "Maafkan aku, Miss Maya. Aku akan memberikan permintaan maaf yang layak setelah ini selesai.",
  ui_story_5086_50860901_74_dialog_content = "<size=50>Putusan Cepat!</size>",
  ui_story_5086_50860901_75_dialog_content = "Tunggu... Jangan!",
  ui_story_5086_50860901_76_dialog_content = "Aku tidak bisa berdarah! Aku tidak seharusnya!",
  ui_story_5086_50860901_77_dialog_content = "Tolong bantu aku—",
  ui_story_5086_50860901_78_dialog_content = "<color=#FFB400>Leluhur!</color>",
  ui_story_5086_50860901_79_dialog_content = "<color=#e8d9bb>Ugh!</color>",
  ui_story_5086_50860901_80_dialog_content = "<color=#e8d9bb>Tiba-tiba, kami mendengar suara nyanyian yang panjang dan jernih.</color>",
  ui_story_5086_50860901_81_dialog_content = "<color=#e8d9bb>Tak terbatas dan nyata namun sementara dan abstrak. Semua kontradiksi secara bersamaan divalidasi dalam satu momen ini.</color>",
  ui_story_5086_50860901_82_dialog_content = "<color=#e8d9bb>Warna-warna tak terhitung berkedip dan bertemu di belakang Maya.</color>",
  ui_story_5086_50860901_83_dialog_content = "Betapa megah...",
  ui_story_5086_50860901_84_dialog_content = "<color=#e8d9bb>Saya belum pernah melihat makhluk fantastis seperti itu, namun begitu saya melihatnya, saya entah bagaimana bisa memahaminya.</color>",
  ui_story_5086_50860901_85_dialog_content = "<color=#e8d9bb>Ini adalah sesuatu yang lahir dari fantasi, mimpi, dan proyeksi pikiran yang tak berujung...</color>",
  ui_story_5086_50860901_86_dialog_content = "<color=#e8d9bb>Phantom kuno yang bisa menghancurkan realitas dengan mudah.</color>",
  ui_story_5086_50860901_87_dialog_content = "<color=#e8d9bb>Dengan satu hembusan nafas, naga efemeral ini...</color>",
  ui_story_5086_50860901_88_dialog_content = "<color=#e8d9bb>... bisa mengubah bentuk semua keberadaan.</color>",
  ui_story_5086_50860901_89_dialog_content = "Apakah ini ilusi? Atau apakah kita benar-benar telah tiba di tempat lain?",
  ui_story_5086_50860901_90_dialog_content = "Dunia ini pasti ciptaan Miss Maya, tempat di mana <color=#FFB400>ilusi</color> dan <color=#FFB400>realitas</color> adalah satu dan sama.",
  ui_story_5086_50860901_91_dialog_content = "Tolong berhati-hati.",
  ui_story_5086_50860901_92_dialog_content = "Saya ragu dia menciptakan ruang ini hanya untuk kita menikmati pemandangannya.",
  ui_story_5086_50860901_93_dialog_content = "Saya ragu dia menciptakan ruang ini untuk kita menikmati pemandangannya.",
  ui_story_5086_50860902_1_dialog_content = "Kerja bagus, Minos.",
  ui_story_5086_50860902_2_dialog_content = "... Minos?",
  ui_story_5086_50860902_3_dialog_content = "Pergi lagi...",
  ui_story_5086_50860902_4_dialog_content = "Meong!",
  ui_story_5086_50860902_5_dialog_content = "Hah? Seekor kucing?",
  ui_story_5086_50860902_6_dialog_content = "Meong! Meong!",
  ui_story_5086_50860902_7_dialog_content = "Apakah kamu mencoba membuat saya mengikuti kamu?",
  ui_story_5086_50860902_8_dialog_content = "Meong!",
  ui_story_5086_50860902_9_dialog_content = "Baiklah, aku juga tidak tahu harus pergi ke mana.",
  ui_story_5086_50860902_10_dialog_content = "<color=#e8d9bb>Percikan—</color>",
  ui_story_5086_50860902_11_dialog_content = "Aduh!",
  ui_story_5086_50860902_12_dialog_content = "Ack... Glub, glub, glub...",
  ui_story_5086_50860902_13_dialog_content = "Dia... Glub, glub, glub... Tolong...",
  ui_story_5086_50860902_14_dialog_content = "Kau rupanya...",
  ui_story_5086_50860902_15_dialog_content = "<color=#e8d9bb>Guyuran.</color>",
  ui_story_5086_50860902_16_dialog_content = "Pffft! Uhuk, uhuk, uhuk...",
  ui_story_5086_50860902_17_dialog_content = "Aku... aku selamat! Terima kasih...",
  ui_story_5086_50860902_18_dialog_content = "Tanah itu tiba-tiba lenyap di bawahku, dan aku terjun ke laut. Aku pikir aku sudah mati.",
  ui_story_5086_50860902_19_dialog_content = "Wh-Apa yang kamu lakukan di sini, Miss Stellandine?",
  ui_story_5086_50860902_20_dialog_content = "Aku mendengar suara conch tidak lama setelah kamu pergi, dan hal berikutnya yang aku tahu, aku ada di sini.",
  ui_story_5086_50860902_21_dialog_content = "Dengan hanya lautan di sekelilingku, yang bisa kulakukan hanyalah menunggu di pantai ini. Itulah saat aku melihatmu jatuh ke dalam air.",
  ui_story_5086_50860902_22_dialog_content = "Aku dibawa ke tempat yang aneh oleh seekor kucing, lalu diselamatkan setelah jatuh ke laut.",
  ui_story_5086_50860902_23_dialog_content = "Hampir seperti dongeng.",
  ui_story_5086_50860902_24_dialog_content = "Mungkin... ini adalah dongeng.",
  ui_story_5086_50860902_25_dialog_content = "Tampaknya kekuatan garis keturunan Maya jauh melampaui menenangkan hati orang lain. Ini juga dapat menciptakan ilusi yang kuat.",
  ui_story_5086_50860902_26_dialog_content = "Ini mungkin saja menjadi latar dari dongeng lainnya.",
  ui_story_5086_50860902_27_dialog_content = "Namun, aku tak pernah membayangkan dia akan menggunakan kekuatannya terhadap orang lain seperti ini...",
  ui_story_5086_50860902_28_dialog_content = "Mungkin ada lebih dari yang tampak oleh mata.",
  ui_story_5086_50860902_29_dialog_content = "Ketika aku melihat Maya tadi, dia tampak khawatir tentang sesuatu.",
  ui_story_5086_50860902_30_dialog_content = "Ah! Ah-ah-aaaaah!",
  ui_story_5086_50860902_31_dialog_content = "Sepertinya aku mendengar seseorang menyanyi.",
  ui_story_5086_50860902_32_dialog_content = "Lihat ke sana, Miss Stellandine! Di sebelah air!",
  ui_story_5086_50860902_33_dialog_content = "Itu... Putri dari laut...",
  ui_story_5086_50860902_34_dialog_content = "Maksudmu putri duyung dari cerita itu? Dia cantik...",
  ui_story_5086_50860902_35_dialog_content = "Hei, ada kapal yang datang! Mungkinkah ini bagian pertama kali pangeran dan putri duyung bertemu?",
  ui_story_5086_50860902_36_dialog_content = "Saya bertanya-tanya apakah kapal itu bisa membawa kita keluar dari sini? Hei—",
  ui_story_5086_50860902_37_dialog_content = "... Ini tidak berhasil. Sepertinya orang-orang di kapal ini sama sekali tidak bisa melihat kita.",
  ui_story_5086_50860902_38_dialog_content = "...",
  ui_story_5086_50860902_39_dialog_content = "Saya rasa kita memang tidak bisa mengalahkan putri duyung dalam kontes pesona.",
  ui_story_5086_50860902_40_dialog_content = "<color=#e8d9bb>Duar!</color>",
  ui_story_5086_50860902_41_dialog_content = "Guntur? Dan langit juga telah menjadi gelap... Ini badai dalam cerita itu, ya?",
  ui_story_5086_50860902_42_dialog_content = "Namun kapalnya baik-baik saja, dan mereka bahkan telah berlayar mendekatinya dan melemparkan tangga tali untuknya...",
  ui_story_5086_50860902_43_dialog_content = "<color=#e8d9bb>Di tengah gemuruh guntur, saya menyaksikan sesuatu yang tidak dapat dipercaya.</color>",
  ui_story_5086_50860902_44_dialog_content = "<color=#e8d9bb>Putri duyung mengulurkan tangan putih saljunya dan menarik penyelamatnya ke dalam air.</color>",
  ui_story_5086_50860902_45_dialog_content = "<color=#e8d9bb>Saat teriakan memenuhi udara, bau busuk muncul dari air, yang perlahan berubah menjadi warna merah tua.</color>",
  ui_story_5086_50860902_46_dialog_content = "<color=#e8d9bb>Ketika darah akhirnya mencapai pantai, adegan mengerikan itu tiba-tiba menghilang.</color>",
  ui_story_5086_50860902_47_dialog_content = "<color=#e8d9bb>Kemudian, kita menemukan diri kita kembali di aquarium.</color>",
  ui_story_5086_50860902_48_dialog_content = "<color=#e8d9bb>Tapi bau busuk tampaknya masih mengambang di udara di sekitar kita.</color>",
  ui_story_5086_50860902_49_dialog_content = "Apa itu... Barusan...",
  ui_story_5086_50860902_50_dialog_content = "Itu... Itu bukan... Ceritanya tidak begitu!",
  ui_story_5086_50860902_51_dialog_content = "... Moya adalah anak yang berhati murni.",
  ui_story_5086_50860902_52_dialog_content = "Begitu murni hingga dia melihat, menerima, dan mencintai segala sesuatu di dunia ini dengan cara yang sama.",
  ui_story_5086_50860902_53_dialog_content = "Mungkin apa yang baru saja kita lihat bukanlah baik atau jahat di matanya.",
  ui_story_5086_50860902_54_dialog_content = "Jadi, bahkan Eclipsite mungkin entah bagaimana bisa menjadi teman-temannya.",
  ui_story_5086_50861001_1_dialog_content = "... Kita tidak bisa berhenti sekarang.",
  ui_story_5086_50861001_2_dialog_content = "Nona Stellandine, bisa kamu berdiri?",
  ui_story_5086_50861001_3_dialog_content = "Aduh...",
  ui_story_5086_50861001_4_dialog_content = "Aku tidak bisa.",
  ui_story_5086_50861001_5_dialog_content = "Maka aku akan membawamu.",
  ui_story_5086_50861001_6_dialog_content = "Apa? Tapi kamu sendiri tidak melakukannya dengan baik, bukan?",
  ui_story_5086_50861001_7_dialog_content = "Ya... kurang lebih...",
  ui_story_5086_50861001_8_dialog_content = "Tapi, aku tidak tahu berapa banyak Eclipsite yang masih bersembunyi di sekitar kita, dan aku merasakan kehadiran yang aneh di suatu tempat dekat sini.",
  ui_story_5086_50861001_9_dialog_content = "Aku juga tidak bisa meninggalkanmu di sini.",
  ui_story_5086_50861001_10_dialog_content = "Tahanlah dirimu padaku, dan beri tahu jika rasa sakitnya terlalu banyak untuk terus berjalan.",
  ui_story_5086_50861001_11_dialog_content = "Kamu adalah jiwa yang baik hati, PlayerName.",
  ui_story_5086_50861001_12_dialog_content = "Saya minta maaf karena membuat kamu terlibat dalam kekacauan ini.",
  ui_story_5086_50861001_13_dialog_content = "Tak apa, aku sudah terbiasa dengan hal seperti ini. Lagipula, aku yakin kamu lebih ingin melestarikan akuarium ini daripada siapa pun, bukan?",
  ui_story_5086_50861001_14_dialog_content = "Ya. Lebih baik tidak...",
  ui_story_5086_50861001_15_dialog_content = "Aum!",
  ui_story_5086_50861001_16_dialog_content = "!",
  ui_story_5086_50861001_17_dialog_content = "Eclipsites! Kita harus mencari jalan lain.",
  ui_story_5086_50861001_18_dialog_content = "Apakah Anda tahu di mana kita berada sekarang, Miss Stellandine?",
  ui_story_5086_50861001_19_dialog_content = "Maaf, tetapi sepertinya akuarium ini telah benar-benar rusak.",
  ui_story_5086_50861001_20_dialog_content = "Urutan ruangan telah teracak, jadi saya bahkan tidak bisa memahami arah yang kita tuju.",
  ui_story_5086_50861001_21_dialog_content = "Tebak kita hanya perlu memanfaatkan peluang yang ada.",
  ui_story_5086_50861001_22_dialog_content = "Lihat ke sana... Siapa itu?",
  ui_story_5086_50861001_23_dialog_content = "Halo, aku—",
  ui_story_5086_50861001_24_dialog_content = "B-Bantu aku!",
  ui_story_5086_50861001_25_dialog_content = "Hah? Tunggu, kenapa kamu lari?",
  ui_story_5086_50861001_26_dialog_content = "Jangan bunuh aku—",
  ui_story_5086_50861001_27_dialog_content = "Apa yang terjadi? Apakah dia sedang dikejar? Urgh...",
  ui_story_5086_50861001_28_dialog_content = "Miss Stellandine, apakah kamu mencium sesuatu yang aneh?",
  ui_story_5086_50861001_29_dialog_content = "Kamu bilang ada yang aneh...?",
  ui_story_5086_50861001_30_dialog_content = "Aku pikir itu hanya efek samping dari ilusi putri duyung tadi, tapi aku masih bisa mencium baunya sekarang.",
  ui_story_5086_50861001_31_dialog_content = "Ini bau busuk, dan sepertinya semakin mendekat...",
  ui_story_5086_50861001_32_dialog_content = "Hosh... Hosh...",
  ui_story_5086_50861001_33_dialog_content = "Hah? Siapa disana?",
  ui_story_5086_50861001_34_dialog_content = "... Sanae? K-Kamu penuh dengan darah! Apakah kamu terluka?!",
  ui_story_5086_50861001_35_dialog_content = "Tolong beri tahu aku bahwa kamu baik-baik saja!!",
  ui_story_5086_50861001_36_dialog_content = "Aaaah!",
  ui_story_5086_50861001_37_dialog_content = "Apa yang salah, Sanae?! Ini hanya kita!",
  ui_story_5086_50861001_38_dialog_content = "Aum!",
  ui_story_5086_50861001_39_dialog_content = "Woah!",
  ui_story_5086_50861001_40_dialog_content = "Apakah benda ini telah mengikuti kita selama ini?!",
  ui_story_5086_50861001_41_dialog_content = "Maaf Miss Stellandine, tapi aku harus menurunkanmu. Tolong berikan aku tongkat itu di sudut dan tetap bersama Sanae.",
  ui_story_5086_50861001_42_dialog_content = "Lupakan aku... Lari saja.",
  ui_story_5086_50861001_43_dialog_content = "Tidak mungkin! Aku akan tetap di sini untuk bertarung!",
  ui_story_5086_50861001_44_dialog_content = "Hanya karena aku biasanya berdiri di belakang semua orang bukan berarti aku tidak tahu bagaimana melindungi teman-temanku!",
  ui_story_5086_50861001_45_dialog_content = "Aum!",
  ui_story_5086_50861001_46_dialog_content = "Hah—",
  ui_story_5086_50861001_47_dialog_content = "<color=#e8d9bb>Mendera!</color>",
  ui_story_5086_50861001_48_dialog_content = "Graaah—",
  ui_story_5086_50861001_49_dialog_content = "Hah? Tidak mungkin... Apakah aku baru saja mengalahkan Eclipsite dengan satu tembakan? Aku?!",
  ui_story_5086_50861001_50_dialog_content = "Sama-sama.",
  ui_story_5086_50861001_51_dialog_content = "Sadie! Jadi, kamu yang mengambilnya.",
  ui_story_5086_50861001_52_dialog_content = "Jangan kehilangan fokus. Masih banyak lagi yang datang dari tempat itu.",
  ui_story_5086_50861001_53_dialog_content = "<size=50>Kamu harus pergi dari sini!</size>",
  ui_story_5086_50861001_54_dialog_content = "Aku akan membantu juga! Hya—",
  ui_story_5086_50861001_55_dialog_content = "Hanya karena biasanya aku berdiri di belakang semua orang bukan berarti aku tidak tahu cara melindungi teman-temanku! Itu adalah kalimat yang sangat keren!",
  ui_story_5086_50861001_56_dialog_content = "Goldie! Sadie! Kalian berdua muncul tepat pada waktunya!",
  ui_story_5086_50861001_57_dialog_content = "Idola dan swashbucklers seharusnya tidak pernah terlambat, kamu tahu!",
  ui_story_5086_50861001_58_dialog_content = "Sekarang saatnya kita untuk bersinar!",
  ui_story_5086_50861002_1_dialog_content = "Graaah—",
  ui_story_5086_50861002_2_dialog_content = "Terima kasih sudah mendengarkan!",
  ui_story_5086_50861002_3_dialog_content = "Kita aman sekarang. Syukurlah kamu berhasil tepat waktu.",
  ui_story_5086_50861002_4_dialog_content = "Saya tidak bisa melakukannya tanpa pengunjung-pengunjung itu.",
  ui_story_5086_50861002_5_dialog_content = "Mereka memberi tahu kami ada Eclipsites menyeramkan yang mengintai ke arah ini, jadi kami datang untuk melihatnya.",
  ui_story_5086_50861002_6_dialog_content = "Pasti orang itu yang baru saja kabur. Dia langsung kabur begitu melihat kita...",
  ui_story_5086_50861002_7_dialog_content = "Apakah kamu sendirian selama ini, PlayerName?",
  ui_story_5086_50861002_8_dialog_content = "Aku telah bersama Sanae dan Miss Stellandine. Aku menyuruh mereka bersembunyi di sana... Hah?",
  ui_story_5086_50861002_9_dialog_content = "Di mana mereka? Yang aku lihat hanya...",
  ui_story_5086_50861002_10_dialog_content = "Genangan darah?",
  ui_story_5086_50861002_11_dialog_content = "<color=#828282>Klik.</color>",
  ui_story_5086_50861002_12_dialog_content = "Eh... Nona Stellandine?",
  ui_story_5086_50861002_13_dialog_content = "Jangan khawatir, aku akan pergi mengunci pintu.",
  ui_story_5086_50861002_14_dialog_content = "Kita satu-satunya yang ada di sini sekarang.",
  ui_story_5086_50861002_15_dialog_content = "Jadi, kita aman.",
  ui_story_5086_50861002_16_dialog_content = "Apakah Anda yakin, Nona Stellandine?",
  ui_story_5086_50861002_17_dialog_content = "Tentu saja.",
  ui_story_5086_50861002_18_dialog_content = "Lalu kenapa...",
  ui_story_5086_50861002_19_dialog_content = "... apakah kamu terlihat seperti...",
  ui_story_5086_50861002_20_dialog_content = "... Eclipsite?",
  ui_story_5086_50861002_21_dialog_content = "...",
  ui_story_5086_50861002_22_dialog_content = "Bisakah itu berarti Sanae dan Miss Stellandine...",
  ui_story_5086_50861002_23_dialog_content = "Kita tidak bisa terburu-buru mengambil kesimpulan sampai kita menemukannya!",
  ui_story_5086_50861002_24_dialog_content = "Periksa setiap sudut ruangan. Orang tidak bisa hanya menghilang tanpa jejak, jadi pasti ada beberapa petunjuk.",
  ui_story_5086_50861002_25_dialog_content = "Benar kata Goldie! Aku akan mencari di lorong sebelah sana.",
  ui_story_5086_50861002_26_dialog_content = "PlayerName! Tunggu!",
  ui_story_5086_50861002_27_dialog_content = "Tunggu, punggungmu... Ada sesuatu yang lengket di situ. Apa ini... Serpihan?",
  ui_story_5086_50861002_28_dialog_content = "Ini terlihat sedikit menjijikkan... Serpihan-serpihan ini hampir terasa seperti daging...",
  ui_story_5086_50861002_29_dialog_content = "Jadi ketika suara itu menarik semua orang pergi, hanya kamu dan aku yang tetap tinggal...",
  ui_story_5086_50861002_30_dialog_content = "Apakah kamu yang menyerangku dari belakang?",
  ui_story_5086_50861002_31_dialog_content = "Benar sekali.",
  ui_story_5086_50861002_32_dialog_content = "... Kamu juga mengendalikan semua Eclipsite itu, Miss Stellandine?",
  ui_story_5086_50861002_33_dialog_content = "Jadi kamu sudah tahu, ya?",
  ui_story_5086_50861002_34_dialog_content = "Tentu saja. Karena saya cukup ahli dalam manipulasi.",
  ui_story_5086_50861002_35_dialog_content = "Eclipsites itu kadang-kadang bertingkah seperti... boneka.",
  ui_story_5086_50861002_36_dialog_content = "Itu cukup mengejutkan. Tapi... sudah terlambat sekarang.",
  ui_story_5086_50861002_37_dialog_content = "Aku... benar-benar lapar.",
  ui_story_5086_50861002_38_dialog_content = "Maaf, sudah lama sekali sejak aku makan makanan normal.",
  ui_story_5086_50861002_39_dialog_content = "Saya juga tidak menginginkan ini...",
  ui_story_5086_50861002_40_dialog_content = "Tapi, aku hanya tidak tahan lagi...",
  ui_story_5086_50861002_41_dialog_content = "Aku punya permintaan. Tolong... jadilah makananku!",
  ui_story_5086_50861002_42_dialog_content = "<color=#e8d9bb>Brak!</color>",
  ui_story_5086_50861002_43_dialog_content = "Kenapa harus kau melawan? Kenapa tidak ada yang berjalan sesuai keinginanku?!",
  ui_story_5086_50861002_44_dialog_content = "Maafkan saya, tapi saya adalah pembantu keluarga Andersen.",
  ui_story_5086_50861002_45_dialog_content = "Saya belum menyelesaikan tugas yang Bapak Minos percayakan kepada saya. Belum lagi Nona Nina yang menunggu kepulangan saya.",
  ui_story_5086_50861002_46_dialog_content = "A-Aku masih punya teman yang ingin kutemui lagi, jadi tolong...",
  ui_story_5086_50861002_47_dialog_content = "Aku tidak bisa membiarkan diriku dimakan olehmu.",
  ui_story_5086_50861002_48_dialog_content = "Jika kamu sangat lapar, coba makan dirimu sendiri, monster sialan!",
  ui_story_5086_50861002_49_dialog_content = "<color=#e8d9bb>Duarr...</color>",
  ui_story_5086_50861002_50_dialog_content = "Apa ini kekuatan gila?! Rasanya seperti aku sedang berhadapan dengan orang yang benar-benar berbeda!",
  ui_story_5086_50861002_51_dialog_content = "Tapi, tidak peduli seberapa kuat kamu, kamu masih terluka.",
  ui_story_5086_50861002_52_dialog_content = "Serangan!",
  ui_story_5086_50861002_53_dialog_content = "Aum!",
  ui_story_5086_50861002_54_dialog_content = "<color=#e8d9bb>Dor! Dor! Dor!</color>",
  ui_story_5086_50861002_55_dialog_content = "<color=#e8d9bb>Eclipsite menyerbu ke dalam ruangan tetapi dilemparkan keluar hanya beberapa saat kemudian—Tentu saja, tidak ada satupun dari mereka yang masih bernafas sekarang.</color>",
  ui_story_5086_50861002_56_dialog_content = "Eh?",
  ui_story_5086_50861002_57_dialog_content = "Dalam keadaan biasa, tamu-tamu harus memperlakukan tuan rumah mereka dengan hormat yang sebesar-besarnya.",
  ui_story_5086_50861002_58_dialog_content = "Karena kamu menyerang pembantu keluarga saya, kamu tidak memberi saya pilihan lain.",
  ui_story_5086_50861002_59_dialog_content = "Demi kehormatan keluarga Andersen, dan untuk meredam kemarahan saya sendiri...",
  ui_story_5086_50861002_60_dialog_content = "Aku harus meninggalkan kesopanan biasa saya.",
  ui_story_5086_50861002_61_dialog_content = "Betapa usilnya...",
  ui_story_5086_50861002_62_dialog_content = "Aum!",
  ui_story_5086_50861002_63_dialog_content = "Minggir, binatang kotor.",
  ui_story_5086_50861002_64_dialog_content = "Humph, makhluk pengecut seperti itu.",
  ui_story_5086_50861100_1_dialog_content = "Sanae—di mana kamu—",
  ui_story_5086_50861100_2_dialog_content = "Kalau kalian bisa mendengar kami, katakan sesuatu!",
  ui_story_5086_50861100_3_dialog_content = "Sanae—",
  ui_story_5086_50861100_4_dialog_content = "Nona Moya! Jangan pergi!",
  ui_story_5086_50861100_5_dialog_content = "Suara itu...!",
  ui_story_5086_50861100_6_dialog_content = "Froude! Maya!",
  ui_story_5086_50861100_7_dialog_content = "Oh, PlayerName...",
  ui_story_5086_50861100_8_dialog_content = "Kamu akan aman di sini, Froude. Maaf, tapi aku harus pergi sekarang.",
  ui_story_5086_50861100_9_dialog_content = "Aku tidak akan melakukannya! Aku tidak akan membiarkanmu pergi!",
  ui_story_5086_50861100_10_dialog_content = "Kau menemukannya? Gadis yang mengendalikan hiu-hiu itu...",
  ui_story_5086_50861100_11_dialog_content = "Jangan biarkan dia pergi!",
  ui_story_5086_50861100_12_dialog_content = "...",
  ui_story_5086_50861100_13_dialog_content = "Tolong tenang, semua orang! Maya itu—",
  ui_story_5086_50861100_14_dialog_content = "Kalian tidak tahu apa-apa tentang dia! Kalian semua sekumpulan idiot!",
  ui_story_5086_50861100_15_dialog_content = "Froude...",
  ui_story_5086_50861100_16_dialog_content = "Nyonya Maya adalah orang paling bodoh di antara mereka semua! Dia bahkan tidak tahu bagaimana menjaga dirinya sendiri!",
  ui_story_5086_50861100_17_dialog_content = "Dia tidak pernah melakukan kesalahan! Saya yakin dia juga ingin menangkap penjahat itu!",
  ui_story_5086_50861100_18_dialog_content = "Maaf, tapi bukankah Maya yang mengembalikan semua ikan itu ke tangki mereka sebelum mereka menggigit siapa pun?",
  ui_story_5086_50861100_19_dialog_content = "Aku... Aku dari sekitar sini, dan aku bisa membela Maya! Selama beberapa tahun terakhir, yang dia lakukan hanyalah membantu orang-orang di seluruh kota!",
  ui_story_5086_50861100_20_dialog_content = "Saya tidak berpikir dia bisa menyakiti siapa pun.",
  ui_story_5086_50861100_21_dialog_content = "Hoi! Apa masalahnya dengan kalian semua?!",
  ui_story_5086_50861100_22_dialog_content = "Apakah kamu serius membela dia di saat seperti ini?!",
  ui_story_5086_50861100_23_dialog_content = "Ada cara untuk mengetahui sekali dan untuk selamanya.",
  ui_story_5086_50861100_24_dialog_content = "(Minos... Terima kasih atas bantuannya.)",
  ui_story_5086_50861100_25_dialog_content = "Bukan kamu lagi, anak... Tunggu, aku ingat sekarang! Kamu Caelestite!",
  ui_story_5086_50861100_26_dialog_content = "Benar, yang berarti saya memiliki kemampuan psikis.",
  ui_story_5086_50861100_27_dialog_content = "Aku ingat kamu adalah orang pertama yang menjabat tanganku tadi. Saya sudah mengkonfirmasi bahwa kamu benar-benar tidak bersalah dalam kasus ini.",
  ui_story_5086_50861100_28_dialog_content = "I-Itu benar.",
  ui_story_5086_50861100_29_dialog_content = "Tidak bisa dipungkiri, anak itu berbakat.",
  ui_story_5086_50861100_30_dialog_content = "Itu juga berarti saya dapat membuktikan apakah Maya tidak bersalah atau tidak sekarang juga.",
  ui_story_5086_50861100_31_dialog_content = "Maaf, Maya. Aku tahu aku pernah bilang tidak akan menggunakan kekuatanku padamu jika kamu tidak setuju.",
  ui_story_5086_50861100_32_dialog_content = "Tapi saya yakin kamu adalah orang yang baik, dan banyak orang juga merasakan hal yang sama.",
  ui_story_5086_50861100_33_dialog_content = "Maya, maukah kamu membiarkan saya melakukannya?",
  ui_story_5086_50861100_34_dialog_content = "Namun...",
  ui_story_5086_50861100_35_dialog_content = "Dengarkan baik-baik, Maya.",
  ui_story_5086_50861100_36_dialog_content = "Apa yang baru saja saya katakan hanya untuk membuat orang-orang itu mundur.",
  ui_story_5086_50861100_37_dialog_content = "Jadi kamu tidak akan membaca pikiranku?",
  ui_story_5086_50861100_38_dialog_content = "Dan aku pikir itu karena aku memercayaimu sejak awal sekali.",
  ui_story_5086_50861100_39_dialog_content = "Kekuatan psikisku berlaku dua arah. Bahkan saya akan kesulitan untuk berbohong ketika pikiran kita terhubung.",
  ui_story_5086_50861100_40_dialog_content = "Itulah sebabnya aku ingin kamu melihat ke dalam pikiranku terlebih dahulu, Maya.",
  ui_story_5086_50861100_41_dialog_content = "Jika kamu berpikir aku layak mendapatkan kepercayaanmu, tolong beri tahu aku alasanmu melakukan semua ini.",
  ui_story_5086_50861100_42_dialog_content = "Apakah itu... benar-benar baik-baik saja?",
  ui_story_5086_50861100_43_dialog_content = "Terserah Anda untuk memutuskan.",
  ui_story_5086_50861100_44_dialog_content = "<color=#e8d9bb>Dengan anggukan kecil, Maya diam-diam setuju.</color>",
  ui_story_5086_50861100_45_dialog_content = "<color=#e8d9bb>Setelah itu, dia dengan gugup mengulurkan tangan dan membiarkan ujung jari kami bersentuhan.</color>",
  ui_story_5086_50861100_46_option_content = "Mindlink!",
  ui_story_5086_50861100_47_dialog_content = "<color=#e8d9bb>Di bawah sinar matahari yang mempesona, bunga-bunga berubah menjadi kupu-kupu dan beterbangan ke langit untuk menyantap awan marshmallow.</color>",
  ui_story_5086_50861100_48_dialog_content = "<color=#e8d9bb>Gelembung iridesen tak terhitung jumlahnya melayang melintasi langit, memandikan mimpi dalam kilauan mereka yang penuh khayalan.</color>",
  ui_story_5086_50861100_49_dialog_content = "(Jadi ini adalah dunia mimpi Maya... Indah.)",
  ui_story_5086_50861100_50_dialog_content = "(Tapi…)",
  ui_story_5086_50861100_51_dialog_content = "(Oh, Sobat! Kenapa aku jadi katak lagi?!)",
  ui_story_5086_50861100_52_dialog_content = "Krek, krek!",
  ui_story_5086_50861100_53_dialog_content = "<color=#e8d9bb>Brak!</color>",
  ui_story_5086_50861100_54_dialog_content = "(Aduh... Apakah bola ini terbuat dari emas murni?!)",
  ui_story_5086_50861100_55_dialog_content = "Maafkan itu, Pak Froggy! Bisakah <color=#FFB400>saya</color> mendapatkan bola saya kembali?",
  ui_story_5086_50861100_56_dialog_content = "Kodok.",
  ui_story_5086_50861100_57_dialog_content = "Terima kasih! Muah!",
  ui_story_5086_50861100_58_dialog_content = "!!!",
  ui_story_5086_50861100_59_dialog_content = "A-Apa yang sedang kamu lakukan, Maya?! Kamu tidak bisa seenaknya mencium orang—Hei, aku sudah kembali normal!",
  ui_story_5086_50861100_60_dialog_content = "Kita bisa bermain bersama jika kamu mau! Ayo!",
  ui_story_5086_50861100_61_dialog_content = "<color=#e8d9bb>Tiba-tiba, kita menemukan diri kita duduk di dalam kereta emas yang ditarik oleh enam kuda indah saat mereka melaju ke dalam gelembung besar di langit.</color>",
  ui_story_5086_50861100_62_dialog_content = "Ini adalah hutan permen! Tanah dan pohon-pohonnya terbuat dari kue dan kue kering, jadi makanlah apa pun yang kamu inginkan.",
  ui_story_5086_50861100_63_dialog_content = "Ingatlah untuk tidak makan rumah jahe di sini, atau si penyihir akan marah!",
  ui_story_5086_50861100_64_dialog_content = "<color=#e8d9bb>Setelah makan manis sampai kenyang, kami melompat ke punggung seekor angsa putih salju dan terbang ke gelembung lainnya.</color>",
  ui_story_5086_50861100_65_dialog_content = "Istana sedang mengadakan pesta dansa, dan setiap orang diundang!",
  ui_story_5086_50861100_66_dialog_content = "Jika kita memetik beberapa batang anggur dari pinggir jalan, kita bisa merajut beberapa pakaian yang bersinar lebih terang dari bulan dan bintang!",
  ui_story_5086_50861100_67_dialog_content = "<color=#e8d9bb>Setelah berganti pakaian baru yang indah, kami merangkak naik sebatang kacang panjang dan masuk ke dalam gelembung lainnya.</color>",
  ui_story_5086_50861100_68_dialog_content = "<color=#e8d9bb>Bersama, kita melaju melalui gelembung mimpi yang tak terhitung jumlahnya.</color>",
  ui_story_5086_50861100_69_dialog_content = "<color=#e8d9bb>Ada gunungan emas dan perak, bahkan ada yang terbuat dari kaca...</color>",
  ui_story_5086_50861100_70_dialog_content = "<color=#e8d9bb>Kami juga mendengar sebuah konser yang dimainkan oleh seekor keledai, ayam jantan, kucing, dan anjing...</color>",
  ui_story_5086_50861100_71_dialog_content = "... Dan di sisi lain kota ada seorang dokter yang tahu segalanya.",
  ui_story_5086_50861100_72_dialog_content = "Dia tahu segalanya tentang dunia, dan bisa menjawab setiap pertanyaan!",
  ui_story_5086_50861100_73_dialog_content = "Benarkah? Jika kita memiliki kesempatan untuk melihatnya, saya ingin bertanya sesuatu padanya—",
  ui_story_5086_50861100_74_dialog_content = "Dapatkah kamu beritahu saya di mana menemukan Maya yang asli?",
  ui_story_5086_50861100_75_dialog_content = "...",
  ui_story_5086_50861100_76_dialog_content = "Aneh sekali.",
  ui_story_5086_50861100_77_dialog_content = "<color=#e8d9bb>Cahaya aneh berkilauan di mata Maya.</color>",
  ui_story_5086_50861100_78_dialog_content = "Kapan kau menyadarinya?",
  ui_story_5086_50861100_79_dialog_content = "Sejak awal.",
  ui_story_5086_50861100_80_dialog_content = "Ketika Maya menceritakan kisahnya kepada kami, saya pikir tidak apa-apa jika ada orang yang mengingat keberadaannya.",
  ui_story_5086_50861100_81_dialog_content = "Maya mengatakan kita menjadi teman segera setelah kita memperkenalkan diri.",
  ui_story_5086_50861100_82_dialog_content = "Jadi, mengenangnya adalah hal paling sedikit yang bisa saya lakukan, bukan?",
  ui_story_5086_50861100_83_dialog_content = "Buku catatan tidak seharusnya menjadi satu-satunya hal yang membuktikan keberadaannya di dunia ini.",
  ui_story_5086_50861100_84_dialog_content = "Tapi kemudian... Siapa yang mengawasinya sebelum dia bertemu orang lain?",
  ui_story_5086_50861100_85_dialog_content = "...",
  ui_story_5086_50861100_86_dialog_content = "Selain darahku, keturunanku juga mewarisi kekuatan untuk memanipulasi lingkungan mereka, bahkan realitas itu sendiri.",
  ui_story_5086_50861100_87_dialog_content = "Dengan berjalannya waktu, garis keturunan saya telah melemah dan keturunan saya tidak lagi dapat mengendalikan kekuatan ini.",
  ui_story_5086_50861100_88_dialog_content = "Bukan hanya dia tidak mampu mengendalikan kekuatanku, tetapi hubungan darah kita juga telah menjadi samar. Ini menyebabkan dia kehilangan ingatannya dan tenggelam dalam dunia fantasi.",
  ui_story_5086_50861100_89_dialog_content = "Jika pemegang tidak bisa mengendalikan kekuatanku, itu juga akan mempengaruhi orang-orang di sekitarnya. Hanya melihat atau mencium darahku atau mendengar suaraku akan menjebak mereka dalam ilusi.",
  ui_story_5086_50861100_90_dialog_content = "Jadi ketika Maya mengatakan dia tidak bisa berdarah...",
  ui_story_5086_50861100_91_dialog_content = "Namun, situasi di akuarium pasti ada hubungannya dengan kekuatan Maya.",
  ui_story_5086_50861100_92_dialog_content = "Jika kamu adalah Leluhur yang dia sebutkan sebelumnya... Bisakah kamu memberitahuku apa yang terjadi di sini?",
  ui_story_5086_50861100_93_dialog_content = "Seperti yang saya katakan sebelumnya, keturunan saya tidak memiliki kemampuan untuk mengendalikan mimpi.",
  ui_story_5086_50861100_94_dialog_content = "Namun demikian, dia telah menyelesaikan semua ini.",
  ui_story_5086_50861100_95_dialog_content = "Jika kamu benar-benar temannya, maka kamu harus tahu penyebab dari peristiwa-peristiwa ini.",
  ui_story_5086_50861100_96_dialog_content = "... Kamu benar.",
  ui_story_5086_50861100_97_dialog_content = "May Bisakah saya mengajukan satu pertanyaan terakhir kepada Anda?",
  ui_story_5086_50861100_98_dialog_content = "Dunia Maya itu seperti dongeng. Itu adalah tempat yang sempurna yang memiliki segala yang diinginkan oleh seseorang.",
  ui_story_5086_50861100_99_dialog_content = "Tapi saya menyadari sesuatu yang aneh saat kita terbang melalui semua mimpi itu... Mengapa saya tidak melihat lautan di salah satunya?",
  ui_story_5086_50861100_100_dialog_content = "Anda pasti sudah melihat laut sampai sekarang.",
  ui_story_5086_50861100_101_dialog_content = "Di dalam mimpi buruk yang tidak berani dilihat oleh keturunanku.",
  ui_story_5086_50861100_102_dialog_content = "Baiklah... Aku paham sekarang.",
  ui_story_5086_50861100_103_dialog_content = "Apa kamu akan menjawab pertanyaan dari diriku sendiri?",
  ui_story_5086_50861100_104_dialog_content = "Tentu saja. Tanyakan apa saja padaku.",
  ui_story_5086_50861100_105_dialog_content = "Jika...",
  ui_story_5086_50861100_106_dialog_content = "Hah? Kamu...",
  ui_story_5086_50861100_107_dialog_content = "Jika aku memberimu semua gaunku, permata, dan mutiara...",
  ui_story_5086_50861100_108_dialog_content = "Maukah kamu tinggal di sini bersamaku selamanya?",
  ui_story_5086_50861100_109_dialog_content = "...",
  ui_story_5086_50861100_110_dialog_content = "Saya sama sekali tidak menginginkan harta karun Anda, Maya.",
  ui_story_5086_50861100_111_dialog_content = "Aku hanya ingin kamu tersenyum.",
  ui_story_5086_50861100_112_dialog_content = "Dan itu adalah kenyataannya, baik di sini maupun di dunia nyata.",
  ui_story_5086_50861100_113_dialog_content = "!",
  ui_story_5086_50861100_114_dialog_content = "<color=#e8d9bb>Nyanyian panjang dan jauh itu dimulai lagi.</color>",
  ui_story_5086_50861100_115_dialog_content = "<color=#e8d9bb>Pemandangan seperti mimpi di sekeliling mereka berubah menjadi kabut dan perlahan memudar, mengungkapkan akuarium yang kembali remang-remang.</color>",
  ui_story_5086_50861100_116_dialog_content = "Kami kembali... Hah? Mengapa semua orang tidur?",
  ui_story_5086_50861100_117_dialog_content = "Ahhh—Betapa indahnya tidur siang! Hihi!",
  ui_story_5086_50861100_118_dialog_content = "Selamat datang kembali, Maya.",
  ui_story_5086_50861100_119_dialog_content = "Aku tahu aku baru saja mengatakan semua itu, tapi kamu tidak perlu memaksakan diri untuk tersenyum jika kamu tidak merasa ingin melakukannya.",
  ui_story_5086_50861100_120_dialog_content = "Tidak akan benar jika kamu melakukannya.",
  ui_story_5086_50861100_121_dialog_content = "...",
  ui_story_5086_50861100_122_dialog_content = "Sejak tamu itu menghilang, kamu tidak pernah tersenyum sama sekali. Setidaknya, bukan senyuman yang sebenarnya.",
  ui_story_5086_50861100_123_dialog_content = "... Aku tidak tahu harus berbuat apa lagi.",
  ui_story_5086_50861100_124_dialog_content = "Jadi, kamu tahu persis siapa yang membuat orang itu hilang selama ini.",
  ui_story_5086_50861100_125_dialog_content = "Aku ingin orang merasa penyesalan ketika mereka melakukan hal buruk...",
  ui_story_5086_50861100_126_dialog_content = "Saya mengirimnya ke dalam mimpi itu untuk bertobat sampai dia siap untuk menebusnya kepada setiap orang.",
  ui_story_5086_50861100_127_dialog_content = "Aku... Aku hanya harus berusaha sedikit lebih keras untuk menjaga mimpinya!",
  ui_story_5086_50861100_128_dialog_content = "Saya yakin dia tahu apa yang dia lakukan itu salah!",
  ui_story_5086_50861100_129_dialog_content = "Jadi tolong, beri aku sedikit waktu lagi...",
  ui_story_5086_50861100_130_dialog_content = "Kamu tidak bisa menghapus kesalahan orang lain, Maya.",
  ui_story_5086_50861100_131_dialog_content = "Dan kita juga tidak bisa hidup dalam mimpi selamanya.",
  ui_story_5086_50861100_132_dialog_content = "Dan di dalam hati Anda, Anda sudah tahu itu. Itulah mengapa akuarium kembali ke keadaan ini lagi.",
  ui_story_5086_50861100_133_dialog_content = "Kamu masih belum menguasai kemampuan untuk mengendalikan mimpi, itulah sebabnya mereka menjadi menakutkan setiap kali kamu memaksa diri untuk melakukannya.",
  ui_story_5086_50861100_134_dialog_content = "Aku tak paham... Kenapa dia tidak merasa menyesal atas tindakannya? Kenapa dia terus memaksa kita untuk saling menyakiti?",
  ui_story_5086_50861100_135_dialog_content = "Mungkin karena tidak semua orang sekuat kamu, Maya.",
  ui_story_5086_50861100_136_dialog_content = "Apakah ini aku... menjadi kuat?",
  ui_story_5086_50861100_137_dialog_content = "Meski aku sedang menangis?",
  ui_story_5086_50861100_138_dialog_content = "Bukan itu sama sekali.",
  ui_story_5086_50861100_139_dialog_content = "Tidak apa-apa untuk menangis dan marah ketika kita merasa sakit atau putus asa. Itu adalah reaksi yang sangat normal.",
  ui_story_5086_50861100_140_dialog_content = "Orang kuat tidak menjadi lemah hanya karena mereka menangis.",
  ui_story_5086_50861100_141_dialog_content = "Aku tidak paham.",
  ui_story_5086_50861100_142_dialog_content = "Hmm, baiklah, izinkan saya mengatakannya dengan cara lain.",
  ui_story_5086_50861100_143_dialog_content = "Jika suatu saat kamu menemukan dirimu dalam masalah serius...",
  ui_story_5086_50861100_144_dialog_content = "Misalnya, bayangkan jika akuarium mulai mendapatkan pengunjung yang lebih sedikit dan berada dalam bahaya penutupan.",
  ui_story_5086_50861100_145_dialog_content = "Apa hal pertama yang akan kamu lakukan?",
  ui_story_5086_50861100_146_dialog_content = "Tutup...? Mustahil! Saya akan keluar dan mencari lebih banyak tamu jika itu terjadi!",
  ui_story_5086_50861100_147_dialog_content = "Jadi, apa yang akan kamu lakukan jika tidak ada orang di Harbour City yang mau mengunjungi akuarium?",
  ui_story_5086_50861100_148_dialog_content = "Pergi ke suatu tempat yang jauh, jauh sekali! Aku akan pergi ke luar Harbor City, atau sisi lain dari laut, atau bahkan sisi lain dari langit!",
  ui_story_5086_50861100_149_dialog_content = "Aku akan terus mencari! Aku yakin aku akan menemukan seseorang yang ingin mengunjungi kita akhirnya!",
  ui_story_5086_50861100_150_dialog_content = "Dan jika kamu gagal?",
  ui_story_5086_50861100_151_dialog_content = "Jika pada awalnya kamu tidak berhasil, coba dan coba lagi!",
  ui_story_5086_50861100_152_dialog_content = "Dan kamu tidak akan merasa putus asa tentang itu?",
  ui_story_5086_50861100_153_dialog_content = "Aku akan merasa buruk, tapi selalu ada hari esok! Lagipula, bukan seperti aku akan mengingat apa-apa!",
  ui_story_5086_50861100_154_dialog_content = "Tapi aku tahu selama aku terus berusaha sekuat tenaga, aku akan berhasil suatu hari nanti!",
  ui_story_5086_50861100_155_dialog_content = "Karena memang begitulah dunia ini bekerja!",
  ui_story_5086_50861100_156_dialog_content = "Dan itulah yang membuat saya kuat.",
  ui_story_5086_50861100_157_dialog_content = "Kebanyakan orang di dunia ini tidak berani berharap seperti yang kamu lakukan, Maya.",
  ui_story_5086_50861100_158_dialog_content = "Itu karena mereka hidup dalam gelembung yang dikenal sebagai realitas.",
  ui_story_5086_50861100_159_dialog_content = "Dalam gelembung itu, kerja keras tidak dijamin akan membuahkan hasil, dan keajaiban tidak terjadi hanya karena orang percaya pada mereka.",
  ui_story_5086_50861100_160_dialog_content = "Beberapa orang tidak pernah melihat akhir cerita yang bahagia. Mereka hanya menderita kesulitan demi kesulitan yang menyakitkan.",
  ui_story_5086_50861100_161_dialog_content = "Ini akan menjadi beban yang berat dan sulit untuk ditanggung, dan tidak ada yang tahu berapa lama kamu harus memikulnya.",
  ui_story_5086_50861100_162_dialog_content = "Terkadang, mereka bahkan tidak tahu apakah cerita pahit ini akan pernah berakhir.",
  ui_story_5086_50861100_163_dialog_content = "Kebanyakan orang pada akhirnya akan tumbang di bawah beban itu, tanpa cara untuk bangkit dan bergerak lagi.",
  ui_story_5086_50861100_164_dialog_content = "Tapi, aku tidak suka itu...",
  ui_story_5086_50861100_165_dialog_content = "Tak ada yang melakukannya, Maya.",
  ui_story_5086_50861100_166_dialog_content = "Jadi, mereka yang merasa tidak mungkin bertahan lebih lama memaksakannya pada orang lain.",
  ui_story_5086_50861100_167_dialog_content = "Hah…?",
  ui_story_5086_50861100_168_dialog_content = "Selama ada orang lain yang berjuang untuknya, dia bisa menderita sedikit lebih lama. Selama ada orang lain yang terluka di tempatnya, dia akan terus mendorong maju.",
  ui_story_5086_50861100_169_dialog_content = "Selama masih ada orang yang bersedia membagi beban hidupnya, dia mungkin akan melihat akhir cerita yang bahagia suatu hari nanti.",
  ui_story_5086_50861100_170_dialog_content = "...",
  ui_story_5086_50861100_171_dialog_content = "Orang itu... Dia juga seperti itu.",
  ui_story_5086_50861100_172_dialog_content = "Dia memindahkan rasa sakitnya ke orang lain hanya untuk terus berjalan.",
  ui_story_5086_50861100_173_dialog_content = "Dia melakukan hal yang buruk, sesuatu yang seharusnya tidak pernah dia lakukan.",
  ui_story_5086_50861100_174_dialog_content = "Nah, aku mengerti keinginanmu untuk membuat pelaku kesalahan bertobat.",
  ui_story_5086_50861100_175_dialog_content = "Tapi mereka yang melakukan kejahatan memiliki hati yang lemah, sehingga mereka tidak bisa menanggung beban kesalahan mereka sendiri.",
  ui_story_5086_50861100_176_dialog_content = "Meski menyedihkan, kita hanya bisa menghadapi mereka dan mencari keadilan.",
  ui_story_5086_50861100_177_dialog_content = "Maaf, Maya... Tapi itu tidak bisa dicapai hanya dengan mimpi saja.",
  ui_story_5086_50861100_178_dialog_content = "Orang baik layak mendapatkan hadiah, dan orang jahat layak dihukum. Bahkan aku tahu itu...",
  ui_story_5086_50861100_179_dialog_content = "Dan itulah satu-satunya cara cerita bisa mencapai akhirnya.",
  ui_story_5086_50861100_180_dialog_content = "Saya telah menyaksikan banyak mimpi sedih. Terima kasih telah membiarkan saya menyaksikan mimpi yang begitu berharga.",
  ui_story_5086_50861100_181_dialog_content = "Jangan khawatir, Maya... Aku akan tetap di sisimu, meskipun aku tidak bisa banyak membantu.",
  ui_story_5086_50861100_182_dialog_content = "Tidak, ini sudah lebih dari cukup.",
  ui_story_5086_50861100_183_dialog_content = "Saya tidak akan menyerah. Saya akan menyelesaikan masalah di dunia nyata sehingga setiap orang akan tersenyum lagi!",
  ui_story_5086_50861100_184_dialog_content = "Maafkan aku, Leluhur. Tolong bantu aku mengirim semua orang kembali!",
  ui_story_5086_50861100_185_dialog_content = "<color=#e8d9bb>Di momen berikutnya, akuarium yang gelap menghilang seperti gelembung yang meletus.</color>",
  ui_story_5086_50861100_186_dialog_content = "<color=#e8d9bb>Samarsamar, aku mendengar suara dari suatu tempat di dekat sini...</color>",
  ui_story_5086_50861100_187_dialog_content = "Keturunan Caelestite, aku memohonmu untuk melindungi darahku.",
  ui_story_5086_50861100_188_dialog_content = "Dia adalah keunikan, seorang yang memiliki kejujuran yang murni dan tidak tercemar.",
  ui_story_5086_50861100_189_dialog_content = "<color=#e8d9bb>Dan begitu ilusi yang terdistorsi akhirnya berakhir.</color>",
  ui_story_5086_50861201_1_dialog_content = "Urgh... Kapan aku tertidur... Hah? Semuanya kembali normal?",
  ui_story_5086_50861201_2_dialog_content = "Daya sudah menyala, dan akuarium benar-benar baik-baik saja.",
  ui_story_5086_50861201_3_dialog_content = "Bahkan pintu masih utuh, dan tidak ada yang banjir.",
  ui_story_5086_50861201_4_dialog_content = "Apakah itu semua hanya mimpi?",
  ui_story_5086_50861201_5_dialog_content = "Ah! Hai! Apakah kamu baik-baik saja?!",
  ui_story_5086_50861201_6_dialog_content = "Nng... A-Apa yang terjadi...?",
  ui_story_5086_50861201_7_dialog_content = "Kukira kamu hilang! Syukurlah kamu hanya mengalami beberapa luka ringan...",
  ui_story_5086_50861201_8_dialog_content = "Apa yang baru saja kita alami...?",
  ui_story_5086_50861201_9_dialog_content = "Ini semua hanya ilusi, tetapi berkat Maya, tidak ada orang lain yang terluka.",
  ui_story_5086_50861201_10_dialog_content = "Aku... Aku tidak bisa ingat lagi.",
  ui_story_5086_50861201_11_dialog_content = "Saya yakin Maya bingung dengan kasus-kasus tersebut dan bekerja keras untuk menyelesaikannya.",
  ui_story_5086_50861201_12_dialog_content = "Jadi, ketika dia akhirnya menangkap kejahatan pelaku, dia dengan sembrono melemparkan ilusi itu.",
  ui_story_5086_50861201_13_dialog_content = "Maya takut orang lain akan terluka, jadi dia dengan putus asa menggunakan kemampuan yang May bahkan bisa membahayakan dirinya sendiri, dan itulah sebabnya mimpi buruk hanya tetap sebagai mimpi buruk.",
  ui_story_5086_50861201_14_dialog_content = "Apakah saya berhasil menebus sebagian kesalahan orang itu?",
  ui_story_5086_50861201_15_dialog_content = "... Iya.",
  ui_story_5086_50861201_16_dialog_content = "Dimana Nona Stellandine?",
  ui_story_5086_50861201_17_dialog_content = "Kenapa hanya dia yang tidak ada di sini?",
  ui_story_5086_50861201_18_dialog_content = "Apakah ada yang terjadi? Ada segerombolan Eclipsite di belakang tadi...",
  ui_story_5086_50861201_19_dialog_content = "Itu tidak perlu.",
  ui_story_5086_50861201_20_dialog_content = "Saya khawatir dia adalah satu-satunya di antara kita yang sama sekali tidak perlu khawatir tentang Eclipsites.",
  ui_story_5086_50861201_21_dialog_content = "Minos, apakah kamu tahu sejak awal?",
  ui_story_5086_50861201_22_dialog_content = "Kamu terlalu mengagung-agungkanku. Aku juga secara bertahap mengkonfirmasi kecurigaanku melalui beberapa karakteristik.",
  ui_story_5086_50861201_23_dialog_content = "Kalian sedang membicarakan apa?",
  ui_story_5086_50861201_24_dialog_content = "Saya yakin semua dari kalian telah mendengar dongeng tentang putri duyung.",
  ui_story_5086_50861201_25_dialog_content = "Dongeng mungkin adalah fantasi, tetapi mereka masih memiliki sisi yang berakar dalam realitas—Metafora atau pelajaran.",
  ui_story_5086_50861201_26_dialog_content = "Salah satu cara untuk menafsirkan dongeng itu adalah bahwa itu menampilkan bentuk dan kebiasaan dari jenis makhluk laut.",
  ui_story_5086_50861201_27_dialog_content = "Sebuah makhluk yang mengambil bentuk Aurorian cantik menggunakan suaranya dan penampilannya untuk menarik pelaut atau pengunjung.",
  ui_story_5086_50861201_28_dialog_content = "Setelah targetnya berhasil tergoda...",
  ui_story_5086_50861201_29_dialog_content = "Ia menarik target ke dalam kedalaman laut, menjadikannya makanannya.",
  ui_story_5086_50861201_30_dialog_content = "Jadi, putri duyung itu tidak lebih dari monster yang memburu dengan \"keinginan\" sebagai umpannya.",
  ui_story_5086_50861201_31_dialog_content = "Jangan bilang padaku...",
  ui_story_5086_50861201_32_dialog_content = "Jadi, semua kejadian menghilang itu disebabkan oleh makhluk yang menyusup ke dalam kelompok kita?",
  ui_story_5086_50861201_33_dialog_content = "Tidak peduli bagaimana ia berubah, monster itu akan selalu...",
  ui_story_5086_50861201_34_dialog_content = "Diam!",
  ui_story_5086_50861201_35_dialog_content = "Eclipsite!",
  ui_story_5086_50861201_36_dialog_content = "Diam! Diam! Diam!!!",
  ui_story_5086_50861201_37_dialog_content = "Tidak, suara itu... Nyonya Stellandine?!",
  ui_story_5086_50861201_38_dialog_content = "?!",
  ui_story_5086_50861201_39_dialog_content = "Monster? Makhluk?!",
  ui_story_5086_50861201_40_dialog_content = "Jika kamu lapar, kamu makan! Itu sama untuk setiap orang!",
  ui_story_5086_50861201_41_dialog_content = "Tidak ada alasan di dunia ini yang akan mengubah fakta bahwa kamu juga bergantung pada daging dan darah makhluk hidup lain untuk bertahan hidup!",
  ui_story_5086_50861201_42_dialog_content = "Hanya saja makanan kita berbeda...",
  ui_story_5086_50861201_43_dialog_content = "Lalu mengapa kamu menahan diri sampai sekarang?",
  ui_story_5086_50861201_44_dialog_content = "!",
  ui_story_5086_50861201_45_dialog_content = "Meski kamu berjuang dalam ilusi, itu tetap layak untuk dipelajari.",
  ui_story_5086_50861201_46_dialog_content = "Kamu sangat lemah dibandingkan dengan yang lain dari jenismu.",
  ui_story_5086_50861201_47_dialog_content = "Seakan-akan... Kamu sudah lama sekali tidak makan.",
  ui_story_5086_50861201_48_dialog_content = "Apa? Apakah kamu benar-benar berpikir dengan memakan cukup banyak Aurorian akan memungkinkanmu untuk hidup seperti salah satunya?",
  ui_story_5086_50861201_49_dialog_content = "Aku menyuruhmu diam!",
  ui_story_5086_50861201_50_dialog_content = "Sejauh yang saya mengerti, makhluk seperti kamu bisa membaca dan belajar dari kenangan Aurorian yang telah kamu telan.",
  ui_story_5086_50861201_51_dialog_content = "Namun, kamu kekurangan sistem pengolahan yang komprehensif. Jadi, semakin banyak kamu menelan, semakin kacau ingatan itu.",
  ui_story_5086_50861201_52_dialog_content = "Anda seharusnya tidak pernah hidup di daratan, tetapi Stellandine sudah ada sejak lama.",
  ui_story_5086_50861201_53_dialog_content = "Tidak, seharusnya saya bilang kamu sudah \"terjebak\" terlalu lama.",
  ui_story_5086_50861201_54_dialog_content = "Bukan hanya meninggalkan lautan dan hidup seperti Aurorian, tetapi kamu juga telah menolak untuk makan dalam waktu yang lama.",
  ui_story_5086_50861201_55_dialog_content = "Aku benar-benar ingin tahu. Kenapa kamu melakukannya?",
  ui_story_5086_50861201_56_dialog_content = "A-Aku mau...",
  ui_story_5086_50861201_57_dialog_content = "Oh, begitu..",
  ui_story_5086_50861201_58_dialog_content = "Kau sudah lupa.",
  ui_story_5086_50861201_59_dialog_content = "Saya tidak memiliki pertanyaan lain. Pada akhirnya, kamu masih merupakan Eclipsite yang menyedihkan.",
  ui_story_5086_50861201_60_dialog_content = "Apa-apaan kau...!",
  ui_story_5086_50861201_61_dialog_content = "Nona Stellandine...",
  ui_story_5086_50861201_62_dialog_content = "Kamu telah melakukan banyak hal buruk dan tak termaafkan!",
  ui_story_5086_50861201_63_dialog_content = "Tapi... Aku tahu kamu benar-benar ingin menjadi seorang Aurorian... Itulah mengapa aku tidak pernah merasakan niat jahat.",
  ui_story_5086_50861201_64_dialog_content = "Jika kamu masih bersedia untuk berubah, maka saya bersedia mencari penebusan bersamamu...",
  ui_story_5086_50861201_65_dialog_content = "Miss Maya, dia adalah Eclipsite.",
  ui_story_5086_50861201_66_dialog_content = "Selama itu tetap menjadi fakta, kita akan selalu menjadi musuh.",
  ui_story_5086_50861201_67_dialog_content = "Saya tidak mencoba membela dia atau apa pun... Tapi apakah Miss Stellandine benar-benar pergi untuk selamanya?",
  ui_story_5086_50861201_68_dialog_content = "... Cukup.",
  ui_story_5086_50861201_69_dialog_content = "Nona Stellandine?",
  ui_story_5086_50861201_70_dialog_content = "Oh, Maya...",
  ui_story_5086_50861201_71_dialog_content = "Bodoh besar sekali!!",
  ui_story_5086_50861201_72_dialog_content = "…Hah?",
  ui_story_5086_50861201_73_dialog_content = "Itu dia! Itulah ekspresi yang mendapatkan kasih sayang semua orang.",
  ui_story_5086_50861201_74_dialog_content = "Sangat sedih bahwa aku tidak bisa mengingat apa-apa, tetapi aku tahu setiap orang akan menyukaiku jika aku melakukan yang terbaik dalam hidup!",
  ui_story_5086_50861201_75_dialog_content = "Aku yakin kamu sangat menikmatinya, bukan? Kamu pasti sangat puas dengan dirimu sendiri sekarang!",
  ui_story_5086_50861201_76_dialog_content = "Maya kecilku yang menyedihkan namun menggemaskan... Tapi apa gunanya? Selama hidupmu, tidak pernah sekali pun kamu melakukan sesuatu yang berarti—",
  ui_story_5086_50861201_77_dialog_content = "Tapi kenapa hanya kamu satu-satunya yang menikmati cinta semua orang?!!",
  ui_story_5086_50861201_78_dialog_content = "Tidak, Miss Stellandine... Tolong... Jangan katakan hal seperti itu...",
  ui_story_5086_50861201_79_dialog_content = "Itulah satu-satunya alasan aku begitu baik padamu! Agar rasa sakit pengkhianatan itu akan terasa lebih menyakitkan!",
  ui_story_5086_50861201_80_dialog_content = "Gadis bodoh! Apakah kamu benar-benar percaya bahwa monster akan memiliki emosi Aurorian?! Ha ha ha! Kamu benar-benar tertipu, ya?",
  ui_story_5086_50861201_81_dialog_content = "Tapi Miss Stellandine, aku bisa melihat bahwa kamu masih menangis di dalam hati...",
  ui_story_5086_50861201_82_dialog_content = "<color=#e8d9bb>Plak!</color>",
  ui_story_5086_50861201_83_dialog_content = "<color=#e8d9bb>Boneka paus tiba-tiba membanting Stellandine.</color>",
  ui_story_5086_50861201_84_dialog_content = "Bu Moya adalah orang yang jauh lebih baik daripada yang akan pernah kamu jadi!",
  ui_story_5086_50861201_85_dialog_content = "Dia menceritakan kisah-kisah dan bekerja keras untuk akuarium...",
  ui_story_5086_50861201_86_dialog_content = "Meskipun dia hampir tidak ingat apa-apa, dia selalu menemukanku di dekat paus setiap kali aku menyelinap keluar!",
  ui_story_5086_50861201_87_dialog_content = "Tapi kamu? Kamu tidak pernah repot-repot untuk mengingat nama kami!",
  ui_story_5086_50861201_88_dialog_content = "Benar, Maya memperlakukan setiap orang dengan tulus! Kamu seharusnya tidak mengecewakannya, Nona Stellandine.",
  ui_story_5086_50861201_89_dialog_content = "Terima pembalasanmu! Monster!",
  ui_story_5086_50861201_90_dialog_content = "<color=#e8d9bb>Plak! Plak! Plak!</color>",
  ui_story_5086_50861201_91_dialog_content = "<color=#e8d9bb>Boneka, kunci, dan bahkan batu dari dalam kolam akuarium... Pengunjung mulai melempari Stellandine dengan objek apa pun yang mereka temukan.</color>",
  ui_story_5086_50861201_92_dialog_content = "Astaga, sungguh pemandangan yang menyentuh...",
  ui_story_5086_50861201_93_dialog_content = "Maka, kamu semua bisa mati bersama-sama!!",
  ui_story_5086_50861202_1_dialog_content = "Sudah berakhir, Nyonya Stellandine. Baik hidupmu maupun keinginanmu.",
  ui_story_5086_50861202_2_dialog_content = "Bisakah aku... pergi kepadanya?",
  ui_story_5086_50861202_3_dialog_content = "Itu tidak disarankan, Miss Maya.",
  ui_story_5086_50861202_4_dialog_content = "Lanjutkan, Maya.",
  ui_story_5086_50861202_5_dialog_content = "Terima kasih!",
  ui_story_5086_50861202_6_dialog_content = "Ini tidak bijaksana.",
  ui_story_5086_50861202_7_dialog_content = "Namun, emosi kadang bertentangan dengan alasan, Minos.",
  ui_story_5086_50861202_8_dialog_content = "...",
  ui_story_5086_50861202_9_dialog_content = "Itu benar. Lanjutkan, Maya!",
  ui_story_5086_50861202_10_dialog_content = "Saya telah terus-menerus menekankan sikap kita terhadap Eclipsites...",
  ui_story_5086_50861202_11_dialog_content = "Saya sadar, Minos.",
  ui_story_5086_50861202_12_dialog_content = "Kejahatan Miss Stellandine tidak dapat dimaafkan, dan oleh karena itu kami menghukumnya.",
  ui_story_5086_50861202_13_dialog_content = "Tapi bagi Maya, dia masih seseorang yang penting yang pernah merawatnya.",
  ui_story_5086_50861202_14_dialog_content = "Meski dia berhasil mengalahkan Miss Stellandine sendiri... Dia masih tidak bisa melepaskan emosi-emosi itu.",
  ui_story_5086_50861202_15_dialog_content = "Ketika berbicara tentang kami dan Eclipsite, kami tidak punya pilihan selain melihat segalanya dalam hitam dan putih.",
  ui_story_5086_50861202_16_dialog_content = "Jika Miss Maya ingin tetap tinggal di Harbour City, pengalaman-pengalaman ini hanya akan mencemarkan hidupnya di sini.",
  ui_story_5086_50861202_17_dialog_content = "... Kecuali jika \"noda\" itu berubah menjadi \"sakit.\"",
  ui_story_5086_50861202_18_dialog_content = "Yang akan membuatnya tampak seperti korban yang tidak bersalah yang telah diperdaya sejak awal.",
  ui_story_5086_50861202_19_dialog_content = "Tunggu... Apakah itu sebabnya kamu dan Nona Stellandine baru saja—",
  ui_story_5086_50861202_20_dialog_content = "Ssst.",
  ui_story_5086_50861202_21_dialog_content = "Tidak peduli seberapa metaforis mereka, dongeng akan selalu populer di kalangan anak-anak.",
  ui_story_5086_50861202_22_dialog_content = "Selama orang benar menang dan orang jahat menderita kekalahan, itu sudah lebih dari cukup sebagai akhir yang bahagia.",
  ui_story_5086_50861202_23_dialog_content = "Berpikir berlebihan hanya akan merampas kebahagiaan murni dari dirimu.",
  ui_story_5086_50861202_24_dialog_content = "...",
  ui_story_5086_50861202_25_dialog_content = "Nona Stellandine...",
  ui_story_5086_50861202_26_dialog_content = "Aku sangat menyesal. Sungguh tidak tahu.",
  ui_story_5086_50861202_27_dialog_content = "Tidak masalah jika itu adalah keinginanmu, rasa sakit, atau sesuatu yang selalu kau tahan...",
  ui_story_5086_50861202_28_dialog_content = "Kalau saja aku menyadarinya lebih awal, mungkin aku bisa membantu...",
  ui_story_5086_50861202_29_dialog_content = "Kamu sungguh bodoh...",
  ui_story_5086_50861202_30_dialog_content = "Tidakkah kamu membenciku setelah mendengar semua itu?",
  ui_story_5086_50861202_31_dialog_content = "Miss Stellandine memberikan tempat tinggal untukku di akuariumnya.",
  ui_story_5086_50861202_32_dialog_content = "Aku tidak akan pernah, pernah lupa!",
  ui_story_5086_50861202_33_dialog_content = "Saya sangat pelupa, jadi saya menolak untuk melepaskan siapa pun begitu saja!",
  ui_story_5086_50861202_34_dialog_content = "Saya bahkan tidak bisa mengingat berapa banyak Aurorian yang telah saya makan.",
  ui_story_5086_50861202_35_dialog_content = "Aku akan membantu kamu menebus.",
  ui_story_5086_50861202_36_dialog_content = "Aku membunuh mereka! Ini bukan urusanmu... Bagaimana kamu akan menebus nyawa yang hilang?",
  ui_story_5086_50861202_37_dialog_content = "Aku tidak bisa mengembalikan orang-orang tak bersalah yang telah tiada, tapi aku berniat untuk membantu setiap orang melewati rasa sakit mereka!",
  ui_story_5086_50861202_38_dialog_content = "May baik itu bersujud kepada mereka atau menebus rasa sakit yang mereka alami, aku akan bekerja keras untuk itu!",
  ui_story_5086_50861202_39_dialog_content = "Jika kamu sedang kelaparan sekarang, kamu bisa mencicipi sedikit dagingku, Miss Stellandine!",
  ui_story_5086_50861202_40_dialog_content = "Aku akan melupakan rasa sakit, dan aku juga akan cepat sembuh!",
  ui_story_5086_50861202_41_dialog_content = "Saya hanya ingin menangis sejadi-jadinya untukmu, orang yang pernah merawat saya, dan saya akan menebusnya kepada semua orang di masa depan.",
  ui_story_5086_50861202_42_dialog_content = "Jadi... Jangan dorong aku pergi...",
  ui_story_5086_50861202_43_dialog_content = "Shush... Jangan katakan hal seperti itu, aku sudah...",
  ui_story_5086_50861202_44_dialog_content = "Kamu tidak punya apa-apa untuk dibayar, anakku... Ini aku yang memiliki hutang untuk dibayar...",
  ui_story_5086_50861202_45_dialog_content = "Jadi, orang benar-benar berbicara dengan tulus saat ini adalah kata-kata terakhir mereka, ya?",
  ui_story_5086_50861202_46_dialog_content = "Kau... sangat mirip dengannya.",
  ui_story_5086_50861202_47_dialog_content = "Mengesankan... Memuji...",
  ui_story_5086_50861202_48_dialog_content = "...",
  ui_story_5086_50861202_49_dialog_content = "Dia mengabaikan nyanyianku dan hanya fokus pada pertempuran melawan badai.",
  ui_story_5086_50861202_50_dialog_content = "Dia terlihat sangat tampan saat dia dengan putus asa menstabilkan kapal di tengah badai yang mengamuk.",
  ui_story_5086_50861202_51_dialog_content = "Aku ingin menunggu kepulangannya, tapi dia tidak pernah kembali... Aku mendarat untuk mencarinya, tapi aku tidak bisa menemukannya...",
  ui_story_5086_50861202_52_dialog_content = "Saya telah bertemu banyak Aurorian, dan banyak wajah baru muncul dalam ingatan saya.",
  ui_story_5086_50861202_53_dialog_content = "Dan seiring berjalannya waktu... Aku sudah tidak bisa lagi membedakan wajah mana yang miliknya.",
  ui_story_5086_50861202_54_dialog_content = "Sepertinya aku masih menunggu, namun semua penantianku...",
  ui_story_5086_50861202_55_dialog_content = "Tidak lebih dari lamunan.",
  ui_story_5086_50861202_56_dialog_content = "A-Aku akan menemukannya untukmu.",
  ui_story_5086_50861202_57_dialog_content = "Tidak... Kamu tidak perlu.",
  ui_story_5086_50861202_58_dialog_content = "Karena aku menemukan seorang gadis kecil tepat di luar akuarium, seorang gadis kecil yang bodoh dan naif yang tidak pernah meragukan siapa pun...",
  ui_story_5086_50861202_59_dialog_content = "Seorang gadis kecil yang berisik yang tidak pernah bisa diam. Dan aku tidak bisa tidak khawatir...",
  ui_story_5086_50861202_60_dialog_content = "Apa yang akan dia lakukan tanpa aku?",
  ui_story_5086_50861202_61_dialog_content = "Aku sudah memikirkannya... Aku sudah memikirkan menjadi Stellandine dan tinggal bersama Maya ku...",
  ui_story_5086_50861202_62_dialog_content = "Tapi aku sangat lapar... Aku benar-benar... kelaparan...",
  ui_story_5086_50861202_63_dialog_content = "...",
  ui_story_5086_50861202_64_dialog_content = "Aku tahu ini akan meremukkan hati Maya... Tapi... Aku hanya monster yang tak bisa melawan kodratnya...",
  ui_story_5086_50861202_65_dialog_content = "Satu-satunya cara bagi saya untuk bertahan hidup adalah dengan memakan Aurorian... Dan apa hasilnya? Hah!",
  ui_story_5086_50861202_66_dialog_content = "Pada akhirnya... saya kehilangan segalanya...",
  ui_story_5086_50861202_67_dialog_content = "Aku benar-benar monster yang menyedihkan...",
  ui_story_5086_50861202_68_dialog_content = "Seandainya saja... aku memiliki hati seorang Aurorian... Maka bisa saja aku memiliki...",
  ui_story_5086_50861202_69_dialog_content = "<color=#e8d9bb>Percikan—</color>",
  ui_story_5086_50861202_70_dialog_content = "?",
  ui_story_5086_50861202_71_dialog_content = "Tempat ini... Kenapa? Bukankah aku...",
  ui_story_5086_50861202_72_dialog_content = "<color=#e8d9bb>Gemuruh-!</color>",
  ui_story_5086_50861202_73_dialog_content = "Badai?! Tidak mungkin!",
  ui_story_5086_50861202_74_dialog_content = "Jangan berpikir untuk membalikkan kapal kita, badai!",
  ui_story_5086_50861202_75_dialog_content = "Teman-teman! Mari tunjukkan pada Poseidon betapa beraninya kita!",
  ui_story_5086_50861202_76_dialog_content = "Mari kita lintasi badai ini! Heave! Ho!",
  ui_story_5086_50861202_77_dialog_content = "Hei! Turun ke sana dan amankan kapal itu!",
  ui_story_5086_50861202_78_dialog_content = "Dan jangan lakukan apa pun lainnya kecuali aku memberi perintah.",
  ui_story_5086_50861202_79_dialog_content = "Aum!",
  ui_story_5086_50861202_80_dialog_content = "Hah? Kapal tiba-tiba menjadi stabil... Sempurna! Ayo buru-buru keluar sekarang!",
  ui_story_5086_50861202_81_dialog_content = "<color=#e8d9bb>Kapal itu perlahan-lahan menghilang ke cakrawala di tengah badai yang menyusut.</color>",
  ui_story_5086_50861202_82_dialog_content = "...",
  ui_story_5086_50861202_83_dialog_content = "Kamu tidak akan mengejar mereka, 'kan?",
  ui_story_5086_50861202_84_dialog_content = "Tidak.",
  ui_story_5086_50861202_85_dialog_content = "Dengan cara ini, saya tidak akan membuat kesalahan yang sama lagi, dan saya tidak akan menyakiti gadis kecil itu lagi.",
  ui_story_5086_50861202_86_dialog_content = "Aku bisa menggali penampilan pelaut itu dari ingatanmu.",
  ui_story_5086_50861202_87_dialog_content = "Setidaknya pada akhirnya, kamu bisa...",
  ui_story_5086_50861202_88_dialog_content = "Ini adalah mimpi yang dibuat oleh anak itu untukku, 'kan?",
  ui_story_5086_50861202_89_dialog_content = "... Iya.",
  ui_story_5086_50861202_90_dialog_content = "Apa aku sedang mati?",
  ui_story_5086_50861202_91_dialog_content = "Baik.",
  ui_story_5086_50861202_92_dialog_content = "Bagus.",
  ui_story_5086_50861202_93_dialog_content = "Monster seperti aku seharusnya mati dengan penyesalan.",
  ui_story_5086_50861202_94_dialog_content = "Aku harus menebus dosa-dosaku dengan menderita sakit yang abadi.",
  ui_story_5086_50861202_95_dialog_content = "Bisakah dia melihat saya?",
  ui_story_5086_50861202_96_dialog_content = "... Tidak.",
  ui_story_5086_50861202_97_dialog_content = "Kemudian katakan padanya itu adalah mimpi yang indah.",
  ui_story_5086_50861202_98_dialog_content = "Jadi...",
  ui_story_5086_50861202_99_dialog_content = "<color=#e8d9bb>Guyuran.</color>",
  ui_story_5086_50861202_100_dialog_content = "<color=#e8d9bb>Kata-kataku disambut dengan dorongan mendadak yang menjauhkan diriku dan percikan cahaya di lautan.</color>",
  ui_story_5086_50861202_101_dialog_content = "<color=#e8d9bb>Stellandine tenggelam ke dalam air dan sosoknya perlahan kabur saat hubungan terputus.</color>",
  ui_story_5086_50861202_102_dialog_content = "<color=#e8d9bb>Dia lahir dari lautan, dan sekarang, sepertinya dia telah kembali ke dalam pelukannya. Tanpa gerakan... hanya tenggelam, dan tenggelam ke dasar.</color>",
  ui_story_5086_50861202_103_dialog_content = "Stellandine!",
  ui_story_5086_50861202_104_dialog_content = "Hmm-hmm.",
  ui_story_5086_50861202_105_dialog_content = "<color=#e8d9bb>Mengabaikan panggilan dan penghalangan saya, monster itu mulai bernyanyi sambil tenggelam ke dalam jurang.</color>",
  ui_story_5086_50861202_106_dialog_content = "<color=#e8d9bb>Lagu sirene bisa menipu pikiran dan menjadikan semua yang mendengarnya sebagai mangsa.</color>",
  ui_story_5086_50861202_107_dialog_content = "<color=#e8d9bb>Tapi melodi ini tidak membahayakan siapa pun.</color>",
  ui_story_5086_50861202_108_dialog_content = "<color=#e8d9bb>Ini hanya... Sebuah berkah sedih dan lembut dari kedalaman laut yang dingin.</color>",
  ui_story_5086_50861202_109_dialog_content = "Maya-ku... yang malang... menggemaskan... kecil...",
  ui_story_5086_50861202_110_dialog_content = "May kamu... hidup bahagia... dengan orang yang kamu cintai.",
  ui_story_5086_50861202_111_dialog_content = "<color=#e8d9bb>Tubuh Stellandine mulai memudar di lobi akuarium.</color>",
  ui_story_5086_50861202_112_dialog_content = "Benar bahwa aku bisa merasakan baik dan jahat dalam seseorang.",
  ui_story_5086_50861202_113_dialog_content = "Jadi, meski aku pelupa, aku tidak bisa ditipu begitu saja.",
  ui_story_5086_50861202_114_dialog_content = "Nona Stellandine adalah seorang Eclipsite, tapi sejak hari kami bertemu, dan bahkan baru saja...",
  ui_story_5086_50861202_115_dialog_content = "Dia tidak pernah memiliki niat jahat sedikit pun terhadapku.",
  ui_story_5086_50861202_116_dialog_content = "Jadi, yang paling tidak bisa saya lakukan adalah memberinya mimpi indah, bukan?",
  ui_story_5086_50861202_117_dialog_content = "Baik.",
  ui_story_5086_50861202_118_dialog_content = "Di masa lalu, dia tidak bisa melepaskan keinginannya untuk bertahan hidup, juga tidak bisa menyerah dengan pikiran-pikirannya yang penuh harapan.",
  ui_story_5086_50861202_119_dialog_content = "Tapi ketika dia melepaskan semuanya dan kehilangan segalanya, dia masih bersedia memberikan berkat tulusnya...",
  ui_story_5086_50861202_120_dialog_content = "Menurut pendapat saya, dia bertobat, dan jadi dia bukan lagi hanya monster.",
  ui_story_5086_50861202_121_dialog_content = "Dia mendambakan hati seorang Aurorian, dan sekarang, di saat kematiannya, dia bisa secara bertahap membayar semuanya kembali.",
  ui_story_5086_50861202_122_dialog_content = "<color=#e8d9bb>Di kedalaman laut yang sunyi, mimpi.</color>",
  ui_story_5086_50861202_123_dialog_content = "<color=#e8d9bb>Tiba-tiba, sinar cahaya yang mempesona muncul di depan sosok Stellandine yang tenggelam.</color>",
  ui_story_5086_50861202_124_dialog_content = "<color=#e8d9bb>Seorang pelaut mengulurkan tangan kepadanya dari dalam cahaya, wajah tampannya jelas terpantul di matanya.</color>",
  ui_story_5086_50861202_125_dialog_content = "Ikutlah denganku.",
  ui_story_5086_50861202_126_dialog_content = "... Oke.",
  ui_story_5086_50861202_127_dialog_content = "<color=#e8d9bb>Stellandine tersenyum sebelum benar-benar menghilang.</color>",
  ui_story_5086_50861202_128_dialog_content = "Terima kasih, PlayerName.",
  ui_story_5086_50861202_129_dialog_content = "Um... Aku tidak tahu bagaimana mengatakannya, tapi terima kasih untuk semuanya.",
  ui_story_5086_50861202_130_dialog_content = "Sama sekali tidak. Saya hanya membantu Nona Stellandine mengingat wajah pelaut itu.",
  ui_story_5086_50861202_131_dialog_content = "Sebenarnya, kaulah yang memberikan keselamatan kepada Miss Stellandine, Maya.",
  ui_story_5086_50861202_132_dialog_content = "Karena cinta itu abadi...",
  ui_story_5086_50861202_133_dialog_content = "Oh, ya! Catatan saya!",
  ui_story_5086_50861202_134_dialog_content = "Saya harus menuliskannya... Ah!",
  ui_story_5086_50861202_135_dialog_content = "<color=#e8d9bb>Ketika Maya mencari-cari catatannya, sebuah kartu jatuh dari balik sampulnya.</color>",
  ui_story_5086_50861202_136_dialog_content = "Apakah itu... Origin Deck milik Jeno?!",
  ui_story_5086_50861300_1_dialog_content = "<color=#e8d9bb>Setelah insiden sirkus—</color>",
  ui_story_5086_50861300_2_dialog_content = "Jeno...",
  ui_story_5086_50861300_3_dialog_content = "Tidak akan ada pertunjukan lagi.",
  ui_story_5086_50861300_4_dialog_content = "Aku tahu kamu bisa membaca pikiran, Jeno!",
  ui_story_5086_50861300_5_dialog_content = "Tidak, itu karena kamu akan bertanya jika ada orang yang mencari bantuanmu.",
  ui_story_5086_50861300_6_dialog_content = "Mari kita tinggalkan Harbour City setelah Emerald diperbaiki.",
  ui_story_5086_50861300_7_dialog_content = "Huh? Tapi begitu banyak yang menantikan pertunjukan ini, dan... Elvis...",
  ui_story_5086_50861300_8_dialog_content = "Elvis adalah alasan kita harus pergi.",
  ui_story_5086_50861300_9_dialog_content = "Ikut denganku, Maya.",
  ui_story_5086_50861300_10_dialog_content = "Keberangkatanku sudah ditetapkan, tapi kamu baru, jadi aku tidak akan memaksamu.",
  ui_story_5086_50861300_11_dialog_content = "Jadi, kamu ikut dengan kami? Atau kamu akan tetap di sini?",
  ui_story_5086_50861300_12_dialog_content = "Jika aku pergi denganmu, bisakah aku membantu kamu dan Elvis?",
  ui_story_5086_50861300_13_dialog_content = "Sepertinya sulit bagiku karena kamu tidak dapat mengendalikan kekuatanmu.",
  ui_story_5086_50861300_14_dialog_content = "Oke...",
  ui_story_5086_50861300_15_dialog_content = "Aku mengerti! Aku akan tetap di sini saja!",
  ui_story_5086_50861300_16_dialog_content = "Elvis selalu menjagaku, dan sekarang saatnya saya membantunya menjaga Harbour City.",
  ui_story_5086_50861300_17_dialog_content = "Mungkin saya bukan yang paling dapat diandalkan... Tapi saya berjanji akan melakukan yang terbaik untuk membantu setiap orang!",
  ui_story_5086_50861300_18_dialog_content = "Sekarang bahwa Elvis tidak lagi menjadi Tuan Kota, dia tidak bisa mengirim siapa pun untuk melindungi kamu lagi.",
  ui_story_5086_50861300_19_dialog_content = "Kamu harus hidup mandiri seperti biasanya.",
  ui_story_5086_50861300_20_dialog_content = "Aku adalah pekerja keras, jadi aku tidak akan kelaparan! Jangan khawatirkan aku! Aku memiliki banyak pengalaman kerja! Meskipun sepertinya aku telah melupakannya semua...",
  ui_story_5086_50861300_21_dialog_content = "Namun...",
  ui_story_5086_50861300_22_dialog_content = "Miss Stellandine dari akuarium sangat baik hati. Saya mendapatkan banyak uang di sana!",
  ui_story_5086_50861300_23_dialog_content = "Kamu harus fokus pada hal-hal yang lebih penting, Jeno!",
  ui_story_5086_50861300_24_dialog_content = "Lalu, aku ingin meminta bantuanmu.",
  ui_story_5086_50861300_25_dialog_content = "Saya tidak keberatan bahkan seratus bantuan!",
  ui_story_5086_50861300_26_dialog_content = "Ini tidak hebat. Aku hanya butuh kamu untuk menyampaikan pesan.",
  ui_story_5086_50861300_27_dialog_content = "Yah... Aku takut aku akan melupakannya...",
  ui_story_5086_50861300_28_dialog_content = "Itulah yang membuat Anda begitu dapat diandalkan.",
  ui_story_5086_50861300_29_dialog_content = "Hiduplah dengan baik di akuarium. Kami akan datang melihatmu suatu hari nanti.",
  ui_story_5086_50861300_30_dialog_content = "Jadi... apakah itu berarti Maya adalah kurir dari Jeno, setelah semua?",
  ui_story_5086_50861300_31_dialog_content = "Sebuah pesan?",
  ui_story_5086_50861300_32_dialog_content = "Aku tidak ingat ada sesuatu seperti itu...",
  ui_story_5086_50861300_33_dialog_content = "Tapi aku samar-samar ingat sesuatu tentang merawat kartu ini dengan baik.",
  ui_story_5086_50861300_34_dialog_content = "Apakah aku kembali melupakan sesuatu yang penting?",
  ui_story_5086_50861300_35_dialog_content = "Tidak, saya pikir itu bagian dari trik Jeno.",
  ui_story_5086_50861300_36_dialog_content = "Kebanyakan hanya memperhatikan air yang misterius menghilang dari cangkir.",
  ui_story_5086_50861300_37_dialog_content = "Tapi di mata seorang pesulap, itu se-simple mengambil gelas kosong dari bawah meja.",
  ui_story_5086_50861300_38_dialog_content = "Aku paham! Teka-teki itu selalu ada di depan kita! Meski tidak ada yang bisa menemukannya selain aku!",
  ui_story_5086_50861300_39_dialog_content = "PlayerName, apakah kamu akan menarik sesuatu keluar?",
  ui_story_5086_50861300_40_dialog_content = "Ini kenanganmu.",
  ui_story_5086_50861300_41_dialog_content = "Oh, tapi jangan khawatir. Jeno tidak akan meninggalkan Deck Origin begitu saja.",
  ui_story_5086_50861300_42_dialog_content = "Jika saya menggunakannya sebagai panduan saya, saya seharusnya bisa menemukan pesan tersebut tanpa menyentuh kenangan lain Anda.",
  ui_story_5086_50861300_43_dialog_content = "Tak apa.",
  ui_story_5086_50861300_44_dialog_content = "Ha?",
  ui_story_5086_50861300_45_dialog_content = "PlayerName, meskipun kamu menolak pakaian bagus, permata, dan bahkan mutiara...",
  ui_story_5086_50861300_46_dialog_content = "Tapi kamu selalu diterima untuk menikmati dirimu sendiri dalam mimpi-mimpiku, para Leluhur telah mengizinkannya!",
  ui_story_5086_50861300_47_dialog_content = "Ini akan menjadi kehormatan saya.",
  ui_story_5086_50861300_48_dialog_content = "Lalu—",
  ui_story_5086_50861300_49_option_content = "Mindlink!",
  ui_story_5086_50861300_50_dialog_content = "(Fokus! Fokus pada gelombang yang sinkron dengan Origin Deck...)",
  ui_story_5086_50861300_51_dialog_content = "(Ketemu!)",
  ui_story_5086_50861300_52_dialog_content = "Kaulah satu-satunya yang bisa sampai di sini, jadi aku akan langsung ke pokoknya.",
  ui_story_5086_50861300_53_dialog_content = "Elvis sudah bangun.",
  ui_story_5086_50861300_54_dialog_content = "(!)",
  ui_story_5086_50861300_55_dialog_content = "Meski hanya sebentar, dan dia langsung tertidur setelahnya, itu sudah cukup untuk membuktikan bahwa metode pengobatan <color=#FFB400>wanita itu</color> berjalan ke arah yang benar.",
  ui_story_5086_50861300_56_dialog_content = "Elvis... tidak pernah mempertimbangkan gambaran besar. Dia hanya menyerang secara buta pada pandangan bahkan kilauan harapan dan meninggalkan setiap orang di belakang.",
  ui_story_5086_50861300_57_dialog_content = "Dia adalah pria yang benar-benar egois namun benar.",
  ui_story_5086_50861300_58_dialog_content = "Tapi saya tidak memiliki hak untuk berbicara buruk tentang dia. Karena tidak peduli apa yang dia lakukan, saya merasa tidak mungkin untuk membencinya.",
  ui_story_5086_50861300_59_dialog_content = "Jadi, pilihan satu-satunya adalah menjadi kaki tangannya.",
  ui_story_5086_50861300_60_dialog_content = "Aku akan membawanya ke tahap berikutnya dalam perawatannya.",
  ui_story_5086_50861300_61_dialog_content = "Caelestite, saya mungkin membutuhkan bantuanmu untuk memastikan kesadaran Elvis tetap utuh.",
  ui_story_5086_50861300_62_dialog_content = "Itulah sebabnya saya membuat Maya menyampaikan informasi ini kepada Anda.",
  ui_story_5086_50861300_63_dialog_content = "Tolong jaga ini sebagai rahasia dari siapa pun yang terhubung dengan Lumopolis, termasuk teman-temanmu.",
  ui_story_5086_50861300_64_dialog_content = "Saya akan mencari cara untuk menghubungi kamu ketika saatnya tepat.",
  ui_story_5086_50861300_65_dialog_content = "Itu saja?",
  ui_story_5086_50861300_66_dialog_content = "Hmm... Tidak, ada satu hal lagi.",
  ui_story_5086_50861300_67_dialog_content = "Saya bukan pemimpin yang hebat, jadi saya memikirkan untuk meninggalkan sirkus. Sayangnya, Emerald penuh dengan orang-orang yang keras kepala dan tidak fleksibel.",
  ui_story_5086_50861300_68_dialog_content = "Mereka bersikeras mengikutiku, dan jika saya menambahkan Elvis ke dalam persamaan... Yah, kesimpulannya adalah kita meninggalkan Maya sendirian di Harbor City.",
  ui_story_5086_50861300_69_dialog_content = "Aku mendengar Elvis berjanji pada ayahnya bahwa dia akan selalu ada untuknya.",
  ui_story_5086_50861300_70_dialog_content = "Jadi, aku tidak punya pilihan selain meminta kamu untuk membantu kami dengan itu.",
  ui_story_5086_50861300_71_dialog_content = "Jangan khawatir, aku akan baik-baik saja!",
  ui_story_5086_50861300_72_dialog_content = "Maya... Apakah kamu benar-benar tidak ikut dengan kami?",
  ui_story_5086_50861300_73_dialog_content = "Huu-huu... Aku akan merindukanmu...",
  ui_story_5086_50861300_74_dialog_content = "(Mari kita berhenti di sini.)",
  ui_story_5086_50861300_75_dialog_content = "Sehat?",
  ui_story_5086_50861300_76_dialog_content = "Apakah Anda menemukan apa yang Anda cari?",
  ui_story_5086_50861300_77_dialog_content = "Ya! Terima kasih, Maya. Kamu benar-benar telah membantuku di sana.",
  ui_story_5086_50861300_78_dialog_content = "Luar biasa!",
  ui_story_5086_50861300_79_dialog_content = "Pokoknya... Sekarang bahwa Miss Stellandine sudah pergi...",
  ui_story_5086_50861300_80_dialog_content = "Maukah kamu ikut denganku?",
  ui_story_5086_50861300_81_dialog_content = "Meski aku tidak bisa memberimu yang terbaik, ada banyak ruangan kosong di Colossus...",
  ui_story_5086_50861300_82_dialog_content = "Aku benar-benar menyukaimu, PlayerName!",
  ui_story_5086_50861300_83_dialog_content = "Hah?! Darimana itu datang...",
  ui_story_5086_50861300_84_dialog_content = "Heehee! Tapi saya juga suka Elvis, laut, dan Harbour City.",
  ui_story_5086_50861300_85_dialog_content = "Dan bahkan jika saya harus merahasiakannya...",
  ui_story_5086_50861300_86_dialog_content = "Saya juga sangat menyukai Miss Stellandine!",
  ui_story_5086_50861300_87_dialog_content = "Untuk alasan itu, saya ingin tinggal dan menjaga akuarium ini tetap hidup.",
  ui_story_5086_50861300_88_dialog_content = "Akuarium akan selalu menjadi rumahku.",
  ui_story_5086_50861300_89_dialog_content = "Dan aku akan berusaha sebaik mungkin untuk menebus segalanya dan menyembuhkan luka semua orang, sehingga kita semua bisa tersenyum lagi.",
  ui_story_5086_50861300_90_dialog_content = "Baiklah... Jika saya pernah bertemu dengan dokter yang mampu mengobati kehilangan ingatanmu, kamu bisa yakin saya akan membawanya kepadamu.",
  ui_story_5086_50861300_91_dialog_content = "Terima kasih, meski kau benar-benar tidak perlu khawatir tentang itu.",
  ui_story_5086_50861300_92_dialog_content = "Saya yakin bahwa saya akan dapat menjalani hidup yang lebih baik.",
  ui_story_5086_50861300_93_dialog_content = "Juga, <color=#FFB400>Aku</color> sudah mengetahui beberapa hal.",
  ui_story_5086_50861300_94_dialog_content = "Benda apa?",
  ui_story_5086_50861300_95_dialog_content = "Hehe! <color=#FFB400>Aku</color> mencatatnya di catatanku. Aku akan membiarkan kamu membacanya ketika kita bertemu lagi.",
  ui_story_5086_50861300_96_dialog_content = "Tapi, ini rahasia untuk sekarang!",
  ui_story_5086_50861300_97_dialog_content = "<color=#e8d9bb>Para ksatria Lumopolis mengambil alih pekerjaan yang tersisa.</color>",
  ui_story_5086_50861300_98_dialog_content = "<color=#e8d9bb>Orang-orang yang maju mendapatkan reward dan pergi.</color>",
  ui_story_5086_50861300_99_dialog_content = "<color=#e8d9bb>Dan pengunjung yang lelah itu pergi setelah menceritakan semua yang mereka ketahui.</color>",
  ui_story_5086_50861300_100_dialog_content = "<color=#e8d9bb>Setelah semua karyawan pergi, Maya ditinggalkan sendirian di akuarium pada malam hari... Dan ada satu lagi yang diam-diam kembali.</color>",
  ui_story_5086_50861300_101_dialog_content = "Halo, Miss Maya.",
  ui_story_5086_50861300_102_dialog_content = "Tuan Minos? Apa yang kamu lakukan kembali di sini? Apakah kamu lupa sesuatu?",
  ui_story_5086_50861300_103_dialog_content = "Aku hanya ingin mengonfirmasi sesuatu.",
  ui_story_5086_50861300_104_dialog_content = "Hah? Maksudnya apa?",
  ui_story_5086_50861300_105_dialog_content = "Lalu izinkan saya menjelaskan secara singkat.",
  ui_story_5086_50861300_106_dialog_content = "Kamu menceritakan sebuah cerita kepada anak-anak.",
  ui_story_5086_50861300_107_dialog_content = "Ini adalah tentang seorang anak laki-laki dan monster laut di sebuah kota kecil...",
  ui_story_5086_50861300_108_dialog_content = "Apakah saya pernah menceritakan kisah seperti itu? Terdengar sangat menarik!",
  ui_story_5086_50861300_109_dialog_content = "Memang begitu. Nona Maya, imajinasimu benar-benar bebas dan penuh warna.",
  ui_story_5086_50861300_110_dialog_content = "Tapi aku merasa senang bisa membaca cerita aslinya.",
  ui_story_5086_50861300_111_dialog_content = "Dalam cerita aslinya, setelah anak laki-laki itu tumbuh dewasa, dia pergi mencari kota itu lagi.",
  ui_story_5086_50861300_112_dialog_content = "Tapi tidak peduli berapa banyak pantai dan hutan yang dia lintasi, dia tidak pernah bisa menemukan jalan kembali ke sana.",
  ui_story_5086_50861300_113_dialog_content = "Ternyata kota itu berada di antara celah-celah mimpi, dan hanya diproyeksikan ke dalam kenyataan ketika seseorang melihat atau mengamatinya.",
  ui_story_5086_50861300_114_dialog_content = "Anak laki-laki dan gadis yang menangis menjadi teman, dan dia membantu orang-orang membasmi monster laut. Namun, tidak ada pengunjung yang pernah mengunjungi kota itu lagi.",
  ui_story_5086_50861300_115_dialog_content = "Seiring berjalannya waktu, kota itu sendiri menghilang.",
  ui_story_5086_50861300_116_dialog_content = "Jika itu terjadi, kira-kira kucing itu akan menyesal telah menyeret anak laki-laki itu ke dalam semua ini?",
  ui_story_5086_50861300_117_dialog_content = "Kucing itu memiliki kekuatan yang luar biasa, dan \"pikiran\"nya akan mempengaruhi penilaianku tentang beberapa hal.",
  ui_story_5086_50861300_118_dialog_content = "Aku... sebenarnya tidak begitu mengerti cerita Anda, Tuan Minos.",
  ui_story_5086_50861300_119_dialog_content = "Tapi gadis yang menangis sendirian setiap hari mendapatkan seorang teman karena anak laki-laki itu.",
  ui_story_5086_50861300_120_dialog_content = "Dan para pengunjung yang tertarik ke sana oleh legenda tampaknya telah pergi setelah menikmati diri mereka sepenuhnya.",
  ui_story_5086_50861300_121_dialog_content = "Pada akhirnya, setiap orang dari mimpi itu kembali ke tempat asal mereka.",
  ui_story_5086_50861300_122_dialog_content = "Jadi mungkin kucing itu... tidak memikirkan apa-apa tentang itu.",
  ui_story_5086_50861300_123_dialog_content = "Meskipun ada beberapa penyesalan, setiap orang telah berusaha sebaik mungkin, dan itu membuatnya menjadi akhir yang bahagia.",
  ui_story_5086_50861300_124_dialog_content = "Akhir yang baik... Huh?",
  ui_story_5086_50861300_125_dialog_content = "Jika harus saya katakan, kucing itu pasti ingin bertemu lagi dengan anak laki-laki itu.",
  ui_story_5086_50861300_126_dialog_content = "Ingin sekali berjalan-jalan lagi di pantai bersama.",
  ui_story_5086_50861300_127_dialog_content = "Lihatlah ombak yang pecah di atas terumbu karang, ikan terbang yang melompat keluar dari air, dan berguling di pasir sambil tertawa saat melihat kepiting yang canggung berjalan bolak-balik.",
  ui_story_5086_50861300_128_dialog_content = "Dan di akhir hari, mereka akan meringkuk di bawah pohon palem dan membiarkan angin laut membawa mereka tertidur.",
  ui_story_5086_50861300_129_dialog_content = "Apakah itu keinginan kucing saat ini?",
  ui_story_5086_50861300_130_dialog_content = "Itu bisa mewujudkan keinginan itu dengan pergi bersama anak laki-laki itu.",
  ui_story_5086_50861300_131_dialog_content = "Tapi rumah kucing itu ada di kota.",
  ui_story_5086_50861300_132_dialog_content = "Jadi, kucing itu akan menunggu sampai anak laki-laki itu kembali. Lagi pula...",
  ui_story_5086_50861300_133_dialog_content = "Cinta itu abadi.",
  ui_story_5086_50861300_134_dialog_content = "Aku paham sekarang. Terima kasih, itu semua yang ingin aku tanyakan.",
  ui_story_5086_50861300_135_dialog_content = "Nah, aku akan kembali untuk melaporkan hasil investigasi bisnis kepada Nona Nina. Selamat tinggal!",
  ui_story_5086_50861300_136_dialog_content = "...",
  ui_story_5086_50861300_137_dialog_content = "Semoga kucing itu mendapatkan apa yang dia inginkan.",
  ui_story_5086_50861300_138_dialog_content = "Jangan bersedih.",
  ui_story_5086_50861300_139_dialog_content = "Karena dongeng...",
  ui_story_5086_50861300_140_dialog_content = "Selalu ada akhir yang bahagia.",
  ui_story_5086_50861300_141_dialog_content = "Hei! Apa kamu mencoba untuk membunuh diri sendiri?",
  ui_story_5086_50861300_142_dialog_content = "Argh! Aku tertangkap?!",
  ui_story_5086_50861300_143_dialog_content = "Jangan berlarian di bawah angin laut saat kamu masih sakit.",
  ui_story_5086_50861300_144_dialog_content = "Aku sudah cukup tidur, Jeno. Aku ingin memandangi rumahku saat aku terjaga.",
  ui_story_5086_50861300_145_dialog_content = "Aku ingin tahu bagaimana keadaan Maya?",
  ui_story_5086_50861300_146_dialog_content = "Garis keturunan Naga Mirage, yang terakhir dari klan Mirage...",
  ui_story_5086_50861300_147_dialog_content = "Dan kamu telah memverifikasi bahwa gelangnya mengandung jenggot naga asli.",
  ui_story_5086_50861300_148_dialog_content = "Tidak ada yang bisa menghentikannya.",
  ui_story_5086_50861300_149_dialog_content = "Memang. Ini adalah barang legendaris yang ayahnya dapatkan dari Sanctum setelah melewati banyak sekali ujian.",
  ui_story_5086_50861300_150_dialog_content = "Aku tidak khawatir tentang keselamatannya.",
  ui_story_5086_50861300_151_dialog_content = "Aku hanya... tidak ingin dia pernah kehilangan senyumnya.",
  ui_story_5086_50861300_152_dialog_content = "Saya berharap Harbour City, dan saya layak untuk dongeng indahnya.",
  ui_story_5086_50861300_153_dialog_content = "Lalu, berusahalah sebaik mungkin untuk menebus kesalahanmu setelah kamu sembuh.",
  ui_story_5086_50861300_154_dialog_content = "Menebus semua kesalahan.",
  ui_story_5086_50861300_155_dialog_content = "... Aku akan ada di sisi kamu.",
  ui_story_5086_50861300_156_dialog_content = "Baiklah."
}
return config
